import { Book } from "@/lib/types";

export const joshua: Book = {
  id: "joshua",
  name: "Josua",
  shortName: "Jos",
  testament: "old",
  chapters: [
    { number: 1, verses: [
      { number: 1, text: "Und es geschah nach dem Tod des Mose, des Knechtes des HERRN*, da sprach der HERR zu Josua, dem Sohn des Nun*, dem Diener des Mose*:", heading: "Zuspruch Gottes an Josua", footnotes: ["℘ 5Mo 34,5", "℘ Neh 8,17", "℘ 2Mo 24,13"] },
      { number: 2, text: "Mein Knecht Mose ist gestorben. So mache dich nun auf und gehe über diesen Jordan*, du und dieses ganze Volk, in das Land, das ich ihnen, den Söhnen Israel, gebe*!", footnotes: ["℘ 5Mo 3,28", "℘ 1Mo 17,8; Neh 9,23"] },
      { number: 3, text: "Jeden Ort, auf den eure Fußsohle treten wird — euch habe ich ihn gegeben, wie ich zu Mose geredet habe*.", footnotes: ["℘ Kap. 14,9; 5Mo 11,24"] },
      { number: 4, text: "Von der Wüste und diesem Libanon an bis zum großen Strom, dem Strom Euphrat, das ganze Land der Hetiter*, und bis zum großen Meer gegen Sonnenuntergang, das soll euer Gebiet sein*.", footnotes: ["℘ 1Kö 10,29", "℘ 1Mo 15,18"] },
      { number: 5, text: "Es soll niemand vor dir standhalten können, alle Tage deines Lebens*. Wie ich mit Mose gewesen bin, werde ich mit dir sein*; ich werde dich nicht aufgeben und dich nicht verlassen*.", footnotes: ["℘ Kap. 10,8; 21,44; 5Mo 7,24", "℘ Kap. 3,7; 6,27; 1Mo 39,2.3; 5Mo 20,1; 31,23; 1Sam 10,7; Apg 18,10", "℘ 5Mo 31,6.8"] },
      { number: 6, text: "Sei stark und mutig!* Denn du, du sollst diesem Volk das Land als Erbe austeilen*, das ihnen zu geben ich ihren Vätern geschworen habe*.", footnotes: ["℘ V. 18; Kap. 10,25; 1Chr 28,20; 2Chr 15,7; Dan 10,19; Hag 2,4; 2Tim 2,1", "℘ Kap. 13,6; 4Mo 26,53", "℘ Kap. 5,6; 18,3; 21,43; 1Mo 12,7; 5Mo 1,8.35; 2Chr 20,7.11; Apg 7,5; Gal 3,16"] },
      { number: 7, text: "Nur sei recht stark und mutig, dass du darauf achtest, nach dem ganzen Gesetz zu handeln, das mein Knecht Mose dir geboten hat*! Weiche nicht davon ab, weder zur Rechten noch zur Linken*, damit du überall Erfolg hast*, wo immer du gehst!", footnotes: ["℘ Kap. 11,15; 5Mo 4,2", "℘ Kap. 23,6; 5Mo 5,32; Hebr 13,9", "o. Einsicht hast; o. klug handelst"] },
      { number: 8, text: "Dieses Buch des Gesetzes soll nicht von deinem Mund weichen, und du sollst Tag und Nacht darüber nachsinnen*, damit du darauf achtest, nach alledem zu handeln, was darin geschrieben ist*; denn dann wirst du auf deinen Wegen zum Ziel gelangen, und dann wirst du Erfolg haben*.", footnotes: ["℘ Ps 119,97; 1Tim 4,15", "w. nach all dem darin Geschriebenen zu handeln\n℘ 5Mo 5,1; 17,18.19", "℘ 5Mo 29,8; 2Chr 26,5; Ps 1,2.3"] },
      { number: 9, text: "Habe ich dir nicht geboten: Sei stark und mutig*? Erschrick nicht* und fürchte dich nicht*! Denn mit dir ist der HERR*, dein Gott, wo immer du gehst*.", footnotes: ["℘ Kap. 3,7; 6,27; 1Mo 39,2.3; 5Mo 20,1; 31,23; 1Sam 10,7; Apg 18,10", "o. Sei nicht niedergeschlagen", "℘ Kap. 8,1; 10,8; 5Mo 1,21.29; 1Chr 28,20; Jes 8,12; Hag 2,5", "℘ Kap. 8,1; 10,8; 5Mo 1,21.29; 1Chr 28,20; Jes 8,12; Hag 2,5", "℘ Jer 1,8"] },
      { number: 10, text: "Da befahl Josua den Aufsehern* des Volkes:", heading: "Vorbereitungen der Stämme für die Überquerung des Jordan", footnotes: ["w. Schreibern; d. i. eine Beamtenbezeichnung"] },
      { number: 11, text: "Geht mitten durch das Lager und befehlt dem Volk und sprecht: Versorgt euch mit Wegzehrung, denn in noch drei Tagen werdet ihr über diesen Jordan ziehen*, um hineinzugehen, das Land einzunehmen*, das der HERR, euer Gott, euch gibt, es zu besitzen!", footnotes: ["℘ Kap. 3,2.3", "℘ 5Mo 3,18; 9,1"] },
      { number: 12, text: "Und zu den Rubenitern und den Gaditern und zum halben Stamm Manasse* sagte Josua:", footnotes: ["℘ Kap. 22,1; 1Chr 5,18; 26,32"] },
      { number: 13, text: "Denkt an das Wort, das Mose, der Knecht des HERRN, euch geboten hat, indem er sagte: Der HERR, euer Gott, schafft euch Ruhe und gibt euch dieses Land!" },
      { number: 14, text: "Eure Frauen, eure Kinder und euer Vieh* sollen in dem Land bleiben, das Mose euch diesseits* des Jordan gegeben hat. Ihr aber, all ihr tüchtigen Krieger, sollt gerüstet vor euren Brüdern hinüberziehen und ihnen helfen*,", footnotes: ["o. Besitz", "w. jenseits (d. h. vom Standpunkt des Betrachters aus)", "℘ Kap. 4,12.13"] },
      { number: 15, text: "bis der HERR euren Brüdern Ruhe schafft wie euch und auch sie das Land in Besitz nehmen*, das der HERR, euer Gott, ihnen gibt. Dann sollt ihr in euer eigenes Land* zurückkehren und es besitzen, das Mose, der Knecht des HERRN, euch gegeben hat, diesseits* des Jordan, gegen Sonnenaufgang*.", footnotes: ["℘ 5Mo 3,18; 9,1", "w. in das Land eures Besitztums", "w. jenseits (d. h. vom Standpunkt des Betrachters aus)", "℘ Kap. 22,1-4; 4Mo 32,20-24; 5Mo 3,18-20"] },
      { number: 16, text: "Und sie antworteten Josua: Alles, was du uns geboten hast, werden wir tun, und wohin immer du uns sendest, werden wir hingehen*.", footnotes: ["℘ 4Mo 32,25.27; Esr 10,4"] },
      { number: 17, text: "Ganz wie wir Mose gehorcht haben, so werden wir dir gehorchen*. Nur möge der HERR, dein Gott, mit dir sein, wie er mit Mose gewesen ist*!", footnotes: ["℘ Kap. 4,14; 4Mo 27,18-20; 5Mo 34,9", "℘ 1Sam 17,37; 2Sam 14,17; 1Kö 1,37"] },
      { number: 18, text: "Jeder, der sich deinem Befehl* widersetzt und nicht auf deine Worte hört in allem, was du uns befiehlst, soll getötet werden*. Nur sei stark und mutig*!", footnotes: ["w. Mund", "℘ 5Mo 17,12; Röm 13,1-5", "℘ V. 6.9"] },
    ]},
    { number: 2, verses: [
      { number: 1, text: "Und Josua, der Sohn des Nun, sandte von Schittim* heimlich zwei Männer als Kundschafter* aus und sagte: Geht, seht euch das Land an und Jericho*! Da gingen sie hin und kamen in das Haus einer Hure; ihr Name war Rahab*. Und sie legten sich dort schlafen.", heading: "Die Kundschafter in Jericho", footnotes: ["℘ Kap. 3,1; 4Mo 25,1", "℘ 4Mo 13,1-3; Ri 1,23", "℘ Kap. 6,1; 4Mo 13,17-20", "℘ Mt 1,5"] },
      { number: 2, text: "Das wurde jedoch dem König von Jericho berichtet: Siehe, in dieser Nacht sind Männer von den Söhnen Israel hierhergekommen, um das Land zu erkunden*.", footnotes: ["℘ Ri 18,2"] },
      { number: 3, text: "Da schickte der König von Jericho zu Rahab und ließ ihr sagen: Gib die Männer heraus, die zu dir gekommen und in dein Haus eingekehrt sind! Denn um das ganze Land zu erkunden, sind sie gekommen." },
      { number: 4, text: "Die Frau aber nahm die beiden Männer und versteckte sie*. Und sie sagte: Ja, die Männer sind zu mir gekommen, aber ich habe nicht erkannt, woher sie waren.", footnotes: ["℘ Kap. 6,17.25"] },
      { number: 5, text: "Als nun das Tor bei Einbruch der Dunkelheit geschlossen werden sollte, da gingen die Männer wieder hinaus; ich habe nicht erkannt, wohin die Männer gegangen sind*. Jagt ihnen eilends nach, dann werdet ihr sie einholen! —", footnotes: ["℘ 1Sam 19,14"] },
      { number: 6, text: "Sie hatte sie aber auf das Dach hinaufgeführt und unter den Flachsstängeln versteckt, die sie sich auf dem Dach aufgeschichtet hatte*.", footnotes: ["℘ 2Sam 17,19.20"] },
      { number: 7, text: "Da jagten ihnen die Männer nach, auf dem Weg zum Jordan, bis zu den Furten*. Und man schloss das Tor, sobald die, die ihnen nachjagten, draußen waren.", footnotes: ["℘ Ri 3,28"] },
      { number: 8, text: "Aber bevor sie sich schlafen legten, stieg sie zu ihnen auf das Dach hinauf" },
      { number: 9, text: "und sagte zu den Männern: Ich habe erkannt, dass der HERR euch das Land gegeben hat* und dass der Schrecken vor euch* auf uns gefallen ist, so dass alle Bewohner des Landes vor euch mutlos geworden sind*.", footnotes: ["℘ Hebr 11,1.31", "w. euer Schrecken", "℘ V. 24; Kap. 5,1; 9,24; 2Mo 15,15.16; Neh 6,16; Est 8,17"] },
      { number: 10, text: "Denn wir haben gehört, dass der HERR das Wasser des Schilfmeeres vor euch ausgetrocknet hat, als ihr aus Ägypten zogt*, und was ihr den beiden Königen der Amoriter getan habt, die jenseits des Jordan waren, dem Sihon und dem Og, an denen ihr den Bann vollstreckt habt*.", footnotes: ["℘ 2Mo 14,21", "℘ Kap. 9,10; 24,12"] },
      { number: 11, text: "Als wir es hörten, da zerschmolz unser Herz, und in keinem blieb noch Mut euch gegenüber*. Denn der HERR, euer Gott, ist Gott oben im Himmel und unten auf der Erde*.", footnotes: ["℘ V. 24; Kap. 5,1; 9,24; 2Mo 15,15.16; Neh 6,16; Est 8,17", "℘ 2Mo 15,14; 5Mo 4,39; Ps 83,19; 1Kor 8,4.6"] },
      { number: 12, text: "So schwört mir nun beim HERRN*, weil ich Gnade an euch erwiesen habe, dass auch ihr an meines Vaters Haus Gnade erweisen werdet*! Und gebt mir ein zuverlässiges Zeichen*,", footnotes: ["℘ 1Mo 24,3", "℘ 1Mo 40,14", "w. Zeichen der Zuverlässigkeit"] },
      { number: 13, text: "dass ihr meinen Vater und meine Mutter und meine Brüder und meine Schwestern samt allem, was zu ihnen gehört, am Leben lassen und unsere Seelen vom Tod retten werdet!" },
      { number: 14, text: "Da sagten die Männer zu ihr: Unsere Seele soll an eurer Statt sterben, wenn ihr diese unsere Sache nicht verratet. Und es soll geschehen, wenn der HERR uns das Land gibt, dann werden wir Gnade und Treue an dir erweisen*.", footnotes: ["℘ Kap. 6,22; 1Mo 24,49; 47,29; Ri 1,24; 2Sam 2,5; Spr 14,22"] },
      { number: 15, text: "Da ließ sie sie an einem Seil durch das Fenster hinunter*; denn ihr Haus befand sich an der Stadtmauer*, und sie wohnte an der Stadtmauer.", footnotes: ["℘ 1Sam 19,12; Apg 9,25; Jak 2,25", "w. war in der Stadtmauer; d. h. es war an die Stadtmauer angebaut"] },
      { number: 16, text: "Und sie sagte zu ihnen: Geht ins Gebirge, damit die Verfolger nicht auf euch stoßen, und verbergt euch dort drei Tage, bis die Verfolger zurückgekehrt sind! Danach geht eures Weges!" },
      { number: 17, text: "Da sagten die Männer zu ihr: Von diesem deinem Eid, den du uns hast schwören lassen*, werden wir unter folgenden Bedingungen frei sein:", footnotes: ["℘ 1Mo 24,8"] },
      { number: 18, text: "Siehe, wenn wir in das Land kommen, musst du diese rote Schnur* in das Fenster binden*, durch das du uns heruntergelassen hast, und musst deinen Vater, deine Mutter, deine Brüder und das ganze Haus deines Vaters zu dir ins Haus versammeln*.", footnotes: ["w. Schnur aus karmesinrotem Faden", "℘ 2Mo 12,13", "℘ Kap. 6,23"] },
      { number: 19, text: "Und es soll geschehen, wer auch immer aus der Tür deines Hauses nach draußen gehen wird, dessen Blut sei auf seinem Haupt*, und wir werden von diesem Eid frei sein. Jeder aber, der bei dir im Haus sein wird, dessen Blut sei auf unserm Haupt, wenn Hand an ihn gelegt wird.", footnotes: ["d. h. er selbst trägt die Verantwortung für seinen Tod und nicht die Kundschafter\n℘ 2Mo 12,22.23; 3Mo 20,9.11-13"] },
      { number: 20, text: "Auch wenn du diese unsere Sache verrätst, so werden wir von deinem Eid frei sein, den du uns hast schwören lassen." },
      { number: 21, text: "Da sagte sie: Wie ihr sagt*, so sei es! Und sie entließ sie, und sie gingen weg. Sie aber band die rote Schnur ins Fenster*.", footnotes: ["w. Entsprechend euren Worten", "℘ 2Mo 12,28"] },
      { number: 22, text: "Und sie gingen weg und kamen ins Gebirge und blieben drei Tage dort, bis die Verfolger zurückgekehrt waren. Die Verfolger aber hatten den ganzen Weg abgesucht und sie nicht gefunden." },
      { number: 23, text: "Die beiden Männer kehrten nun um, stiegen von dem Gebirge herab, gingen hinüber und kamen zu Josua, dem Sohn des Nun; und sie erzählten ihm alles, was ihnen begegnet war*.", footnotes: ["℘ Mk 6,30"] },
      { number: 24, text: "Und sie sagten zu Josua: Der HERR hat das ganze Land in unsere Hand gegeben*; auch sind alle Bewohner des Landes vor uns mutlos geworden*.", footnotes: ["℘ Kap. 6,2; 8,1; 21,44; 2Mo 23,31; Ri 1,2; 18,10", "℘ V. 9.11"] },
    ]},
    { number: 3, verses: [
      { number: 1, text: "Da machte sich Josua des Morgens früh auf*, und sie brachen auf von Schittim* und kamen an den Jordan, er und alle Söhne Israel; dort rasteten* sie, bevor sie hinüberzogen.", heading: "Zug durch den Jordan", footnotes: ["℘ Kap. 6,12; 7,16; 8,10; 1Mo 22,3; 1Sam 17,20", "℘ Kap. 2,1", "o. übernachteten"] },
      { number: 2, text: "Und es geschah nach Ablauf von drei Tagen, da gingen die Aufseher* durch das Lager*,", footnotes: ["w. Schreiber; d. i. eine Beamtenbezeichnung", "℘ Kap. 1,10.11"] },
      { number: 3, text: "und sie befahlen dem Volk: Sobald ihr die Lade des Bundes des HERRN, eures Gottes, seht, wenn die Priester, die Leviten, sie aufheben*, dann sollt ihr von eurem Ort aufbrechen und ihr nachfolgen.", footnotes: ["℘ 5Mo 31,9"] },
      { number: 4, text: "Doch soll zwischen euch und ihr ein Abstand von etwa zweitausend Ellen sein. Ihr dürft euch ihr nicht nähern. Nur dann werdet ihr den Weg erkennen*, den ihr gehen sollt*; denn ihr seid den Weg bisher* noch nicht gegangen.", footnotes: ["w. Nähert euch ihr nicht, damit ihr den Weg erkennt", "℘ Ps 25,12; Jes 48,17; Joh 10,4", "w. seit gestern und vorgestern"] },
      { number: 5, text: "Und Josua sagte zu dem Volk: Heiligt euch*! Denn morgen wird der HERR in eurer Mitte Wunder tun*.", footnotes: ["℘ Kap. 7,13; 2Mo 19,10; 3Mo 20,7; 1Sam 16,5; 2Kor 7,1; 1Petr 1,15", "℘ Ps 77,15"] },
      { number: 6, text: "Und Josua sagte zu den Priestern: Hebt die Bundeslade auf und zieht vor dem Volk hinüber! Da hoben sie die Bundeslade auf* und zogen vor dem Volk her*.", footnotes: ["℘ Kap. 6,6", "℘ Mi 2,13"] },
      { number: 7, text: "Und der HERR sprach zu Josua: Heute will ich beginnen, dich in den Augen von ganz Israel groß zu machen*, damit sie erkennen: Genauso wie ich mit Mose gewesen bin, werde ich mit dir sein*.", footnotes: ["℘ Kap. 4,14; 2Chr 1,1", "℘ Kap. 1,5.9.17"] },
      { number: 8, text: "Du aber befiehl den Priestern, die die Bundeslade tragen: Wenn ihr an das Ufer* des Jordan kommt, so bleibt im Jordan stehen!", footnotes: ["w. an den Rand des Wassers"] },
      { number: 9, text: "Und Josua sagte zu den Söhnen Israel: Tretet heran und hört die Worte des HERRN, eures Gottes!" },
      { number: 10, text: "Und Josua sagte weiter: Daran sollt ihr erkennen, dass der lebendige Gott* in eurer Mitte ist* und dass er die Kanaaniter, Hetiter, Hewiter, Perisiter, Girgaschiter, Amoriter und Jebusiter* ganz bestimmt vor euch vertreiben wird*.", footnotes: ["℘ 5Mo 5,26; 1Sam 17,26; 2Kö 19,4; Jer 10,10; 1Thes 1,9", "℘ Kap. 22,31; 5Mo 7,21", "℘ Kap. 9,1; 11,3; 12,8; 24,11; 1Mo 15,21; 4Mo 13,29", "℘ Ps 44,3"] },
      { number: 11, text: "Siehe, die Lade des Bundes des Herrschers* der ganzen Erde* zieht vor euch her* in den Jordan.", footnotes: ["w. Herrn", "℘ 1Chr 29,11; Ps 83,19; Jes 54,5; Sach 4,14", "℘ 5Mo 9,3"] },
      { number: 12, text: "Nun denn, nehmt euch zwölf Männer aus den Stämmen Israels, je einen Mann für jeden Stamm*!", footnotes: ["℘ Kap. 4,2.4; 4Mo 13,2"] },
      { number: 13, text: "Und es wird geschehen, sobald die Fußsohlen der Priester, die die Lade des HERRN, des Herrn der ganzen Erde*, tragen, im Wasser des Jordan stillstehen, wird das Wasser des Jordan, das von oben herabfließende Wasser, abgeschnitten werden, und es wird stehen bleiben wie ein Damm*.", footnotes: ["℘ 1Chr 29,11; Ps 83,19; Jes 54,5; Sach 4,14", "℘ 2Mo 15,8; Ps 78,13; 114,3.5"] },
      { number: 14, text: "Und es geschah, als das Volk aus seinen Zelten aufbrach, um über den Jordan zu ziehen — wobei die Priester, die die Bundeslade trugen, vor dem Volk herzogen*,", footnotes: ["℘ Apg 7,45"] },
      { number: 15, text: "und als die Träger der Lade an den Jordan kamen und die Füße der Priester, die die Lade trugen, in das Wasser am Ufer* tauchten — der Jordan aber führt in der ganzen Erntezeit Hochwasser* —,", footnotes: ["w. in den Rand des Wassers", "w. ist voll über all seine Ufer alle Tage der Ernte\n℘ Kap. 4,18; 1Chr 12,16"] },
      { number: 16, text: "da blieb das von oben herabfließende Wasser stehen. Es richtete sich auf wie ein Damm*, sehr fern, bei der Stadt Adam, die bei* Zaretan* liegt. Und das Wasser, das zum Meer der Steppe*, dem Salzmeer, hinabfloss*, verlief sich völlig*. So zog das Volk hindurch, gegenüber von Jericho*.", footnotes: ["℘ 2Mo 15,8; Ps 78,13; 114,3.5", "w. zur Seite von", "℘ Ri 7,22; 1Kö 4,12", "hebr. Araba; d. i. die Steppe, die sich beiderseits des Toten Meeres erstreckt", "℘ Kap. 12,3; 5Mo 3,17", "w. wurde völlig abgeschnitten", "℘ Kap. 4,22; 5,1"] },
      { number: 17, text: "Und die Priester, die die Lade des Bundes des HERRN trugen, standen festen Fußes auf dem Trockenen mitten im Jordan. Und ganz Israel zog auf dem Trockenen hinüber, bis die ganze Nation vollständig den Jordan überquert hatte*.", footnotes: ["℘ Kap. 4,1.10.11; 2Mo 14,22"] },
    ]},
    { number: 4, verses: [
      { number: 1, text: "Und es geschah, als die ganze Nation vollständig durch den Jordan gezogen war*, da sprach der HERR zu Josua:", heading: "Aufrichtung der zwölf Gedenksteine", footnotes: ["℘ Kap. 3,17; 24,11"] },
      { number: 2, text: "Nehmt euch aus dem Volk zwölf Männer, einen Mann für jeden Stamm*,", footnotes: ["℘ Kap. 3,12"] },
      { number: 3, text: "und gebietet ihnen Folgendes: Hebt euch hier mitten im Jordan von der Stelle, wo die Füße der Priester auf festem Boden standen, zwölf Steine auf, bringt sie mit euch hinüber und legt sie in dem Nachtlager nieder, wo ihr diese Nacht verbringen werdet!" },
      { number: 4, text: "Da rief Josua die zwölf Männer, die er aus den Söhnen Israel eingesetzt hatte, je einen Mann für jeden Stamm*.", footnotes: ["℘ Kap. 3,12"] },
      { number: 5, text: "Und Josua sagte zu ihnen: Geht hinüber vor der Lade des HERRN, eures Gottes, mitten in den Jordan, und hebt euch jeder einen Stein auf seine Schulter, nach der Zahl der Stämme der Söhne Israel*,", footnotes: ["℘ 2Mo 24,4"] },
      { number: 6, text: "damit dies ein Zeichen in eurer Mitte sei! Wenn eure Kinder künftig* fragen: Was bedeuten euch diese Steine*? —", footnotes: ["w. morgen", "℘ V. 21; 2Mo 12,26"] },
      { number: 7, text: "dann sollt ihr ihnen sagen: Das Wasser des Jordan wurde vor der Lade des Bundes des HERRN abgeschnitten! Bei ihrem Durchzug durch den Jordan wurde das Wasser des Jordan abgeschnitten! Und diese Steine sollen den Söhnen Israel für alle Zeiten* zur Erinnerung dienen*.", footnotes: ["w. in Ewigkeit", "℘ 2Mo 12,14; 4Mo 17,5; 5Mo 16,3"] },
      { number: 8, text: "Da taten die Söhne Israel, wie Josua geboten hatte, hoben zwölf Steine auf aus der Mitte des Jordan, wie der HERR zu Josua geredet hatte*, nach der Zahl der Stämme der Söhne Israel*, brachten sie mit sich in das Nachtlager hinüber und legten sie dort nieder.", footnotes: ["℘ 2Mo 12,28", "℘ 2Mo 24,4"] },
      { number: 9, text: "Zwölf Steine aber richtete Josua mitten im Jordan auf, an der Stelle, wo die Füße der Priester, die die Bundeslade trugen, gestanden hatten. Dort sind sie noch bis zum heutigen Tag." },
      { number: 10, text: "Und die Priester, die Träger der Lade, blieben mitten im Jordan stehen, bis die ganze Sache ausgeführt war, die der HERR dem Josua geboten hatte dem Volk zu sagen; genauso wie Mose dem Josua befohlen hatte. Und das Volk eilte und zog hinüber*.", footnotes: ["℘ Kap. 3,17; 24,11"] },
      { number: 11, text: "Und es geschah, als das ganze Volk vollständig hinübergezogen war*, da zogen auch die Lade des HERRN und die Priester hinüber vor den Augen* des Volkes*.", footnotes: ["℘ Kap. 3,17; 24,11", "w. angesichts; o. vor dem Volk", "℘ Jes 52,12"] },
      { number: 12, text: "Und die Söhne Ruben und die Söhne Gad und der halbe Stamm Manasse zogen gerüstet vor den Söhnen Israel her*, wie Mose zu ihnen gesagt hatte*.", footnotes: ["℘ 5Mo 33,21", "℘ Kap. 1,14.15"] },
      { number: 13, text: "Etwa 40 000 zum Krieg Gerüstete zogen vor dem HERRN her zum Kampf* in die Steppen von Jericho.", footnotes: ["℘ Ri 20,1.2"] },
      { number: 14, text: "An jenem Tag machte der HERR den Josua groß in den Augen von ganz Israel*. Und sie fürchteten ihn, wie sie Mose gefürchtet hatten*, alle Tage seines Lebens.", footnotes: ["℘ Kap. 3,7; 2Mo 11,3; 1Chr 29,25", "℘ Kap. 1,17; 2Mo 14,31; 1Sam 12,18; 1Kö 3,28; 2Kö 2,15"] },
      { number: 15, text: "Und der HERR sprach zu Josua:" },
      { number: 16, text: "Befiehl den Priestern, die die Lade des Zeugnisses tragen, dass sie aus dem Jordan heraufsteigen!" },
      { number: 17, text: "Da befahl Josua den Priestern: Steigt aus dem Jordan herauf!" },
      { number: 18, text: "Und es geschah, als die Priester, die die Lade des Bundes des HERRN trugen, aus der Mitte des Jordan heraufstiegen, als die Fußsohlen der Priester kaum das Trockene berührt hatten*, da kehrte das Wasser des Jordan an seinen Platz zurück, und es floss wie früher* über alle seine Ufer*.", footnotes: ["w. als sich die Fußsohlen der Priester zu dem Trockenen hin losgerissen hatten", "w. wie gestern und vorgestern", "℘ Kap. 3,15"] },
      { number: 19, text: "Und das Volk stieg aus dem Jordan herauf am zehnten Tag des ersten Monats; und sie lagerten sich in Gilgal*, an der Ostgrenze von Jericho*.", footnotes: ["℘ Kap. 5,9.10; 9,6; 5Mo 11,30; 1Sam 10,8; 2Kö 2,1", "℘ Kap. 24,11"] },
      { number: 20, text: "Jene zwölf Steine aber, die sie aus dem Jordan genommen hatten, richtete Josua in Gilgal auf." },
      { number: 21, text: "Und er sagte zu den Söhnen Israel: Wenn eure Söhne künftig* ihre Väter fragen werden: Was bedeuten diese Steine*? —", footnotes: ["w. morgen", "℘ V. 6"] },
      { number: 22, text: "dann sollt ihr es euren Söhnen so erklären*: Trockenen Fußes* hat Israel diesen Jordan durchquert*.", footnotes: ["w. zu erkennen geben", "w. Auf Trockenem", "℘ Kap. 3,17; Ps 66,6"] },
      { number: 23, text: "Denn der HERR, euer Gott, hat das Wasser des Jordan vor euch vertrocknen lassen, bis ihr hinübergezogen wart, wie der HERR, euer Gott, es mit dem Schilfmeer tat, das er vor uns vertrocknen ließ, bis wir hindurchgezogen waren*,", footnotes: ["℘ 2Mo 15,19"] },
      { number: 24, text: "damit alle Völker der Erde erkennen sollen, wie stark die Hand des HERRN ist*, damit ihr den HERRN, euren Gott, allezeit* fürchtet*.", footnotes: ["w. damit alle . . . die Hand des HERRN erkennen sollen, dass sie stark ist\n℘ 2Mo 9,16; 1Sam 17,46; 1Kö 8,40-43; Ps 106,8; Jes 52,10; Röm 9,17", "w. alle Tage", "℘ 2Mo 14,31; 5Mo 6,2; Jer 10,7; Offb 15,4"] },
    ]},
    { number: 5, verses: [
      { number: 1, text: "Und es geschah, als alle Könige der Amoriter, die jenseits des Jordan im Westen*, und alle Könige der Kanaaniter, die am Meer wohnten*, hörten, dass der HERR das Wasser des Jordan vor den Söhnen Israel hatte vertrocknen lassen, bis wir* hinübergezogen waren*, da zerschmolz ihr Herz, und es war kein Mut* mehr in ihnen vor den Söhnen Israel*.", footnotes: ["w. meerwärts", "℘ 4Mo 13,29", "andere hebr. Handschr.: sie", "℘ Kap. 3,17", "w. Atem", "℘ Kap. 2,9-11"] },
      { number: 2, text: "In jener Zeit sprach der HERR zu Josua: Mache dir steinerne Messer und wiederhole die Beschneidung an den Söhnen Israel*!*", heading: "Beschneidung Israels und Passahfeier in Gilgal", footnotes: ["w. Wende dich, die Söhne Israel zum zweiten Mal zu beschneiden", "℘ 1Mo 17,10-13; 23-27"] },
      { number: 3, text: "Da machte sich Josua steinerne Messer und beschnitt die Söhne Israel am Hügel Aralot*.", footnotes: ["d. h. Hügel der Vorhäute"] },
      { number: 4, text: "Und dies ist der Grund, warum Josua sie beschnitt: Alles Volk männlichen Geschlechts, das aus Ägypten gezogen war*, alle Kriegsleute waren unterwegs in der Wüste gestorben bei ihrem Auszug aus Ägypten.", footnotes: ["℘ 4Mo 26,64.65"] },
      { number: 5, text: "Denn das ganze Volk, das auszog, war beschnitten gewesen; aber das ganze Volk, das in der Wüste unterwegs bei ihrem Auszug aus Ägypten geboren worden war, hatte man nicht beschnitten." },
      { number: 6, text: "Denn die Söhne Israel wanderten vierzig Jahre in der Wüste, bis die ganze Nation umgekommen war — die Kriegsleute*, die aus Ägypten ausgezogen waren —, weil sie nicht auf die Stimme des HERRN gehört hatten und weil der HERR ihnen geschworen hatte, sie das Land nicht sehen zu lassen*, das der HERR ihren Vätern geschworen hatte, uns zu geben*, ein Land, das von Milch und Honig überfließt*.", footnotes: ["℘ Kap. 24,7", "℘ 4Mo 14,33-35; Hebr 3,11.17.18", "℘ Kap. 1,6", "℘ 2Mo 3,8.17"] },
      { number: 7, text: "Und ihre Söhne hatte er statt ihrer aufkommen lassen*. Diese nun beschnitt Josua; denn sie waren unbeschnitten, weil man sie unterwegs nicht beschnitten hatte.", footnotes: ["℘ 5Mo 1,39"] },
      { number: 8, text: "Und es geschah, als die ganze Nation vollständig beschnitten war, da blieben sie an ihrem Ort im Lager, bis sie genesen waren*.", footnotes: ["℘ 1Mo 34,25"] },
      { number: 9, text: "Und der HERR sprach zu Josua: Heute habe ich die Schande* Ägyptens von euch abgewälzt. Daher nennt man diesen Ort Gilgal* bis zum heutigen Tag.", footnotes: ["℘ 1Mo 34,14", "d. h. Abwälzung\n℘ Kap. 4,19; 1Sam 7,16; Hos 4,15; Am 5,5; Mi 6,5"] },
      { number: 10, text: "Und die Söhne Israel lagerten in Gilgal. Und sie feierten das Passah am vierzehnten Tag des Monats, am Abend*, in den Steppen von Jericho.", footnotes: ["℘ 2Mo 12,6.11"] },
      { number: 11, text: "Und sie aßen von dem Ertrag* des Landes am Tag nach dem Passah, ungesäuertes Brot* und geröstete Körner, an ebendiesem Tag.", footnotes: ["o. von dem Getreide", "℘ 2Mo 13,6.7"] },
      { number: 12, text: "Das Man* aber hörte auf am folgenden Tag, als sie von dem Ertrag* des Landes aßen, und es gab für die Söhne Israel künftig kein Man mehr. Und sie aßen von der Ernte* des Landes Kanaan in jenem Jahr.", footnotes: ["℘ 2Mo 16,35", "o. von dem Getreide", "o. dem Erzeugnis"] },
      { number: 13, text: "Und es geschah, als Josua bei Jericho war, da erhob er seine Augen und sah: und siehe, ein Mann stand ihm gegenüber*, und sein Schwert war gezückt in seiner Hand*. Da ging Josua auf ihn zu und sagte zu ihm: Gehörst du zu uns oder zu unseren Feinden?", heading: "Der Anführer des Heeres des HERRN begegnet Josua", footnotes: ["℘ 1Mo 18,2", "℘ 4Mo 22,23.31"] },
      { number: 14, text: "Und er sprach: Nein, sondern ich bin der Oberste des Heeres des HERRN*; gerade jetzt bin ich gekommen*. Da fiel Josua auf sein Angesicht* zur Erde und huldigte ihm* und sagte zu ihm: Was redet mein Herr zu seinem Knecht?*", footnotes: ["℘ 2Mo 23,20.23; Dan 8,11", "℘ Röm 8,31; 1Kor 15,57", "℘ 4Mo 22,31; Hes 3,23", "℘ Mt 2,11; 28,9; Joh 9,38", "℘ 1Sam 3,9.10; 2Sam 7,19.20"] },
      { number: 15, text: "Da sprach der Oberste des Heeres des HERRN zu Josua: Zieh deine Schuhe von deinen Füßen*; denn der Ort, auf dem du stehst, ist heilig!* Und Josua tat es.", footnotes: ["w. Zieh deinen Schuh von deinem Fuß", "℘ 2Mo 3,5"] },
    ]},
    { number: 6, verses: [
      { number: 1, text: "Und Jericho* hatte seine Tore geschlossen und blieb verschlossen vor den Söhnen Israel. Niemand ging heraus, und niemand ging hinein.", heading: "Jericho wird erobert und gebannt", footnotes: ["℘ Kap. 2,1; 18,21; 2Sam 10,5; 2Kö 2,4"] },
      { number: 2, text: "Da sprach der HERR zu Josua: Siehe, ich habe Jericho, seinen König und seine tüchtigen Krieger in deine Hand gegeben*.", footnotes: ["℘ Kap. 2,9.24; 12,9"] },
      { number: 3, text: "So zieht nun um die Stadt: alle Kriegsleute, einmal rings um die Stadt herum! So sollst du es sechs Tage lang machen." },
      { number: 4, text: "Und sieben Priester sollen sieben Widderhörner vor der Lade hertragen. Aber am siebten Tag sollt ihr siebenmal* um die Stadt herumziehen, und die Priester sollen dabei in die Hörner stoßen*.", footnotes: ["℘ 1Kö 18,43; 2Kö 5,10", "℘ 4Mo 10,8.9"] },
      { number: 5, text: "Und es soll geschehen, wenn man das Widderhorn anhaltend bläst und ihr den Schall des Horns hört, dann soll das ganze Volk ein großes Kriegsgeschrei erheben. Die Mauer der Stadt wird dann in sich zusammenstürzen, und das Volk soll hinaufsteigen, jeder gerade vor sich hin." },
      { number: 6, text: "Und Josua, der Sohn des Nun, rief die Priester und sagte zu ihnen: Hebt die Bundeslade auf*! Und sieben Priester sollen sieben Widderhörner vor der Lade des HERRN hertragen.", footnotes: ["℘ Kap. 3,6"] },
      { number: 7, text: "Zum Volk sagte er: Macht euch auf und zieht um die Stadt! Die Gerüsteten aber sollen vor der Lade des HERRN hergehen." },
      { number: 8, text: "Und es geschah, als Josua zum Volk geredet hatte, da machten sich die sieben Priester auf, die die sieben Widderhörner vor dem HERRN hertrugen, und stießen in die Hörner. Und die Lade des Bundes des HERRN folgte ihnen." },
      { number: 9, text: "Die Gerüsteten zogen vor den Priestern her, die in die Hörner stießen, und die Nachhut des Zuges folgte der Lade, wobei man immerfort in die Hörner stieß." },
      { number: 10, text: "Dem Volk aber hatte Josua befohlen: Ihr sollt kein Kriegsgeschrei erheben und eure Stimme nicht hören lassen. Kein Wort soll aus eurem Mund kommen bis zu dem Tag, an dem ich zu euch sagen werde: Erhebt das Kriegsgeschrei! Dann sollt ihr das Kriegsgeschrei erheben." },
      { number: 11, text: "So zog die Lade des HERRN um die Stadt, einmal rings um sie her; und sie kamen wieder ins Lager und übernachteten im Lager." },
      { number: 12, text: "Und früh am Morgen machte sich Josua auf*, und die Priester trugen die Lade des HERRN.", footnotes: ["℘ Kap. 3,1"] },
      { number: 13, text: "Und die sieben Priester, die die sieben Widderhörner vor der Lade des HERRN hertrugen, stießen im Gehen immerfort in die Hörner: Die Gerüsteten zogen vor ihnen her, während die Nachhut des Zuges hinter der Lade des HERRN folgte, wobei man immerfort in die Hörner stieß." },
      { number: 14, text: "So zogen sie auch am zweiten Tag nur einmal um die Stadt. Dann kehrten sie zum Lager zurück. So taten sie es sechs Tage lang." },
      { number: 15, text: "Und es geschah am siebten Tag, da machten sie sich früh auf, beim Aufgang der Morgenröte*, und zogen in derselben Weise siebenmal um die Stadt; nur an diesem Tag zogen sie siebenmal um die Stadt.", footnotes: ["℘ Kap. 3,1"] },
      { number: 16, text: "Und es geschah beim siebten Mal, da stießen die Priester in die Hörner* und Josua sagte zum Volk: Erhebt das Kriegsgeschrei! Denn der HERR hat euch die Stadt gegeben*.", footnotes: ["℘ Ri 7,22", "℘ 2Chr 20,22"] },
      { number: 17, text: "Und die Stadt selbst und alles, was darin ist, soll dem Bann des HERRN verfallen sein*. Nur die Hure Rahab soll am Leben bleiben, sie und alle, die bei ihr im Haus sind, weil sie die Boten versteckte, die wir ausgesandt hatten*.", footnotes: ["w. dem HERRN ein Bann werden\n℘ 3Mo 27,28; 4Mo 21,2.3", "℘ Kap. 2,4"] },
      { number: 18, text: "Ihr jedoch sollt euch vor dem Gebannten hüten*, damit ihr nicht an anderen den Bann vollstreckt, selbst aber* etwas von dem Gebannten nehmt und das Lager Israels zum Bann macht* und es ins Unglück bringt*.", footnotes: ["℘ 5Mo 23,10", "LXX: damit es euch nicht etwa gelüstet und ihr selbst", "℘ Kap. 7,12", "℘ Kap. 7,25; 5Mo 7,26; 1Sam 15,9-11"] },
      { number: 19, text: "Alles Silber und Gold sowie die bronzenen und eisernen Geräte sollen dem HERRN heilig sein: In den Schatz des HERRN soll es kommen*.", footnotes: ["℘ 1Chr 18,11"] },
      { number: 20, text: "Da erhob das Volk das Kriegsgeschrei*, und sie stießen in die Hörner. Und es geschah, als das Volk den Schall der Hörner hörte, da erhob das Volk ein großes Kriegsgeschrei. Da stürzte die Mauer in sich zusammen*, und das Volk stieg in die Stadt, ein jeder gerade vor sich hin, und sie nahmen die Stadt ein.", footnotes: ["℘ 2Chr 13,15", "℘ Zef 1,16; Hebr 11,30"] },
      { number: 21, text: "Und sie vollstreckten den Bann an allem, was in der Stadt war, an Mann und Frau, an Alt und Jung*, an Rind, Schaf* und Esel, mit der Schärfe des Schwertes*. —", footnotes: ["℘ Kap. 8,22; 9,24; 5Mo 7,2.16", "o. Kleinvieh", "℘ Kap. 8,2; 9,3; 5Mo 2,34; 13,16"] },
      { number: 22, text: "Zu den beiden Männern, die das Land ausgekundschaftet hatten, sagte Josua: Geht in das Haus der Hure und führt die Frau sowie alles, was zu ihr gehört, von dort heraus, wie ihr es ihr geschworen habt!*", footnotes: ["℘ Kap. 2,14"] },
      { number: 23, text: "Da gingen die jungen Männer, die Kundschafter, hinein und führten Rahab und ihren Vater und ihre Mutter und ihre Brüder und alles, was zu ihr gehörte, hinaus*: Alle ihre Verwandten führten sie hinaus; sie brachten sie außerhalb des Lagers Israels unter. —", footnotes: ["℘ Kap. 2,18.19; Ri 1,25; Hebr 11,31"] },
      { number: 24, text: "Die Stadt aber und alles, was darin war, verbrannten sie mit Feuer*. Das Silber jedoch und das Gold und die bronzenen und eisernen Geräte legten sie in den Schatz des Hauses des HERRN*. —", footnotes: ["℘ Kap. 11,11; 4Mo 31,10; 5Mo 13,17", "℘ 1Chr 18,11"] },
      { number: 25, text: "So ließ Josua die Hure Rahab* und das Haus ihres Vaters sowie alles, was zu ihr gehörte, am Leben*. Und sie wohnte mitten in Israel bis zum heutigen Tag, weil sie die Boten versteckte, die Josua gesandt hatte, um Jericho auszukundschaften*.", footnotes: ["℘ Kap. 2,1.4", "℘ Kap. 2,4", "℘ Kap. 2,4"] },
      { number: 26, text: "So ließ Josua damals schwören: Verflucht vor dem HERRN sei der Mann, der sich aufmachen und diese Stadt Jericho wieder aufbauen* wird! Mit seinem* Erstgeborenen wird er ihren Grund legen, und mit seinem* Jüngsten ihre Tore einsetzen*. —", footnotes: ["w. bauen", "d. h. um den Preis seines", "d. h. um den Preis seines", "℘ 1Kö 16,34"] },
      { number: 27, text: "Und der HERR war mit Josua*, und die Kunde von ihm verbreitete sich durch das ganze Land*.", footnotes: ["℘ Kap. 1,5.9", "℘ 2Sam 7,9; 1Chr 14,17; Est 9,4"] },
    ]},
    { number: 7, verses: [
      { number: 1, text: "Doch die Söhne Israel übten Untreue an dem Gebannten. Und Achan, der Sohn des Karmi, des Sohnes Sabdis, des Sohnes Serachs, vom Stamm Juda, nahm etwas von dem Gebannten*. Da entbrannte der Zorn des HERRN gegen die Söhne Israel*. —", heading: "Ai wird nicht erobert — Achan wird gebannt", footnotes: ["℘ 1Chr 2,7; Pred 9,18", "℘ Kap. 22,18.20; 3Mo 10,6; 1Chr 21,7"] },
      { number: 2, text: "Und Josua schickte Männer von Jericho nach Ai*, das bei Bet-Awen, östlich von Bethel liegt*, und sagte zu ihnen: Geht hinauf und kundschaftet das Land aus! Und die Männer gingen hinauf und kundschafteten Ai aus.", footnotes: ["℘ Jes 10,28", "℘ 1Mo 12,8; 1Sam 13,5; 1Kö 12,29; Hos 4,15"] },
      { number: 3, text: "Als sie zu Josua zurückkamen, sagten sie zu ihm: Es muss nicht das ganze Volk hinaufziehen. Etwa zweitausend oder dreitausend Mann mögen hinaufziehen und Ai schlagen. Bemühe nicht das ganze Volk dorthin, denn sie sind nur wenige!" },
      { number: 4, text: "Da zogen von dem Volk etwa dreitausend Mann hinauf; aber sie flohen vor den Männern von Ai." },
      { number: 5, text: "Und die Männer von Ai erschlugen von ihnen etwa 36 Mann und jagten ihnen nach* vom Tor bis nach Schebarim* und schlugen sie am Abhang. Da zerschmolz das Herz des Volkes und wurde zu Wasser.", footnotes: ["℘ 5Mo 1,44", "o. bis zu den Steinbrüchen"] },
      { number: 6, text: "Und Josua zerriss seine Kleider* und fiel auf sein Angesicht zur Erde*, vor der Lade des HERRN, bis zum Abend, er und die Ältesten von Israel*, und sie warfen Staub auf ihr Haupt*.", footnotes: ["℘ Ri 11,35", "℘ 2Sam 12,16; Esr 9,3; 10,1; Hi 1,20", "℘ Ri 20,23.26", "℘ 1Sam 4,12; 2Sam 1,2; 13,19; Neh 9,1; Est 4,1.3"] },
      { number: 7, text: "Und Josua sagte: Ach, Herr, HERR! Wozu hast du denn dieses Volk über den Jordan geführt, um uns doch in die Hand der Amoriter zu geben, damit sie uns vernichten*? Hätten wir uns doch entschlossen, jenseits des Jordan zu bleiben!", footnotes: ["℘ 2Mo 5,22"] },
      { number: 8, text: "Bitte, Herr, was soll ich sagen, nachdem Israel seinen Feinden den Rücken gekehrt hat?" },
      { number: 9, text: "Die Kanaaniter und alle Bewohner des Landes werden es hören*! Und sie werden uns umzingeln* und unsern Namen von der Erde ausrotten*! Was wirst du dann für deinen großen Namen tun?*", footnotes: ["℘ 4Mo 14,13", "o. werden sich gegen uns wenden", "℘ Ps 83,5", "℘ 2Mo 32,12; 5Mo 9,28; Ps 79,9; 115,1.2; Joe 2,17; Mi 7,10"] },
      { number: 10, text: "Da sprach der HERR zu Josua: Steh auf! Warum liegst du denn auf deinem Angesicht*?", footnotes: ["℘ 2Mo 14,15"] },
      { number: 11, text: "Israel hat sich versündigt, sie haben meinen Bund übertreten, den ich ihnen geboten habe. Und sie haben sogar von dem Gebannten genommen und haben es gestohlen und haben es verheimlicht und es zu ihren Geräten gelegt!" },
      { number: 12, text: "Die Söhne Israel werden vor ihren Feinden nicht mehr bestehen können*. Den Rücken werden sie ihren Feinden zuwenden müssen, denn sie sind zum Bann geworden. Ich werde nicht mehr mit euch sein, wenn ihr nicht das Gebannte aus eurer Mitte ausrottet*.", footnotes: ["℘ 4Mo 14,42; Ri 2,14", "℘ Kap. 6,18"] },
      { number: 13, text: "Steh auf, heilige das Volk* und sprich: Heiligt euch für morgen! Denn so spricht der HERR, der Gott Israels: Gebanntes ist in deiner Mitte, Israel. Du wirst vor deinen Feinden nicht bestehen können, bis ihr das Gebannte aus eurer Mitte weggetan habt*.", footnotes: ["℘ Kap. 3,5", "℘ 5Mo 13,6"] },
      { number: 14, text: "Darum sollt ihr am kommenden Morgen nach euren Stämmen herantreten. Und es soll geschehen: der Stamm, den der HERR treffen* wird, soll herantreten nach den Sippen; und die Sippe, die der HERR treffen wird, soll herantreten nach den Häusern; und das Haus, das der HERR treffen wird, soll herantreten nach den Männern*.", footnotes: ["w. ergreifen; d. h. durch Los; vgl. 1Sam 14,41", "℘ 1Sam 10,19; Spr 16,33"] },
      { number: 15, text: "Und es soll geschehen: wer mit dem Gebannten angetroffen wird, soll mit Feuer verbrannt werden, er selbst und alles, was zu ihm gehört; denn er hat den Bund des HERRN übertreten und eine Schandtat in Israel begangen*.", footnotes: ["℘ Ri 20,6"] },
      { number: 16, text: "Josua machte sich früh am Morgen auf* und ließ Israel herantreten nach seinen Stämmen; da wurde der Stamm Juda getroffen.", footnotes: ["℘ Kap. 3,1"] },
      { number: 17, text: "Dann ließ er die Sippen von Juda herantreten; und es traf die Sippe der Serachiter. Und er ließ die Sippe der Serachiter herantreten nach den Männern; da wurde Sabdi getroffen." },
      { number: 18, text: "Und er ließ sein Haus herantreten nach den Männern; da wurde Achan getroffen*, der Sohn des Karmi, des Sohnes Sabdis, des Sohnes Serachs, vom Stamm Juda.", footnotes: ["℘ 1Sam 14,42"] },
      { number: 19, text: "Da sagte Josua zu Achan: Mein Sohn, gib doch dem HERRN, dem Gott Israels, die Ehre* und gib ihm das Lob* und teile mir mit, was du getan hast! Verschweige nichts vor mir!", footnotes: ["℘ 1Sam 6,5; Jer 13,16; Joh 9,24", "o. Geständnis; gemeint ist ein Lobbekenntnis, das das Sündenbekenntnis einschloss\n℘ 4Mo 5,6.7; 1Sam 14,43; Esr 10,11; Jon 1,8"] },
      { number: 20, text: "Da antwortete Achan dem Josua und sagte: Es ist wahr, ich habe gegen den HERRN, den Gott Israels, gesündigt*, das und das habe ich getan:", footnotes: ["℘ 2Mo 9,27; Lk 15,21"] },
      { number: 21, text: "Ich sah unter der Beute einen schönen Mantel aus Schinar sowie zweihundert Schekel Silber und einen Goldbarren*, sein Gewicht fünfzig Schekel. Ich bekam Lust danach*, und ich nahm es*, und siehe, es ist im Innern meines Zeltes im Boden verscharrt* und das Silber darunter*.", footnotes: ["w. Zunge von Gold. — Gemeint ist ein Goldbarren in Form einer Zunge.", "℘ 1Mo 3,6; 1Jo 2,16", "℘ 1Tim 6,9.10", "o. versteckt", "℘ 2Kö 5,24"] },
      { number: 22, text: "Da schickte Josua Boten hin, und sie liefen zum Zelt; und siehe, es war in seinem Zelt verscharrt und das Silber darunter." },
      { number: 23, text: "Sie nahmen es aus dem Innern des Zeltes und brachten es zu Josua und zu allen Söhnen Israel, und sie schütteten es vor dem HERRN hin." },
      { number: 24, text: "Da nahm Josua und ganz Israel mit ihm Achan, den Sohn des Serach, sowie das Silber, den Mantel und den Goldbarren und seine Söhne, seine Töchter*, seine Rinder, seine Esel und seine Schafe, sein Zelt und alles, was zu ihm gehörte, und sie brachten sie hinauf ins Tal Achor.", footnotes: ["℘ Kap. 22,20"] },
      { number: 25, text: "Und Josua sagte: Wie du uns ins Unglück gebracht hast*, so wird der HERR dich heute ins Unglück bringen! Und ganz Israel steinigte ihn*, und sie verbrannten sie mit Feuer und bewarfen sie mit Steinen.", footnotes: ["℘ Kap. 6,18; 1Mo 34,30", "℘ 5Mo 13,10.11; Spr 1,19; 15,27"] },
      { number: 26, text: "Und sie errichteten einen großen Steinhaufen über ihm*, der bis zum heutigen Tag noch da ist. Da wandte sich der HERR von seinem glühenden Zorn ab*. Darum nannte man diesen Ort Tal Achor* bis zum heutigen Tag.", footnotes: ["℘ Kap. 8,29; 2Sam 18,17", "w. Und der HERR wandte sich von der Glut seines Zorns\n℘ 2Mo 32,12; 4Mo 25,8; 5Mo 13,18; 2Chr 29,10; Esr 10,14; Ps 85,4; Jon 1,15", "hebr. achar; d. h. ins Unglück bringen\n℘ Jes 65,10; Hos 2,17"] },
    ]},
    { number: 8, verses: [
      { number: 1, text: "Und der HERR sprach zu Josua: Fürchte dich nicht und erschrick nicht*!* Nimm das ganze Kriegsvolk mit dir und mache dich auf, zieh hinauf nach Ai! Siehe, ich habe den König von Ai sowie sein Volk, seine Stadt und sein Land in deine Hand gegeben*.", heading: "Ai wird erobert und gebannt", footnotes: ["o. und sei nicht niedergeschlagen", "℘ Kap. 1,9; 5Mo 7,18", "℘ Kap. 6,2"] },
      { number: 2, text: "Du sollst mit Ai und seinem König das tun, was du mit Jericho und seinem König getan hast*. Jedoch seine Beute und sein Vieh dürft ihr unter euch aufteilen*. Lege du der Stadt einen Hinterhalt von der Rückseite her!", footnotes: ["℘ Kap. 6,21; 9,3", "w. für euch erbeuten\n℘ Kap. 11,14; 5Mo 2,35"] },
      { number: 3, text: "Da machte sich Josua mit dem ganzen Kriegsvolk auf*, um nach Ai hinaufzuziehen. Und Josua wählte 30 000 Mann, tüchtige Krieger, aus* und sandte sie bei Nacht aus.", footnotes: ["℘ Kap. 10,7", "℘ 2Mo 17,9"] },
      { number: 4, text: "Er befahl ihnen: Seht, ihr sollt euch in den Hinterhalt legen, hinter der Stadt*! Entfernt euch nicht zu sehr von der Stadt*, sondern seid alle bereit!", footnotes: ["w. ihr sollt der Stadt einen Hinterhalt legen, hinter der Stadt", "℘ Ri 9,32; 20,29"] },
      { number: 5, text: "Ich aber und das ganze Volk, das bei mir ist, wir wollen nahe an die Stadt heranrücken*. Und es soll geschehen, wenn sie herauskommen, uns entgegen, wie beim ersten Mal, so wollen wir vor ihnen fliehen.", footnotes: ["w. wir wollen uns der Stadt nähern"] },
      { number: 6, text: "Sie werden uns nachsetzen, bis wir sie von der Stadt abgeschnitten haben. Denn sie werden sich sagen: Sie fliehen vor uns wie beim ersten Mal! Wenn wir dann vor ihnen fliehen werden*,", footnotes: ["℘ Ri 20,32"] },
      { number: 7, text: "dann sollt ihr euch aus dem Hinterhalt aufmachen und die Stadt einnehmen. Der HERR, euer Gott, wird sie in eure Hand geben." },
      { number: 8, text: "Und es soll geschehen, wenn ihr die Stadt eingenommen habt, dann sollt ihr sie in Brand stecken*; nach dem Wort des HERRN sollt ihr es tun. Seht, ich habe es euch befohlen. —", footnotes: ["w. die Stadt mit Feuer anzünden"] },
      { number: 9, text: "Da schickte Josua sie los, und sie begaben sich in den Hinterhalt und blieben zwischen Bethel und Ai, westlich von Ai. Josua aber verbrachte jene Nacht mitten unter dem Volk*.", footnotes: ["d. h. beim Kriegsvolk"] },
      { number: 10, text: "Und Josua machte sich des Morgens früh auf* und musterte das Volk. Dann zog er mit den Ältesten Israels vor dem Volk her nach Ai hinauf.", footnotes: ["℘ Kap. 3,1"] },
      { number: 11, text: "Und alles Kriegsvolk, das bei ihm war, zog hinauf und rückte heran, und sie kamen vor die Stadt. Sie lagerten sich nördlich von Ai, so dass das Tal zwischen ihnen* und Ai war.", footnotes: ["w. ihm; hiermit ist das Kriegsvolk gemeint"] },
      { number: 12, text: "Er hatte aber etwa fünftausend Mann genommen und sie als Hinterhalt zwischen Bethel und Ai gelegt, westlich von der Stadt*.", footnotes: ["℘ 1Sam 15,5"] },
      { number: 13, text: "Und so stellten sie das Volk auf, das ganze Lager, das nördlich von der Stadt war, und sein Ende* westlich von der Stadt. Und Josua zog in dieser Nacht mitten in die Talebene.", footnotes: ["w. Ferse; o. Huf; militärisch: der hintere Teil des Heeres"] },
      { number: 14, text: "Und es geschah, als der König von Ai es sah, da rückten die Männer der Stadt in aller Frühe eilends aus*, Israel entgegen zum Kampf, er und sein ganzes Volk, zur Begegnung* vor der Steppe*. Er hatte aber nicht erkannt,* dass ihm im Rücken der Stadt ein Hinterhalt gelegt war.", footnotes: ["w. da eilten die Männer der Stadt und machten sich früh auf und zogen hinaus", "o. zum Begegnungsplatz", "w. vor der Araba; vgl. Kap. 3,16", "℘ Ri 20,34"] },
      { number: 15, text: "Josua und ganz Israel ließen sich nun von ihnen schlagen und flohen zur Wüste hin." },
      { number: 16, text: "Da wurde das ganze Volk, das in der Stadt war, zusammengerufen, um ihnen nachzujagen. Und sie jagten Josua nach und wurden von der Stadt abgeschnitten." },
      { number: 17, text: "Da blieb kein Mann in Ai und Bethel zurück, der nicht hinter Israel her ausgezogen wäre. Und sie ließen die Stadt offenstehen und jagten Israel nach*.", footnotes: ["℘ Ri 20,31"] },
      { number: 18, text: "Da sprach der HERR zu Josua: Strecke das Kurzschwert, das in deiner Hand ist, gegen Ai aus; denn in deine Hand will ich es geben. Josua streckte das Krummschwert, das in seiner Hand war, gegen die Stadt aus*.", footnotes: ["℘ 2Mo 8,1"] },
      { number: 19, text: "Der Hinterhalt aber hatte sich eilends aus seiner Stellung aufgemacht*, und sie liefen, als er seine Hand ausstreckte. Und sie kamen zur Stadt, nahmen sie ein, und sie eilten und steckten sie in Brand*.", footnotes: ["w. von seinem Ort erhoben", "w. und zündeten die Stadt mit Feuer an"] },
      { number: 20, text: "Und die Männer von Ai wandten sich um und sahen, und siehe, der Rauch von der Stadt stieg zum Himmel auf. Da war in ihnen keine Kraft mehr zu fliehen, weder hierhin noch dorthin. Und das Volk, das bisher zur Wüste geflohen war, wandte sich nun um gegen den Verfolger*.", footnotes: ["℘ Ri 20,40.41"] },
      { number: 21, text: "Denn als Josua und ganz Israel sahen, dass der Hinterhalt die Stadt eingenommen hatte und dass der Rauch der Stadt aufstieg, da kehrten sie um und schlugen die Männer von Ai." },
      { number: 22, text: "Diese waren ja aus der Stadt ihnen entgegen ausgezogen, so dass sie nun mitten zwischen Israel waren, die einen kamen von hier und die andern von dort. Und sie erschlugen sie, bis von ihnen kein Entronnener oder Entkommener mehr übrig blieb*.", footnotes: ["℘ Kap. 6,21"] },
      { number: 23, text: "Den König von Ai hingegen ergriffen sie lebendig und brachten ihn zu Josua*.", footnotes: ["℘ Kap. 10,22.23"] },
      { number: 24, text: "Und es geschah, als Israel alle Bewohner von Ai auf dem Feld, in der Wüste, wohin sie ihnen nachgejagt waren, umgebracht hatte* und sie alle durch die Schärfe des Schwertes gefallen waren, bis sie vollständig aufgerieben waren, da kehrte ganz Israel um nach Ai, und sie schlugen es mit der Schärfe des Schwertes.", footnotes: ["w. als Israel vollendet hatte, alle Bewohner von Ai umzubringen"] },
      { number: 25, text: "Die Zahl aller Männer und Frauen, die an diesem Tag fielen, war zwölftausend, alle Leute von Ai." },
      { number: 26, text: "Josua aber zog seine Hand, die er mit dem Kurzschwert ausgestreckt hatte, nicht zurück, bis er an allen Bewohnern von Ai den Bann vollstreckt hatte*.", footnotes: ["℘ Kap. 9,3; 2Mo 17,12.13; 5Mo 2,34"] },
      { number: 27, text: "Nur das Vieh und die Beute dieser Stadt erbeutete Israel für sich, nach dem Wort des HERRN, das er dem Josua befohlen hatte." },
      { number: 28, text: "Und Josua brannte Ai nieder und machte es zu einem ewigen Hügel der Öde, bis zum heutigen Tag*.", footnotes: ["℘ 5Mo 13,17"] },
      { number: 29, text: "Und den König von Ai ließ er an einen Baum* hängen* bis zum Abend. Und bei Sonnenuntergang befahl Josua, dass sie seine Leiche vom Baum herunternähmen*. Und sie warfen sie an den Eingang des Stadttores und errichteten über ihr einen großen Steinhaufen*, der bis zum heutigen Tag da ist.", footnotes: ["o. an ein Holz", "℘ Kap. 12,9", "℘ Kap. 10,26.27; 5Mo 21,22.23", "℘ Kap. 7,26"] },
      { number: 30, text: "Damals baute Josua dem HERRN, dem Gott Israels, einen Altar* auf dem Berg Ebal,", heading: "Altar auf dem Ebal — Gesetzessteine — Segen und Fluch", footnotes: ["℘ 1Mo 12,7.8"] },
      { number: 31, text: "wie Mose, der Knecht des HERRN, den Söhnen Israel geboten hatte, wie im Buch des Gesetzes des Mose geschrieben steht, einen Altar von unbehauenen Steinen, über denen man kein Eisen geschwungen hatte*. Und sie brachten darauf dem HERRN Brandopfer dar und schlachteten Heilsopfer*.", footnotes: ["℘ 2Mo 20,25", "o. Friedensopfer; o. Abschlussopfer; o. Gemeinschaftsopfer\n℘ 5Mo 27,2-8"] },
      { number: 32, text: "Und er schrieb dort auf die Steine eine Abschrift des Gesetzes des Mose, die er vor den Söhnen Israel geschrieben hatte*.", footnotes: ["℘ 5Mo 27,2-8"] },
      { number: 33, text: "Und ganz Israel sowie seine Ältesten und Aufseher* und seine Richter standen an dieser und an jener Seite der Lade, den Priestern, den Leviten gegenüber, die die Lade des Bundes des HERRN trugen, der Fremde wie der Einheimische*, die eine Hälfte gegen den Berg Garizim hin und die andere Hälfte gegen den Berg Ebal hin*, wie Mose, der Knecht des HERRN, vormals geboten hatte, das Volk Israel zu segnen*.", footnotes: ["w. Schreiber; d. i. eine Beamtenbezeichnung", "℘ 4Mo 15,15.16.29; 5Mo 31,12", "℘ Joh 4,20", "℘ 5Mo 11,29"] },
      { number: 34, text: "Danach las er alle Worte des Gesetzes, den Segen und den Fluch, ganz wie es im Buch des Gesetzes geschrieben steht*.", footnotes: ["℘ 5Mo 27,14-26; 28; 31,11"] },
      { number: 35, text: "Es war kein Wort von allem, was Mose geboten hatte, das Josua nicht der ganzen Versammlung Israels vorgelesen hätte, ebenso den Frauen, den Kindern und dem Fremden, der in ihrer Mitte lebte*.", footnotes: ["w. einherging, o. wandelte\n℘ 5Mo 29,9-11.28; Neh 8,3; 1Thes 5,27"] },
    ]},
    { number: 9, verses: [
      { number: 1, text: "Und es geschah, als alle Könige es hörten, die jenseits des Jordan* waren, auf dem Gebirge und in der Niederung* und an der ganzen Küste des großen Meeres* in Richtung zum Libanon hin*, nämlich die Hetiter und die Amoriter, die Kanaaniter, die Perisiter, die Hewiter und die Jebusiter*:", heading: "Die Gibeoniter", footnotes: ["Gemeint ist das Westjordanland.", "hebr. Schefelah; d. i. der Küstenstreifen zwischen Jafo und Gaza\n℘ 5Mo 1,7", "d. i. das Mittelmeer", "℘ 4Mo 13,29", "℘ Kap. 3,10"] },
      { number: 2, text: "da versammelten sie sich allesamt, um einmütig gegen Josua und gegen Israel zu kämpfen*.", footnotes: ["℘ Kap. 10,5; 11,1-5; 24,11; Ps 83,4-6"] },
      { number: 3, text: "Die Bewohner von Gibeon* aber hatten gehört, was Josua an Jericho und an Ai getan hatte*.", footnotes: ["℘ Kap. 10,2; 18,25; 21,17; 2Sam 2,12; 2Chr 1,3", "℘ Kap. 6,21.24; 8,26-28; 10,1.28"] },
      { number: 4, text: "Da handelten auch sie mit List und gingen und verstellten sich als Boten*. Sie nahmen abgenutzte Säcke für ihre Esel und abgenutzte, zerrissene und geflickte Weinschläuche", footnotes: ["Andere Handschr. und die alten Üs.: und versahen sich mit Reiseproviant; vgl. V. 12"] },
      { number: 5, text: "sowie abgenutzte, geflickte Schuhe an ihre Füße und zogen abgenutzte Kleidung an. Und das gesamte Brot ihrer Wegzehrung war vertrocknet und zu Brotkrumen geworden." },
      { number: 6, text: "Und sie gingen zu Josua ins Lager nach Gilgal* und sagten zu ihm und zu den Männern von Israel: Aus einem fernen Land kommen wir. Nun denn, schließt mit uns einen Bund!", footnotes: ["℘ Kap. 4,19; 10,6"] },
      { number: 7, text: "Da sagten die Männer von Israel zu den Hewitern*: Vielleicht wohnst du in meiner Mitte, und wie könnte ich da mit dir einen Bund schließen*?", footnotes: ["℘ 1Mo 10,17; 2Sam 24,7", "℘ 2Mo 23,22"] },
      { number: 8, text: "Sie sagten zu Josua: Deine Knechte sind wir*! Und Josua sagte zu ihnen: Wer seid ihr, und woher kommt ihr?", footnotes: ["℘ Kap. 10,6"] },
      { number: 9, text: "Und sie sagten zu ihm: Aus einem sehr fernen Land sind deine Knechte gekommen*, um des Namens des HERRN, deines Gottes, willen. Denn wir haben die Kunde von ihm vernommen, alles, was er in Ägypten tat*,", footnotes: ["℘ 5Mo 20,11-15", "℘ 2Mo 15,14; Ps 78,12"] },
      { number: 10, text: "und alles, was er den beiden Königen der Amoriter tat, die jenseits des Jordan waren, Sihon, dem König von Heschbon, und Og, dem König von Baschan, der zu Aschtarot wohnte*.", footnotes: ["℘ Kap. 2,10"] },
      { number: 11, text: "Da sagten unsere Ältesten und alle Bewohner unseres Landes zu uns: Nehmt* Wegzehrung mit auf den Weg und geht ihnen entgegen und sagt zu ihnen: Eure Knechte sind wir; nun denn, schließt mit uns einen Bund!", footnotes: ["w. Nehmt in eure Hand"] },
      { number: 12, text: "Da ist unser Brot. Noch warm haben wir es zur Wegzehrung aus unsern Häusern mitgenommen am Tag, als wir auszogen, um zu euch zu gehen; und nun siehe, es ist vertrocknet und zu Brotkrumen geworden." },
      { number: 13, text: "Und diese Weinschläuche, die neu waren, als wir sie füllten, siehe, sie sind zerrissen. Und diese unsere Kleider und unsere Schuhe sind abgenutzt von dem sehr langen Weg. —" },
      { number: 14, text: "Da nahmen die Männer* von ihrer Wegzehrung*. Den Mund des HERRN aber befragten sie nicht*.", footnotes: ["LXX: Fürsten", "o. Da nahmen sich die Männer ihre Wegzehrung vor; d. h. sie begutachteten sie", "℘ 4Mo 27,21; 1Chr 10,14; Jes 30,1.2"] },
      { number: 15, text: "Und Josua machte Frieden mit ihnen* und schloss mit ihnen einen Bund, sie am Leben zu lassen; und die Fürsten der Gemeinde schworen ihnen*.", footnotes: ["℘ Kap. 11,19", "℘ 2Sam 21,2"] },
      { number: 16, text: "Und es geschah nach Ablauf von drei Tagen, nachdem sie einen Bund mit ihnen geschlossen hatten, da hörten sie, dass jene aus ihrer Nähe* waren und mitten unter ihnen wohnten.", footnotes: ["w. nahe bei ihnen"] },
      { number: 17, text: "Da brachen die Söhne Israel auf und kamen zu ihren Städten am dritten Tag; ihre Städte aber waren Gibeon, Kefira, Beerot* und Kirjat-Jearim.", footnotes: ["℘ Kap. 18,25; Esr 2,25"] },
      { number: 18, text: "Und die Söhne Israel schlugen sie nicht, weil die Fürsten der Gemeinde ihnen bei dem HERRN, dem Gott Israels, geschworen hatten*. Da murrte die ganze Gemeinde über die Fürsten.", footnotes: ["℘ 4Mo 30,3; 5Mo 23,24; Ps 15,4; Mt 5,33"] },
      { number: 19, text: "Und alle Fürsten sagten zu der ganzen Gemeinde: Wir haben ihnen bei dem HERRN, dem Gott Israels, geschworen, und nun können wir sie nicht antasten." },
      { number: 20, text: "Das wollen wir ihnen tun und sie am Leben lassen, damit nicht ein Zorn über uns kommt um des Eides willen, den wir ihnen geschworen haben*.", footnotes: ["℘ 2Sam 21,1-6; Hes 17,15-19; Sach 5,3.4"] },
      { number: 21, text: "Und die Fürsten sagten zu ihnen: Sie sollen am Leben bleiben. Und sie wurden Holzhauer und Wasserschöpfer für die ganze Gemeinde*, wie die Fürsten ihnen zugesagt hatten.", footnotes: ["℘ Kap. 10,1; 5Mo 29,10"] },
      { number: 22, text: "Und Josua rief sie und redete zu ihnen: Warum habt ihr uns getäuscht und gesagt: »Sehr weit sind wir von euch weg«, da ihr doch mitten unter uns wohnt?" },
      { number: 23, text: "Und nun, verflucht seid ihr! Ihr sollt nicht aufhören, Knechte zu sein*, sowohl Holzhauer als auch Wasserschöpfer für das Haus meines Gottes!", footnotes: ["w. Und es soll nicht aufhören unter euch der Knecht\n℘ 1Mo 9,25.26"] },
      { number: 24, text: "Sie antworteten Josua und sagten: Weil deinen Knechten zuverlässig berichtet wurde, dass der HERR, dein Gott, seinem Knecht Mose geboten hat, euch das ganze Land zu geben und alle Einwohner des Landes vor euch auszurotten*, darum fürchteten wir sehr um unser Leben*, als wir von euch hörten, und haben das getan.", footnotes: ["℘ Kap. 6,21", "℘ Kap. 2,9; 10,2; Hi 2,4"] },
      { number: 25, text: "Und nun siehe, wir sind in deiner Hand. Wie es gut und wie es recht ist in deinen Augen, uns zu tun, so mach es mit uns*!", footnotes: ["℘ 2Sam 15,26; 2Kö 10,5; Jer 26,14"] },
      { number: 26, text: "Und er machte es so mit ihnen und rettete sie aus der Hand der Söhne Israel; und sie brachten sie nicht um." },
      { number: 27, text: "So machte Josua sie an jenem Tag zu Holzhauern und Wasserschöpfern für die Gemeinde und für den Altar des HERRN*, bis zum heutigen Tag, an dem Ort, den er erwählen würde.*", footnotes: ["℘ 4Mo 31,28-30", "℘ 5Mo 12,5.11; 2Chr 2,16; Joh 4,20"] },
    ]},
    { number: 10, verses: [
      { number: 1, text: "Und es geschah, als Adoni-Zedek, der König von Jerusalem, hörte, dass Josua Ai eingenommen und an ihm den Bann vollstreckt habe, dass er es mit Ai und seinem König ebenso gemacht habe, wie er es mit Jericho und seinem König gemacht hatte*, und dass die Bewohner von Gibeon Frieden mit Israel gemacht hätten und in ihrer Mitte seien*:", heading: "Eroberung des Südteils von Kanaan", footnotes: ["℘ Kap. 9,3", "℘ Kap. 9,21"] },
      { number: 2, text: "Da fürchteten sie sich sehr*. Denn Gibeon* war eine große Stadt, wie eine der Königsstädte, ja, es war größer als Ai, und alle seine Männer waren Krieger.", footnotes: ["℘ Kap. 9,24; 5Mo 2,25", "℘ Kap. 9,3"] },
      { number: 3, text: "Und Adoni-Zedek, der König von Jerusalem, sandte zu Hoham, dem König von Hebron, und zu Piram, dem König von Jarmut, und zu Jafia, dem König von Lachisch, und zu Debir, dem König von Eglon, und ließ ihnen sagen:" },
      { number: 4, text: "Kommt zu mir herauf und helft mir, dass wir Gibeon schlagen! Denn es hat mit Josua und mit den Söhnen Israel Frieden gemacht." },
      { number: 5, text: "Da sammelten sich die fünf Könige der Amoriter und zogen hinauf: der König von Jerusalem, der König von Hebron, der König von Jarmut, der König von Lachisch, der König von Eglon, sie und alle ihre Heerlager; und sie belagerten Gibeon und kämpften gegen die Stadt*.", footnotes: ["w. gegen sie\n℘ Kap. 9,2"] },
      { number: 6, text: "Da sandten die Männer von Gibeon zu Josua ins Lager nach Gilgal* und ließen sagen: Zieh deine Hände nicht ab von deinen Knechten*! Komm eilends zu uns herauf und rette uns und hilf uns! Denn gegen uns haben sich versammelt alle Könige der Amoriter, die im Gebirge wohnen.", footnotes: ["℘ Kap. 9,6", "℘ Kap. 9,8.23"] },
      { number: 7, text: "Da zog Josua von Gilgal hinauf, er und alles Kriegsvolk mit ihm und alle tüchtigen Krieger*.", footnotes: ["℘ Kap. 8,3"] },
      { number: 8, text: "Und der HERR sprach zu Josua: Fürchte dich nicht vor ihnen*! Denn in deine Hand habe ich sie gegeben*; kein Mann von ihnen wird vor dir standhalten*.", footnotes: ["℘ Kap. 1,9; Apg 18,9.10", "℘ Kap. 11,6; 5Mo 3,2; 20,1-4; Ri 4,14; 1Sam 17,47; 1Kö 20,13", "℘ Kap. 1,5; Ri 6,16"] },
      { number: 9, text: "Und Josua kam plötzlich über sie*. Die ganze Nacht war er von Gilgal hinaufgezogen.", footnotes: ["℘ Kap. 11,7"] },
      { number: 10, text: "Der HERR aber verwirrte sie vor Israel*. Und er fügte ihnen bei Gibeon eine schwere Niederlage zu* und jagte ihnen nach auf dem Weg zur Höhe* von Bet-Horon* und schlug sie bis Aseka* und bis Makkeda.", footnotes: ["℘ 5Mo 7,23; Ri 4,15.16; 1Sam 7,10.11", "w. er schlug sie, einen großen Schlag bei Gibeon\n℘ Ri 5,20", "w. zum Aufstieg; o. Anstieg", "℘ 1Sam 13,18; 2Chr 25,13", "℘ Kap. 15,35"] },
      { number: 11, text: "Und es geschah, als sie vor Israel flohen — sie waren gerade am Abhang von Bet-Horon —, da warf der HERR große Steine vom Himmel auf sie herab*, bis Aseka, so dass sie umkamen*. Es waren mehr, die durch die Hagelsteine umkamen, als die, welche die Söhne Israel mit dem Schwert umbrachten*.", footnotes: ["℘ Ri 5,20", "℘ 2Mo 9,22-25; Ps 18,13-15; Hi 38,23; Jes 30,30; Offb 16,21", "℘ 5Mo 20,4; Jes 28,21"] },
      { number: 12, text: "Damals redete Josua zum HERRN*, und zwar an dem Tag, als der HERR die Amoriter vor den Söhnen Israel dahingab, und sagte vor den Augen Israels: Sonne, stehe still zu Gibeon, und Mond, im Tal Ajalon*!", footnotes: ["℘ 1Sam 12,18", "℘ Kap. 19,42; 21,24; 1Sam 14,31; 1Chr 8,13; 2Chr 11,10"] },
      { number: 13, text: "Da stand die Sonne still, und der Mond blieb stehen*, bis das Volk* sich an seinen Feinden gerächt hatte. Ist das nicht geschrieben im Buch Jaschar*? Die Sonne blieb stehen mitten am Himmel und beeilte sich nicht unterzugehen, ungefähr einen ganzen Tag lang*.", footnotes: ["℘ Hi 9,7; Hab 3,11", "w. Nation; hier im Sinne von Kriegsschar", "d. h. des Rechtschaffenen, o. des Aufrichtigen\n℘ 2Sam 1,18", "℘ 2Kö 20,10.11"] },
      { number: 14, text: "Und es war kein Tag wie dieser, weder vorher noch danach, dass der HERR so auf die Stimme eines Menschen gehört hätte; denn der HERR kämpfte für Israel*.", footnotes: ["℘ V. 42; Kap. 23,3.10; 2Mo 14,14.25; Sach 14,3"] },
      { number: 15, text: "Dann kehrte Josua — und ganz Israel mit ihm — ins Lager nach Gilgal zurück*.", footnotes: ["℘ V. 43; 2Sam 12,31"] },
      { number: 16, text: "Jene fünf Könige aber flohen* und versteckten sich in der Höhle zu Makkeda.", footnotes: ["℘ Ps 68,13"] },
      { number: 17, text: "Da wurde dem Josua mitgeteilt: Die fünf Könige sind gefunden worden, versteckt in der Höhle zu Makkeda." },
      { number: 18, text: "Und Josua sagte: Wälzt große Steine an den Eingang der Höhle und stellt Männer an ihr auf, um sie zu bewachen!" },
      { number: 19, text: "Ihr aber, steht nicht still, sondern jagt euren Feinden nach* und schlagt ihre Nachhut*! Lasst sie nicht in ihre Städte kommen! Denn der HERR, euer Gott, hat sie in eure Hand gegeben.", footnotes: ["℘ Jer 48,10", "w. stutzt ihren Schweif"] },
      { number: 20, text: "Und es geschah, als Josua und die Söhne Israel ihnen endgültig eine sehr schwere Niederlage zugefügt hatten*, bis sie vollständig aufgerieben waren* — die Entronnenen von ihnen aber entkamen in die befestigten Städte* —,", footnotes: ["w. Und es geschah, als Josua und die Söhne Israel aufgehört hatten, sie mit einem sehr großen Schlag zu schlagen; vgl. V. 10", "℘ Kap. 11,8.14; 1Kö 20,21", "w. und die Entronnenen von ihnen entrannen und kamen in die Städte der Befestigung"] },
      { number: 21, text: "da kehrte das ganze Volk im Frieden zu Josua zurück, in das Lager nach Makkeda; niemand spitzte seine Zunge gegen die Söhne Israel*.", footnotes: ["℘ 2Mo 11,7"] },
      { number: 22, text: "Und Josua sprach: Öffnet den Eingang der Höhle und bringt diese fünf Könige aus der Höhle zu mir heraus*!", footnotes: ["℘ Kap. 8,23; 1Sam 15,32"] },
      { number: 23, text: "Sie taten es und brachten diese fünf Könige aus der Höhle zu ihm heraus: den König von Jerusalem, den König von Hebron, den König von Jarmut, den König von Lachisch, den König von Eglon*.", footnotes: ["℘ Kap. 12,10-12"] },
      { number: 24, text: "Und es geschah, als sie diese Könige zu Josua herausgebracht hatten, da rief Josua alle Männer von Israel zusammen und sagte zu den Anführern der Kriegsleute, die mit ihm zogen: Tretet heran, setzt eure Füße auf die Nacken* dieser Könige! Da traten sie heran und setzten ihre Füße auf ihre Nacken.", footnotes: ["℘ 2Sam 22,39; Mal 3,21"] },
      { number: 25, text: "Und Josua sagte zu ihnen: Fürchtet euch nicht und erschreckt nicht*, seid stark und mutig!* Denn genauso wird der HERR mit allen euren Feinden verfahren, gegen die ihr kämpft*.", footnotes: ["o. und seid nicht niedergeschlagen", "℘ Kap. 1,6.9; 1Kor 16,13", "℘ 5Mo 7,19-24"] },
      { number: 26, text: "Danach erschlug Josua sie. Er tötete sie* und hängte sie an fünf Bäumen* auf; und sie blieben an den Bäumen* aufgehängt bis zum Abend*.", footnotes: ["℘ Ri 8,21; Ps 18,41; 149,7-9", "o. Hölzern; o. Pfählen", "o. Hölzern; o. Pfählen", "℘ Kap. 8,29; 5Mo 21,23"] },
      { number: 27, text: "Und es geschah zur Zeit des Sonnenuntergangs, da gab Josua Befehl, und man nahm sie von den Bäumen* herab* und warf sie in die Höhle, wo sie sich versteckt gehalten hatten. Und man legte große Steine vor den Eingang der Höhle, die noch bis zum heutigen Tag da sind.", footnotes: ["o. Hölzern; o. Pfählen", "℘ Kap. 8,29; 5Mo 21,23"] },
      { number: 28, text: "Und Josua nahm an demselben Tag Makkeda ein und schlug es mit der Schärfe des Schwertes. Und an seinem König, an der Stadt* und an allem Leben, das* in ihr war, vollstreckte er den Bann: Er ließ keinen Entronnenen übrig. Und er machte es mit dem König von Makkeda, wie er es mit dem König von Jericho gemacht hatte*. —", footnotes: ["w. an ihnen", "w. an jeder Seele, die", "℘ Kap. 9,3; 12,15.16"] },
      { number: 29, text: "Dann zog Josua und ganz Israel mit ihm von Makkeda nach Libna* und kämpfte gegen Libna.", footnotes: ["℘ Kap. 12,15; 21,13; 2Kö 19,8; 2Chr 21,10"] },
      { number: 30, text: "Und der HERR gab auch dies in die Hand Israels mitsamt seinem König. Und er schlug es* mit der Schärfe des Schwertes und alles Leben, das darin war*: Er ließ keinen Entronnenen darin übrig. Und er tat seinem König, wie er dem König von Jericho getan hatte*. —", footnotes: ["d. i. die Stadt Libna", "w. alle Seelen, die darin waren", "℘ Kap. 9,3; 12,15.16"] },
      { number: 31, text: "Dann zog Josua und ganz Israel mit ihm von Libna nach Lachisch*; und er belagerte es und kämpfte gegen es.", footnotes: ["℘ Kap. 15,39; 2Kö 14,19; 2Chr 11,9"] },
      { number: 32, text: "Und der HERR gab Lachisch in die Hand Israels. Und er nahm es am zweiten Tag ein und schlug es mit der Schärfe des Schwertes und alles Leben, das darin war*, genauso, wie er Libna getan hatte.", footnotes: ["w. alle Seelen, die darin waren"] },
      { number: 33, text: "Damals zog Horam, der König von Geser*, herauf, um Lachisch zu helfen. Aber Josua schlug ihn und sein Volk, so dass keiner entrinnen konnte*. —", footnotes: ["℘ Kap. 12,12; 21,21; 2Sam 5,25", "w. bis ihm kein Entronnener übrig blieb"] },
      { number: 34, text: "Dann zog Josua und ganz Israel mit ihm von Lachisch nach Eglon; und sie belagerten es und kämpften gegen es." },
      { number: 35, text: "Und sie nahmen es an demselben Tag ein und schlugen es mit der Schärfe des Schwertes. Und an allem Leben, das darin war*, vollstreckte er den Bann an demselben Tag, genauso, wie er es mit Lachisch gemacht hatte. —", footnotes: ["w. allen Seelen, die darin waren"] },
      { number: 36, text: "Dann zog Josua und ganz Israel mit ihm von Eglon nach Hebron hinauf, und sie kämpften gegen es." },
      { number: 37, text: "Und sie nahmen es ein und schlugen es mit der Schärfe des Schwertes mitsamt seinem König und allen seinen Städten* und allem Leben, das darin war*: Er ließ keinen Entronnenen übrig, genauso, wie er es mit Eglon gemacht hatte: Er vollstreckte den Bann an ihm und an allem Leben, das darin war*. —", footnotes: ["d. h. die Städte von Hebron", "w. allen Seelen, die darin waren", "w. allen Seelen, die darin waren"] },
      { number: 38, text: "Dann wandte sich Josua und ganz Israel mit ihm nach Debir* und kämpfte gegen es.", footnotes: ["℘ Kap. 21,15"] },
      { number: 39, text: "Und er nahm es ein mitsamt seinem König und allen seinen Städten*. Und sie schlugen sie mit der Schärfe des Schwertes und vollstreckten an allem Leben, das darin war*, den Bann*: Er ließ keinen Entronnenen übrig. Wie er es mit Hebron gemacht und wie er es mit Libna und seinem König gemacht hatte, ebenso machte er es auch mit Debir und seinem König*.", footnotes: ["d. h. die Städte von Debir", "w. allen Seelen, die darin waren", "℘ 1Sam 15,3.8.18", "℘ Kap. 12,13"] },
      { number: 40, text: "So schlug Josua das ganze Land, das Gebirge*, das Südland*, die Niederung*, die Berghänge und all ihre Könige: Er ließ keinen Entronnenen übrig*. An allem Lebenden* vollstreckte er den Bann, wie der HERR, der Gott Israels, geboten hatte*.", footnotes: ["℘ 4Mo 13,17", "hebr. Negev; d. i. die Südgegend von Palästina", "hebr. Schefelah; d. i. der Küstenstreifen zwischen Jafo und Gaza\n℘ Kap. 12,8", "℘ 5Mo 2,34", "w. Lebensatem", "℘ Neh 9,24; 2Mo 23,32.33"] },
      { number: 41, text: "Und Josua schlug sie von Kadesch-Barnea* bis Gaza* und das ganze Land Goschen bis Gibeon.", footnotes: ["℘ 5Mo 1,19", "℘ 5Mo 2,23"] },
      { number: 42, text: "Und alle diese Könige sowie ihr Land nahm Josua auf einmal. Denn der HERR, der Gott Israels, kämpfte für Israel*.", footnotes: ["℘ V. 14"] },
      { number: 43, text: "Dann kehrte Josua und ganz Israel mit ihm ins Lager nach Gilgal zurück*.", footnotes: ["℘ V. 15"] },
    ]},
    { number: 11, verses: [
      { number: 1, text: "Und es geschah, als Jabin, der König von Hazor*, es hörte, sandte er zu Jobab, dem König von Madon*, und zum König von Schimron und zum König von Achschaf*", heading: "Siege im Norden Kanaans und Eroberung des übrigen Landes", footnotes: ["℘ Kap. 12,19; 19,36; Ri 4,2; 1Kö 9,15; 2Kö 15,29", "℘ Kap. 9,3; 12,15.16", "℘ Kap. 12,20"] },
      { number: 2, text: "und zu den Königen, die im Norden im Gebirge und in der Steppe* südlich von Kinneret* und in der Niederung* und im Hügelland von Dor* im Westen waren,", footnotes: ["hebr. Araba; vgl. Anm. zu Kap. 3,16", "im NT »See Genezareth« genannt\n℘ 4Mo 34,11; 1Kö 15,20", "hebr. Schefelah; d. i. der Küstenstreifen zwischen Jafo und Gaza", "℘ Kap. 12,23"] },
      { number: 3, text: "zu den Kanaanitern im Osten und im Westen, zu den Amoritern, den Hetitern, den Perisitern und den Jebusitern auf dem Gebirge* und zu den Hewitern am Fuß des Hermon im Land Mizpa.", footnotes: ["℘ Kap. 3,10"] },
      { number: 4, text: "Und sie zogen aus, sie und ihr ganzes Heerlager mit ihnen, ein Volk, so zahlreich wie der Sand, der am Ufer des Meeres ist, an Menge*, sowie sehr viele Pferde und Wagen*.", footnotes: ["℘ Ri 7,12; 1Sam 13,5; 2Sam 17,11", "℘ Ps 20,8"] },
      { number: 5, text: "All diese Könige trafen zusammen. Sie kamen und lagerten miteinander am Wasser Merom, um gegen Israel zu kämpfen*.", footnotes: ["℘ Kap. 9,2; 2Sam 10,15.16; Ps 48,5"] },
      { number: 6, text: "Da sprach der HERR zu Josua: Fürchte dich nicht vor ihnen*! Denn morgen um diese Zeit werde ich sie alle vor Israel zu Erschlagenen machen. Ihre Pferde sollst du lähmen* und ihre Wagen mit Feuer verbrennen*.", footnotes: ["℘ Kap. 10,8; 2Kö 6,16", "d. h. die Sehnen der Füße durchschneiden\n℘ 2Sam 8,4", "℘ Ps 46,10"] },
      { number: 7, text: "Und Josua und alles Kriegsvolk mit ihm kam plötzlich über sie am Wasser Merom, und sie überfielen sie*.", footnotes: ["℘ Kap. 10,9"] },
      { number: 8, text: "Und der HERR gab sie in die Hand Israels, und sie schlugen sie und jagten ihnen nach bis Sidon*, der großen Stadt, und bis Misrefot-Majim und bis in die Talebene von Mizpe im Osten. Und sie schlugen sie, so dass ihnen kein Entronnener übrig blieb*.", footnotes: ["℘ 2Sam 24,6", "℘ Kap. 10,20; 13,6; 21,44; 5Mo 7,2.16; 9,3"] },
      { number: 9, text: "Josua machte es mit ihnen, wie der HERR ihm gesagt hatte: Ihre Pferde lähmte er*, und ihre Wagen verbrannte er mit Feuer*.", footnotes: ["℘ Ps 46,10", "℘ Ps 46,10"] },
      { number: 10, text: "In jener Zeit kehrte Josua um und nahm Hazor ein, und seinen König erschlug er mit dem Schwert. Denn Hazor war damals* die Hauptstadt all dieser Königreiche.", footnotes: ["w. zuvor"] },
      { number: 11, text: "Und sie schlugen alles Leben, das* darin war, mit der Schärfe des Schwertes, indem sie den Bann an ihnen vollstreckten: Nichts Lebendes* blieb übrig. Hazor aber verbrannte er mit Feuer*.", footnotes: ["o. jede Seele, die", "w. kein(en) Lebensatem", "℘ Kap. 6,21.24"] },
      { number: 12, text: "Alle Städte dieser Könige mit all ihren Königen nahm Josua ein und schlug sie mit der Schärfe des Schwertes. Er vollstreckte den Bann an ihnen, wie Mose, der Knecht des HERRN, befohlen hatte*.", footnotes: ["℘ Kap. 10,20; 13,6; 21,44; 5Mo 7,2.16; 9,3"] },
      { number: 13, text: "Nur all die Städte, die auf Hügeln* standen, verbrannte Israel nicht*, ausgenommen Hazor allein, das verbrannte Josua.", footnotes: ["w. auf ihrem Hügel", "℘ Kap. 24,13"] },
      { number: 14, text: "Die ganze Beute dieser Städte sowie das Vieh plünderten die Söhne Israel für sich*. Doch alle Menschen schlugen sie mit der Schärfe des Schwertes, bis sie sie vernichtet hatten: Sie ließen nichts Lebendes* übrig.", footnotes: ["℘ Kap. 8,2; 2Chr 20,25", "w. kein(en) Lebensatem"] },
      { number: 15, text: "Wie der HERR seinem Knecht Mose befohlen hatte, so befahl Mose Josua, und so machte es Josua. Er unterließ nichts von allem, das der HERR dem Mose befohlen hatte*.", footnotes: ["℘ Kap. 1,7; 4Mo 33,50-52; 5Mo 31,3-5"] },
      { number: 16, text: "So nahm Josua dieses ganze Land, das Gebirge, den ganzen Süden, das ganze Land Goschen, die Niederung und die Steppe*, das Gebirge Israel und seine Niederung*,", footnotes: ["hebr. Araba; vgl. Anm. zu Kap. 3,16", "hebr. Schefelah; d. i. der Küstenstreifen zwischen Jafo und Gaza"] },
      { number: 17, text: "von dem kahlen Gebirge, das gegen Seïr ansteigt, bis Baal-Gad in der Talebene des Libanon, am Fuße des Berges Hermon*. Und alle ihre Könige nahm er gefangen, erschlug sie und tötete sie*.", footnotes: ["℘ Kap. 13,5; 5Mo 1,7", "℘ Kap. 12,7-24; 5Mo 7,24"] },
      { number: 18, text: "Lange Zeit führte Josua mit all diesen Königen Krieg." },
      { number: 19, text: "Es gab keine Stadt, die sich den Söhnen Israel friedlich ergab, außer den Hewitern, die in Gibeon wohnten*, alles andere nahmen sie im Kampf ein.", footnotes: ["w. den Bewohnern Gibeons\n℘ Kap. 9,15"] },
      { number: 20, text: "Denn vom HERRN kam es*, dass sie ihr Herz verstockten*, so dass es zum Krieg mit Israel kam, damit an ihnen der Bann vollstreckt würde, ohne dass ihnen Gnade widerführe, sondern dass sie vernichtet würden*, wie der HERR dem Mose befohlen hatte.", footnotes: ["℘ Ri 14,4; 1Sam 2,25; 2Chr 22,7; Jes 14,24", "℘ 2Mo 14,4.17; 5Mo 2,30", "℘ 2Sam 17,14; Jes 34,2"] },
      { number: 21, text: "Zu jener Zeit kam Josua und rottete die Enakiter aus* von dem Gebirge, von Hebron, von Debir, von Anab und von dem ganzen Gebirge Juda und von dem ganzen Gebirge Israel: Mitsamt ihren Städten vollstreckte Josua an ihnen den Bann.", footnotes: ["℘ Kap. 14,12; 15,13.14; 4Mo 13,22; 5Mo 9,2; Ri 1,20"] },
      { number: 22, text: "Es blieben keine Enakiter im Land der Söhne Israel übrig. Nur in Gaza*, in Gat und in Aschdod* blieben sie übrig.", footnotes: ["℘ Kap. 10,41; 15,47; 1Sam 5,1; 1Sam 17,4; 2Sam 21,16-22", "℘ Kap. 10,41; 15,47; 1Sam 5,1; 1Sam 17,4; 2Sam 21,16-22"] },
      { number: 23, text: "Und so nahm Josua das ganze Land ein, ganz wie der HERR zu Mose geredet hatte*. Und Josua gab es Israel zum Erbteil, nach ihren Abteilungen, entsprechend ihren Stämmen*. Und das Land hatte Ruhe vom Krieg*.", footnotes: ["℘ 4Mo 34,2-13", "℘ Kap. 12,7; 14-19; 4Mo 26,53", "℘ Kap. 14,15; 21,44; 5Mo 12,10"] },
    ]},
    { number: 12, verses: [
      { number: 1, text: "*Dies sind die Könige des Landes, die die Söhne Israel schlugen und deren Land sie in Besitz nahmen jenseits des Jordan, gegen Sonnenaufgang, vom Fluss Arnon bis zum Berg Hermon, und die ganze Steppe* nach Osten zu:", heading: "Liste der besiegten Könige", footnotes: ["℘ V. 1-6: 4Mo 21,21-35; 5Mo 2,32-37; 3,1-7; 4,46-49", "hebr. Araba; vgl. Anm. zu Kap. 3,16"] },
      { number: 2, text: "Sihon, der König der Amoriter, der in Heschbon wohnte*, er herrschte über das Gebiet von Aroër an, das am Ufer des Flusses Arnon liegt, und zwar von der Mitte des Flusstales an, und über das halbe Gilead bis an den Fluss Jabbok, die Grenze der Söhne Ammon,", footnotes: ["℘ 5Mo 1,4"] },
      { number: 3, text: "und über die Steppe* bis an den See Kinneret* im Osten*, und bis ans Meer der Steppe*, das Salzmeer*, im Osten*, nach Bet-Jeschimot hin und im Süden an den Fuß der Abhänge des Pisga*.", footnotes: ["hebr. Araba; vgl. Anm. zu Kap. 3,16", "℘ Kap. 11,2", "d. h. an das Ostufer des", "d. i. das Tote Meer", "℘ Kap. 3,16", "d. i. das Tote Meer", "Pisga ist das Randgebirge der moabitischen Hochebene nordöstlich vom Toten Meer."] },
      { number: 4, text: "Und das Gebiet des Königs Og von Baschan, von dem Rest der Refaïter, der in Aschtarot und in Edreï wohnte*.", footnotes: ["℘ Kap. 13,12; 5Mo 1,4; 3,11"] },
      { number: 5, text: "Und er herrschte über das Hermongebirge, über Salcha und über ganz Baschan bis an die Grenze der Geschuriter und der Maachatiter und über halb Gilead bis an die Grenze Sihons, des Königs von Heschbon." },
      { number: 6, text: "Mose, der Knecht des HERRN, und die Söhne Israel schlugen sie. Und Mose, der Knecht des HERRN, gab es als Besitz den Rubenitern, den Gaditern und dem halben Stamm Manasse.*", footnotes: ["℘ Kap. 13,8-12; 14,3; 18,7; 22,4; 4Mo 32,32; 1Kö 4,19"] },
      { number: 7, text: "Dies sind die Könige des Landes, die Josua und die Söhne Israel schlugen diesseits des Jordan, im Westen, von Baal-Gad an in der Talebene des Libanon bis an das kahle Gebirge, das nach Seïr hin ansteigt. — Und Josua gab es den Stämmen Israels zum Besitz nach ihren Abteilungen,*", footnotes: ["℘ Kap. 11,23"] },
      { number: 8, text: "im Gebirge, in der Niederung*, in der Steppe, an den Abhängen, in der Wüste und im Süden* — die Hetiter, die Amoriter, die Kanaaniter, die Perisiter, die Hewiter und die Jebusiter*:", footnotes: ["hebr. Schefelah; d. i. der Küstenstreifen zwischen Jafo und Gaza", "℘ Kap. 10,40; 11,16.17; Ri 1,9", "℘ Kap. 3,10"] },
      { number: 9, text: "der König von Jericho*: einer; der König von Ai*, das neben Bethel liegt: einer;", footnotes: ["℘ Kap. 6,2", "℘ Kap. 8,29"] },
      { number: 10, text: "der König von Jerusalem: einer; der König von Hebron: einer;" },
      { number: 11, text: "der König von Jarmut: einer; der König von Lachisch: einer;" },
      { number: 12, text: "der König von Eglon*: einer; der König von Geser*: einer;", footnotes: ["℘ Kap. 10,23", "℘ Kap. 10,33"] },
      { number: 13, text: "der König von Debir*: einer; der König von Geder: einer;", footnotes: ["℘ Kap. 10,38.39"] },
      { number: 14, text: "der König von Horma: einer; der König von Arad*: einer;", footnotes: ["℘ 4Mo 21,1-3"] },
      { number: 15, text: "der König von Libna*: einer; der König von Adullam: einer;", footnotes: ["℘ Kap. 10,29.30"] },
      { number: 16, text: "der König von Makkeda*: einer; der König von Bethel: einer;", footnotes: ["℘ Kap. 10,28"] },
      { number: 17, text: "der König von Tappuach: einer; der König von Hefer*: einer;", footnotes: ["℘ 1Kö 4,10"] },
      { number: 18, text: "der König von Afek: einer; der König von Scharon: einer;" },
      { number: 19, text: "der König von Madon: einer; der König von Hazor*: einer;", footnotes: ["℘ Kap. 11,1"] },
      { number: 20, text: "der König von Schimron-Meron: einer; der König von Achschaf*: einer;", footnotes: ["℘ Kap. 11,1"] },
      { number: 21, text: "der König von Taanach*: einer; der König von Megiddo: einer;", footnotes: ["℘ Kap. 21,25; Ri 5,19"] },
      { number: 22, text: "der König von Kedesch: einer; der König von Jokneam* am Karmel: einer;", footnotes: ["℘ Kap. 21,34; 1Kö 4,12"] },
      { number: 23, text: "der König von Dor im Hügelland von Dor*: einer; der König von Gojim* zu Gilgal*: einer;", footnotes: ["℘ Kap. 11,2", "o. der Nationen; vgl. 1Mo 14,1", "LXX: in Galiläa"] },
      { number: 24, text: "der König von Tirza*: einer. Alle Könige zusammen waren 31*.", footnotes: ["℘ 1Kö 14,17", "℘ Neh 9,24; Ps 135,11"] },
    ]},
    { number: 13, verses: [
      { number: 1, text: "Als nun Josua alt und hochbetagt war*, da sprach der HERR zu ihm: Du bist alt geworden und bist hochbetagt, und sehr viel Land ist noch übrig, das in Besitz genommen werden muss*.", heading: "Noch nicht eroberte Gebiete", footnotes: ["℘ Kap. 23,1.2; 1Mo 18,11; 1Kö 1,1", "℘ Kap. 18,3"] },
      { number: 2, text: "Dies ist das Land, das noch übrig ist: alle Bezirke* der Philister* und ganz Geschur*;", footnotes: ["hebr. gelilot; viell. ein Ortsname: ganz Gelilot; vgl. Kap. 18,17", "℘ Zef 2,5", "℘ 1Sam 27,8"] },
      { number: 3, text: "vom Schihor an, der vor Ägypten* fließt*, bis zur Grenze von Ekron im Norden — es wird zum Gebiet der Kanaaniter gerechnet —, die fünf Fürsten der Philister*: der Gaziter, der Aschdoditer, der Aschkeloniter, der Gatiter, der Ekroniter und die Awiter*;", footnotes: ["d. h. östlich von Ägypten", "℘ 1Mo 15,18; 1Chr 13,5", "℘ Ri 3,3; 1Sam 5,8; 6,4", "℘ 5Mo 2,23"] },
      { number: 4, text: "im Süden* das ganze Land der Kanaaniter und Meara, das den Sidoniern gehört, bis Afek, bis an die Grenze der Amoriter;", footnotes: ["Die syr. Üs. schließt V. 3 erst nach »im Süden« ab: die Awiter im Süden, 4 das ganze"] },
      { number: 5, text: "und das Land der Gebaliter* und der ganze Libanon gegen Sonnenaufgang, von Baal-Gad, am Fuß des Hermongebirges*, bis man nach Hamat kommt*;", footnotes: ["℘ 1Kö 5,32; Hes 27,9", "℘ Kap. 11,17", "℘ 4Mo 34,8"] },
      { number: 6, text: "alle Bewohner des Gebirges, vom Libanon an bis Misrefot-Majim, alle Sidonier*. Ich selbst werde sie vor den Söhnen Israel vertreiben*. Nur verlose das Land für Israel als Erbteil*, wie ich dir befohlen habe!*", footnotes: ["℘ Kap. 11,8", "℘ Kap. 23,5; 2Mo 23,31", "w. wirf das Los über das Land zum Erbbesitz für Israel", "℘ Kap. 1,6; 14,1"] },
      { number: 7, text: "Und nun verteile dieses Land als Erbteil unter die neun Stämme und den halben Stamm Manasse*!", footnotes: ["℘ Kap. 14,2; 4Mo 34,13"] },
      { number: 8, text: "*Mit ihm* haben die Rubeniter und die Gaditer ihr Erbteil empfangen, das Mose ihnen gegeben hat jenseits des Jordan im Osten, wie Mose, der Knecht des HERRN, es ihnen gab*:", heading: "Ostjordanland für Ruben, Gad und den halben Stamm Manasse", footnotes: ["℘ 4Mo 32,33-42; 5Mo 3,8-17", "d. h. dem andern halben Stamm Manasse", "℘ Kap. 12,6"] },
      { number: 9, text: "von Aroër an, das am Ufer des Flusses Arnon liegt, und von der Stadt, die mitten im Flusstal liegt, und die ganze Ebene von Medeba* bis Dibon", footnotes: ["℘ 1Chr 19,7"] },
      { number: 10, text: "und alle Städte Sihons, des Königs der Amoriter, der König zu Heschbon war, bis zur Grenze der Söhne Ammon*,", footnotes: ["℘ 5Mo 2,19"] },
      { number: 11, text: "und Gilead* und das Gebiet der Geschuriter und der Maachatiter und das ganze Hermongebirge und ganz Baschan bis nach Salcha*,", footnotes: ["℘ 1Sam 13,7", "℘ 1Chr 5,11"] },
      { number: 12, text: "das ganze Reich des Og in Baschan, der König zu Aschtarot und zu Edreï war. Er war von dem Rest der Refaïter übrig geblieben; Mose aber hatte sie geschlagen und vertrieben*.", footnotes: ["℘ Kap. 12,4"] },
      { number: 13, text: "Aber die Söhne Israel vertrieben die Geschuriter und die Maachatiter nicht. Und so blieben Geschur und Maacha mitten in Israel wohnen bis zum heutigen Tag*.", footnotes: ["℘ 2Sam 3,3; 10,6"] },
      { number: 14, text: "Nur dem Stamm Levi gab er kein Erbteil. Die Feueropfer* des HERRN, des Gottes Israels, sind sein Erbteil, wie er ihm gesagt hatte*.", footnotes: ["w. Die Feuer", "℘ V. 33; 4Mo 18,20.23.24; Hes 44,28"] },
      { number: 15, text: "Und Mose gab dem Stamm der Söhne Ruben* seinen Anteil nach ihren Sippen.", footnotes: ["℘ 1Mo 35,23"] },
      { number: 16, text: "Es wurde ihnen das Gebiet zuteil: von Aroër an, das am Ufer des Flusses Arnon liegt, und von der Stadt, die mitten im Flusstal liegt, und die ganze Ebene bei Medeba*,", footnotes: ["℘ Kap. 14,3; 18,7; 4Mo 21,26.30; Ri 11,26"] },
      { number: 17, text: "Heschbon* und all seine Städte, die in der Ebene sind: Dibon, Bamot-Baal, Bet-Baal-Meon*,", footnotes: ["℘ Kap. 14,3; 18,7; 4Mo 21,26.30; Ri 11,26", "℘ 1Chr 5,8"] },
      { number: 18, text: "Jahaz, Kedemot*, Mefaat*,", footnotes: ["℘ 5Mo 2,26", "℘ Kap. 21,37; Jer 48,21.23"] },
      { number: 19, text: "Kirjatajim, Sibma, Zeret-Schahar auf dem Berg der Talebene," },
      { number: 20, text: "Bet-Peor, die Abhänge des Pisga, Bet-Jeschimot*", footnotes: ["℘ 4Mo 33,49; Hes 25,9"] },
      { number: 21, text: "und alle Städte der Ebene sowie das ganze Reich Sihons, des Königs der Amoriter, der König zu Heschbon war, den Mose schlug, ihn und die Fürsten von Midian: Ewi, Rekem, Zur*, Hur und Reba, die Fürsten* Sihons, die das Land bewohnten.", footnotes: ["℘ 4Mo 25,15", "d. h., dass diese Fürsten als Vasallen vom König Sihon eingesetzt waren"] },
      { number: 22, text: "Und Bileam, den Sohn des Beor, den Wahrsager, brachten die Söhne Israel mit dem Schwert um, außer den von ihnen Getöteten*.", footnotes: ["w. Durchbohrten\n℘ 4Mo 31,8"] },
      { number: 23, text: "Die Grenze der Söhne Ruben war der Jordan und das angrenzende Gebiet. Das ist das Erbteil der Söhne Ruben, nach ihren Sippen, die Städte und ihre Dörfer*.", footnotes: ["o. Gehöfte\n℘ Hes 48,6"] },
      { number: 24, text: "Und Mose gab dem Stamm Gad*, den Söhnen Gad, ihren Anteil, nach ihren Sippen.", footnotes: ["℘ 1Mo 35,26; Hes 48,27"] },
      { number: 25, text: "Und es wurde ihnen das Gebiet zuteil: Jaser und alle Städte Gileads und das halbe Land der Söhne Ammon bis nach Aroër*, das Rabba gegenüberliegt;", footnotes: ["℘ 2Sam 24,5; Jes 17,2"] },
      { number: 26, text: "und von Heschbon bis Ramat-Mizpe* und Betonim, und von Mahanajim bis an die Grenze von Debir*;", footnotes: ["℘ Ri 10,17", "Im Mas. T. steht »Lidebir«, viell. identisch mit dem Ort »Lo Dabar« in 2Sam 9,4.5; 17,27. Die LXX sowie die syr. und lat. Üs. (Vulgata) schreiben allerdings »Debir«."] },
      { number: 27, text: "und in der Talebene: Bet-Haram, Bet-Nimra, Sukkot und Zafon, der Rest des Reiches Sihons, des Königs von Heschbon, der Jordan und das angrenzende Gebiet bis an das Ende des Sees Kinneret*, jenseits des Jordan nach Osten zu.", footnotes: ["℘ Kap. 11,2"] },
      { number: 28, text: "Das ist das Erbteil der Söhne Gad nach ihren Sippen, die Städte und ihre Dörfer*.", footnotes: ["o. Gehöfte\n℘ 1Chr 5,16"] },
      { number: 29, text: "Und Mose gab dem halben Stamm Manasse seinen Anteil. Und dem halben Stamm der Söhne Manasse wurde nach ihren Sippen Folgendes zuteil." },
      { number: 30, text: "Ihr Gebiet war: von Mahanajim* an ganz Baschan, das ganze Reich des Og, des Königs von Baschan, und alle Zeltdörfer Jaïrs*, die in Baschan liegen*, sechzig Städte.", footnotes: ["℘ Kap. 21,38; 1Mo 32,3", "℘ 4Mo 32,41", "℘ 5Mo 3,4"] },
      { number: 31, text: "Und das halbe Gilead und Aschtarot und Edreï, die Städte des Reiches des Og in Baschan, wurden den Söhnen des Machir, des Sohnes Manasses, zuteil, der Hälfte der Söhne Machir, nach ihren Sippen*.", footnotes: ["℘ Kap. 17,5.6; Hes 48,4"] },
      { number: 32, text: "Das ist es, was Mose in den Steppen Moabs als Erbe ausgeteilt hat, jenseits des Jordan bei Jericho, nach Osten zu." },
      { number: 33, text: "Aber dem Stamm Levi gab Mose kein Erbteil. Der HERR, der Gott Israels, er ist ihr Erbteil, wie er ihnen zugesagt hat.*", footnotes: ["℘ V. 14"] },
    ]},
    { number: 14, verses: [
      { number: 1, text: "Und dies ist es, was die Söhne Israel als Erbe im Land Kanaan erhielten, was ihnen der Priester Eleasar und Josua, der Sohn des Nun, und die Familienoberhäupter* der Stämme der Söhne Israel* als Erbe austeilten*,", heading: "Vorbereitungen zur Auslosung des Westjordanlandes", footnotes: ["w. die Häupter der Väter", "℘ Kap. 21,1", "℘ Kap. 13,6; 19,51; 4Mo 34,17-29; 5Mo 12,10"] },
      { number: 2, text: "durch das Los ihres Erbteils*, wie der HERR durch Mose geboten hatte betreffs der neun Stämme und des halben Stammes*.", footnotes: ["℘ Kap. 18,6; 4Mo 26,52-56; Hes 45,1", "℘ Kap. 13,7"] },
      { number: 3, text: "Denn das Erbteil der zwei Stämme und des halben Stammes hatte Mose jenseits des Jordan gegeben*. Den Leviten aber hatte er kein Erbteil in ihrer Mitte gegeben*.", footnotes: ["℘ Kap. 12,6", "℘ Kap. 13,14.33"] },
      { number: 4, text: "Denn die Söhne Josef bildeten zwei Stämme, Manasse und Ephraim*. Und man gab den Leviten kein Teil im Land, außer den Städten zum Wohnen und deren Weideplätzen für ihr Vieh und für ihre Habe*.", footnotes: ["℘ Kap. 16,4; 1Mo 48,5", "℘ 4Mo 35,2.3"] },
      { number: 5, text: "Wie der HERR dem Mose geboten hatte, so taten die Söhne Israel, und sie verteilten das Land.*", footnotes: ["℘ Kap. 18,10"] },
      { number: 6, text: "Da traten die Söhne Juda vor Josua in Gilgal, und Kaleb, der Sohn des Jefunne*, der Kenasiter, sagte zu ihm: Du kennst das Wort, das der HERR zu Mose, dem Mann Gottes*, meinet- und deinetwegen in Kadesch-Barnea geredet hat.", heading: "Erbteil des Kaleb", footnotes: ["℘ 4Mo 13,6", "℘ 5Mo 33,1; 1Chr 23,14"] },
      { number: 7, text: "Vierzig Jahre war ich alt, als Mose, der Knecht des HERRN, mich von Kadesch-Barnea aussandte*, um das Land auszukundschaften; und ich brachte ihm Antwort, wie es in meinem Herzen war*.", footnotes: ["℘ 4Mo 13,26", "d. h. wie ich es mir vorgenommen hatte\n℘ 4Mo 13,30; Mt 12,34"] },
      { number: 8, text: "Meine Brüder aber, die mit mir hinaufgezogen waren, machten das Herz des Volkes verzagt*; ich aber bin dem HERRN, meinem Gott, treu nachgefolgt*.", footnotes: ["w. machten das Herz . . . zerfließen\n℘ 4Mo 13,31-33; 14,1-4; 5Mo 1,28", "w. und ich habe die Nachfolge hinter dem HERRN, meinem Gott, her erfüllt\n℘ 4Mo 14,24; 5Mo 1,36"] },
      { number: 9, text: "Da schwor Mose an demselben Tag: Wenn nicht das Land, auf das dein Fuß getreten ist, dir und deinen Söhnen für ewig zum Erbteil wird*! Denn du bist dem HERRN, meinem Gott, treu nachgefolgt*.", footnotes: ["Der Satz ist eine hebr. Schwurformel, deren zweite Hälfte nicht ausgesprochen wurde.\n℘ Kap. 1,3; Ps 37,9", "w. du hast die Nachfolge hinter dem HERRN, meinem Gott, her erfüllt; so sinngemäß auch V. 14"] },
      { number: 10, text: "Und nun siehe, der HERR hat mich am Leben erhalten, wie er geredet hat. Es sind nun 45 Jahre, seitdem der HERR dieses Wort zu Mose geredet hat, als Israel in der Wüste umherzog*; und nun siehe, ich bin heute 85 Jahre alt.", footnotes: ["℘ 4Mo 14,34.38"] },
      { number: 11, text: "Ich bin heute noch so stark wie an dem Tag, als Mose mich aussandte. Wie meine Kraft damals, so ist meine Kraft jetzt, sowohl zum Kampf als auch um aus- und einzuziehen*.", footnotes: ["℘ 5Mo 33,25; 34,7; Jes 40,31"] },
      { number: 12, text: "Und nun gib mir dieses Gebirge, von dem der HERR an jenem Tag geredet hat! Denn du hast an jenem Tag gehört, dass die Enakiter dort sind und große, feste Städte*. Vielleicht ist der HERR mit mir, dass ich sie vertreibe*, wie der HERR geredet hat*.", footnotes: ["℘ 4Mo 13,28", "℘ Kap. 11,21; 4Mo 14,8.9; 1Sam 14,6", "℘ 5Mo 9,1-3"] },
      { number: 13, text: "Da segnete ihn* Josua und gab dem Kaleb, dem Sohn des Jefunne, Hebron zum Erbteil*.", footnotes: ["℘ 1Mo 47,7.10", "℘ Kap. 15,13; 21,12; Ri 1,20; 1Sam 30,31; 1Chr 6,4; Neh 11,25"] },
      { number: 14, text: "Daher wurde Hebron dem Kaleb, dem Sohn des Jefunne, dem Kenasiter, zum Erbteil bis zum heutigen Tag, weil er dem HERRN, dem Gott Israels, treu nachgefolgt war*.", footnotes: ["℘ 2Chr 15,7; Gal 6,9"] },
      { number: 15, text: "Der Name Hebrons war aber vorher Kirjat-Arba*; er* war der größte Mann unter den Enakitern gewesen. — Und das Land hatte Ruhe vom Krieg*.", footnotes: ["o. Stadt des Arba\n℘ Kap. 15,13; 21,12; Ri 1,20; 1Sam 30,31; 1Chr 6,4; Neh 11,25", "d. h. Arba", "℘ Kap. 11,23"] },
    ]},
    { number: 15, verses: [
      { number: 1, text: "*Und das Los fiel* für den Stamm der Söhne Juda* nach ihren Sippen zur Grenze Edoms hin, der Wüste Zin, auf das Südland zu, im äußersten Süden.", heading: "Erbteil des Stammes Juda", footnotes: ["℘ V. 1-4: 4Mo 34,3-5", "w. wurde, o. war", "℘ 1Mo 35,23"] },
      { number: 2, text: "Und ihre Südgrenze verlief vom Ende des Salzmeeres, von der Meereszunge an, die sich nach Süden wendet," },
      { number: 3, text: "und sie lief bis südlich vom Anstieg Akrabbim* und ging hinüber nach Zin und stieg dann südlich von Kadesch-Barnea hinauf und ging hinüber nach Hezron, und sie stieg hinauf nach Addar und wandte sich nach Karka.", footnotes: ["o. von der Skorpionensteige"] },
      { number: 4, text: "Dann ging sie hinüber nach Azmon und lief aus am Bach Ägyptens*, und die Grenze endete am Meer. Das soll eure Südgrenze sein.", footnotes: ["℘ 1Kö 8,65; Jes 27,12"] },
      { number: 5, text: "*Und die Grenze nach Osten war das Salzmeer bis an das Ende des Jordan*. — Und die Grenze an der Nordseite war von der Meereszunge an, vom Ende des Jordan.", footnotes: ["℘ V. 5-9: Kap. 18,15-20", "d. h. seiner Einmündung ins Tote Meer\n℘ 4Mo 34,12"] },
      { number: 6, text: "Und die Grenze stieg hinauf nach Bet-Hogla und ging hinüber nördlich von Bet-Araba; und die Grenze stieg hinauf zum Stein Bohans, des Sohnes Rubens." },
      { number: 7, text: "Die Grenze stieg dann vom Tal Achor hinauf nach Debir, und sie wandte sich nördlich nach Gilgal*, welches dem Anstieg von Adummim gegenüberliegt, der südlich vom Bach ist. Und die Grenze ging hinüber zum Wasser En-Schemesch und sie endete bei* En-Rogel*.", footnotes: ["viell. urspr. Gelilot; vgl. Kap. 18,17", "w. ihr Ausläufer war nach", "℘ 2Sam 17,17"] },
      { number: 8, text: "Und die Grenze stieg das Tal Ben-Hinnom hinauf, südlich zum Berghang* der Jebusiter, das ist Jerusalem*. Und die Grenze stieg an bis zum Gipfel des Berges, der sich vor dem Tal Hinnom* nach Westen zu erhebt, der am Ende der Refaïm-Talebene* nach Norden zu liegt.", footnotes: ["w. zur Schulter", "℘ V. 63; Kap. 18,28", "℘ 2Kö 23,10; Jer 7,31; 19,2", "℘ 2Sam 5,18.22; Jes 17,5"] },
      { number: 9, text: "Dann zog sich die Grenze vom Gipfel des Berges herum in Richtung auf die Quelle Me-Neftoach und lief zu den Städten des Gebirges Efron hin. Die Grenze zog sich dann herum nach Baala*, das ist Kirjat-Jearim*.", footnotes: ["℘ 2Sam 6,2", "℘ V. 60; Ri 18,12"] },
      { number: 10, text: "Und von Baala wandte sich die Grenze nach Westen zum Gebirge Seïr und ging hinüber zum Nordabhang des Berges Jearim*, das ist Kesalon, und sie stieg hinunter nach Bet-Schemesch* und ging hinüber nach Timna*;", footnotes: ["w. zur Schulter des Berges Jearim von Norden", "℘ Kap. 19,38; 21,16; 1Sam 6,9; 2Kö 14,11; 2Chr 28,18", "℘ V. 57; Ri 14,1"] },
      { number: 11, text: "dann lief die Grenze weiter zum Nordabhang* von Ekron*. Und die Grenze zog sich herum nach Schikkaron und ging hinüber zum Berg Baala, und sie lief aus bei Jabneel*; und somit endete die Grenze am Meer*. —", footnotes: ["w. zur Schulter Ekrons nach Norden", "℘ V. 45; Ri 1,18; 1Sam 5,10; 7,14; 2Kö 1,2", "℘ 2Chr 26,6", "℘ 4Mo 34,6"] },
      { number: 12, text: "Und die Westgrenze war das große Meer und die Küste*. Das war die Grenze der Söhne Juda ringsum nach ihren Sippen.*", footnotes: ["w. Grenze", "℘ Kap. 18,5; Hes 48,7"] },
      { number: 13, text: "*Und dem Kaleb, dem Sohn des Jefunne, gab er ein Teil inmitten der Söhne Juda nach dem Befehl des HERRN an Josua: die Stadt des Arba*, des Vaters Enaks, das ist Hebron*.", footnotes: ["℘ V. 13-19: Ri 1,10-15", "o. Kirjat-Arba", "℘ Kap. 14,13-15; 20,7; 21,11; 2Sam 2,1"] },
      { number: 14, text: "Und Kaleb vertrieb von dort die drei Söhne Enaks*, Scheschai und Ahiman und Talmai, Kinder Enaks.", footnotes: ["℘ Kap. 11,21"] },
      { number: 15, text: "Und von dort zog er hinauf gegen die Bewohner von Debir; der Name von Debir war aber früher Kirjat-Sefer." },
      { number: 16, text: "Und Kaleb sagte: Wer Kirjat-Sefer schlägt und es einnimmt, dem gebe ich meine Tochter Achsa* zur Frau*.", footnotes: ["℘ 1Chr 2,49", "℘ 1Sam 17,25"] },
      { number: 17, text: "Da nahm es Otniël ein, der Sohn des Kenas*, der Bruder Kalebs; und er gab ihm seine Tochter Achsa zur Frau.", footnotes: ["℘ 4Mo 32,12; 1Chr 4,13; 27,15"] },
      { number: 18, text: "Und es geschah, als sie herbeikam, da trieb sie ihn an*, von ihrem Vater ein Feld zu fordern. Und sie sprang vom Esel herab*. Da sagte Kaleb zu ihr: Was hast du?", footnotes: ["einige Handschr. der LXX: da trieb er sie an", "℘ 1Mo 24,64; 1Sam 25,23"] },
      { number: 19, text: "Sie sagte: Gib mir einen Segen*! Denn ein dürres Südland hast du mir gegeben*. So gib mir auch Wasserquellen! Da gab er ihr die oberen Quellen und die unteren Quellen.", footnotes: ["d. i. ein Geschenk, das durch einen Segensspruch begleitet und übertragen wird", "o. in ein dürres Südland hast du mich gegeben"] },
      { number: 20, text: "Das war das Erbteil des Stammes der Söhne Juda nach ihren Sippen." },
      { number: 21, text: "*Und die Städte am Rand des Stammes der Söhne Juda, zur Grenze von Edom im Süden hin, waren: Kabzeel*, Eder, Jagur,", footnotes: ["℘ V. 21-62: Kap. 19,1-9; Neh 11,25-30; V. 26-31: 1Chr 4,28-30", "℘ 2Sam 23,20"] },
      { number: 22, text: "Kina, Dimona, Adada," },
      { number: 23, text: "Kedesch, Hazor, Jitnan," },
      { number: 24, text: "Sif, Telem*, Bealot,", footnotes: ["℘ 1Sam 15,4"] },
      { number: 25, text: "Hazor-Hadatta, Kerijot-Hezron, das ist Hazor," },
      { number: 26, text: "Amam, Schema, Molada," },
      { number: 27, text: "Hazar-Gadda, Heschmon, Bet-Pelet*,", footnotes: ["℘ 2Sam 23,26"] },
      { number: 28, text: "Hazar-Schual, Beerscheba*, Bisjotja*,", footnotes: ["℘ 1Mo 21,31", "LXX: und seine Tochterstädte"] },
      { number: 29, text: "Baala, Ijim, Ezem," },
      { number: 30, text: "Eltolad, Kesil, Horma*,", footnotes: ["℘ 4Mo 21,3"] },
      { number: 31, text: "Ziklag*, Madmanna*, Sansanna,", footnotes: ["℘ 1Sam 27,6", "℘ 1Chr 2,49"] },
      { number: 32, text: "Lebaot, Schilhim, Ajin* und Rimmon*. Alle Städte sind 29 an der Zahl und dazu noch ihre Dörfer*. —", footnotes: ["℘ Kap. 21,16", "℘ Sach 14,10", "o. Gehöfte"] },
      { number: 33, text: "In der Niederung*: Eschtaol, Zora*, Aschna,", footnotes: ["hebr. Schefelah; d. i. der Küstenstreifen zwischen Jafo und Gaza", "℘ Kap. 19,41; Ri 13,2"] },
      { number: 34, text: "Sanoach, En-Gannim, Tappuach*, Enam,", footnotes: ["℘ 1Chr 2,43"] },
      { number: 35, text: "Jarmut und Adullam*, Socho* und Aseka*,", footnotes: ["℘ 1Sam 22,1", "℘ V. 48; 1Sam 17,1", "℘ 2Chr 11,9"] },
      { number: 36, text: "Schaarajim*, Aditajim, Gedera und Gederotajim: vierzehn Städte und dazu noch ihre Dörfer*.", footnotes: ["℘ 1Sam 17,52", "o. Gehöfte"] },
      { number: 37, text: "Zenan, Hadascha, Migdal-Gad," },
      { number: 38, text: "Dilan, Mizpe, Jokteel," },
      { number: 39, text: "Lachisch*, Bozkat*, Eglon,", footnotes: ["℘ Kap. 10,31", "℘ 2Kö 22,1"] },
      { number: 40, text: "Kabbon, Lachmas, Kitlisch," },
      { number: 41, text: "Gederot*, Bet-Dagon, Naama* und Makkeda: sechzehn Städte und dazu noch ihre Dörfer*.", footnotes: ["℘ 1Chr 27,28; 2Chr 28,18", "℘ Hi 2,11", "o. Gehöfte"] },
      { number: 42, text: "Libna, Eter, Aschan*,", footnotes: ["℘ 1Sam 30,30"] },
      { number: 43, text: "Jiftach, Aschna, Nezib," },
      { number: 44, text: "Keïla*, Achsib und Marescha*: neun Städte und dazu noch ihre Dörfer*;", footnotes: ["℘ 1Sam 23,1", "℘ 1Chr 2,42; 4,21; Mi 1,14.15", "o. Gehöfte"] },
      { number: 45, text: "Ekron* und seine Tochterstädte und seine Dörfer*;", footnotes: ["℘ V. 11; Kap. 19,43", "o. Gehöfte"] },
      { number: 46, text: "von Ekron an und westwärts alle, die seitlich von Aschdod liegen, und dazu noch ihre Dörfer*;", footnotes: ["o. Gehöfte"] },
      { number: 47, text: "Aschdod*, seine Tochterstädte und seine Dörfer*; Gaza*, seine Tochterstädte und seine Dörfer*, bis zum Bach Ägyptens und dem großen Meer und der Küste.", footnotes: ["℘ 2Chr 26,6", "o. Gehöfte", "℘ Kap. 11,22", "o. Gehöfte"] },
      { number: 48, text: "Und im Gebirge: Schamir, Jattir*, Socho*,", footnotes: ["℘ Kap. 21,14", "℘ V. 35; 1Chr 4,18"] },
      { number: 49, text: "Danna, Kirjat-Sanna, das ist Debir," },
      { number: 50, text: "Anab, Eschtemo*, Anim,", footnotes: ["℘ Kap. 21,14"] },
      { number: 51, text: "Goschen, Holon* und Gilo*: elf Städte und dazu noch ihre Dörfer*.", footnotes: ["℘ Kap. 21,15", "℘ 2Sam 15,12", "o. Gehöfte"] },
      { number: 52, text: "Arab*, Duma, Eschan,", footnotes: ["℘ 2Sam 23,35"] },
      { number: 53, text: "Janum, Bet-Tappuach, Afeka*,", footnotes: ["℘ 1Sam 4,1"] },
      { number: 54, text: "Humta, Kirjat-Arba, das ist Hebron, und Zior: neun Städte und dazu noch ihre Dörfer*.", footnotes: ["o. Gehöfte"] },
      { number: 55, text: "Maon*, Karmel*, Sif*, Jutta*,", footnotes: ["℘ 1Chr 2,45", "℘ Kap. 19,26; 1Sam 15,12", "℘ 1Sam 23,14.24; 1Chr 2,42", "℘ Kap. 21,16"] },
      { number: 56, text: "Jesreel*, Jokdeam, Sanoach*,", footnotes: ["℘ Kap. 17,16; 19,18", "℘ 1Chr 4,18"] },
      { number: 57, text: "Kajin*, Gibea* und Timna*: zehn Städte und dazu noch ihre Dörfer*.", footnotes: ["o. Hakajin", "℘ 1Chr 2,49", "℘ V. 10; Kap. 19,43", "o. Gehöfte"] },
      { number: 58, text: "Halhul, Bet-Zur*, Gedor*,", footnotes: ["℘ 1Chr 2,45; 2Chr 11,7", "℘ 1Chr 4,18"] },
      { number: 59, text: "Maarat, Bet-Anot und Eltekon: sechs Städte und dazu noch ihre Dörfer*.", footnotes: ["o. Gehöfte"] },
      { number: 60, text: "Kirjat-Baal, das ist Kirjat-Jearim*, und Rabba: zwei Städte und dazu noch ihre Dörfer*. —", footnotes: ["℘ V. 9; 1Chr 2,50", "LXX zählt hier noch weiter auf: Tekoa, Efrata — das ist Bethlehem —, Peor, Etam, Kolon, Tatam, Sores, Kerem, Gallim, Bet-Ter, Manocho — das sind 11 Städte und ihre Dörfer"] },
      { number: 61, text: "In der Wüste: Bet-Araba, Middin, Sechacha," },
      { number: 62, text: "Nibschan und die Salzstadt und En-Gedi*: sechs Städte und dazu noch ihre Dörfer*.", footnotes: ["℘ 1Sam 24,1; 2Chr 20,2", "o. Gehöfte"] },
      { number: 63, text: "Aber die Jebusiter, die Bewohner von Jerusalem*, — die Söhne Juda konnten sie nicht vertreiben. Und die Jebusiter wohnen zusammen mit den Söhnen Juda in Jerusalem bis zum heutigen Tag*.", footnotes: ["℘ V. 8", "℘ Ri 1,8.21; 2Sam 5,6"] },
    ]},
    { number: 16, verses: [
      { number: 1, text: "Und das Los kam heraus für die Söhne Josef* vom Jordan bei Jericho an, dem Wasser von Jericho im Osten: die Wüste, die von Jericho aus zum Gebirge von Bethel hinaufsteigt*.", heading: "Erbteil des Stammes Ephraim", footnotes: ["℘ 1Mo 35,24", "℘ Kap. 18,12"] },
      { number: 2, text: "Und die Grenze ging aus von Bethel nach Lus* und ging hinüber zum Gebiet der Arkiter*, nach Atarot,", footnotes: ["℘ 1Mo 28,19; Ri 1,22.23", "℘ 2Sam 15,32"] },
      { number: 3, text: "und stieg westwärts hinunter zum Gebiet der Jafletiter bis an das Gebiet vom unteren Bet-Horon* und bis Geser*; und sie endete am Meer.", footnotes: ["℘ Kap. 18,13; 1Chr 7,24; 2Chr 8,5", "℘ 1Kö 9,15.17; 1Chr 20,4"] },
      { number: 4, text: "So erhielten die Söhne Josef, Manasse und Ephraim*, ihr Erbteil*.", footnotes: ["℘ Kap. 14,4; 1Mo 41,52; Hes 47,13", "℘ Kap. 18,5"] },
      { number: 5, text: "Es war aber dies die Grenze der Söhne Ephraim nach ihren Sippen: Die Grenze ihres Erbteils im Osten war Atarot-Addar* bis Ober-Bet-Horon.", footnotes: ["℘ Kap. 18,13"] },
      { number: 6, text: "Und die Grenze lief zum Meer hin, Michmetat* im Norden. Und die Grenze wandte sich nach Osten nach Taanat-Silo und ging daran vorbei ostwärts nach Janoach.", footnotes: ["℘ Kap. 17,7"] },
      { number: 7, text: "Dann stieg sie von Janoach hinab nach Atarot und Naara und stieß an Jericho und lief am Jordan aus." },
      { number: 8, text: "Von Tappuach* ging die Grenze westwärts zum Bach Kana*, und sie endete am Meer. Das ist das Erbteil des Stammes der Söhne Ephraim nach ihren Sippen.", footnotes: ["℘ Kap. 17,7", "℘ Kap. 17,9; 2Sam 2,9; 1Chr 7,28; Hes 48,5"] },
      { number: 9, text: "Und die ausgesonderten Städte gehörten den Söhnen Ephraim mitten im Erbteil der Söhne Manasse: alle Städte und ihre Dörfer*. —", footnotes: ["o. Gehöfte\n℘ Kap. 17,9; 2Sam 2,9; 1Chr 7,28; Hes 48,5"] },
      { number: 10, text: "Aber sie trieben die Kanaaniter nicht aus, die in Geser wohnten. Und die Kanaaniter blieben inmitten von Ephraim wohnen bis zum heutigen Tag, und sie wurden zu fronpflichtigen Knechten*.", footnotes: ["℘ Kap. 17,13; Ri 1,29; 1Kö 9,16.21"] },
    ]},
    { number: 17, verses: [
      { number: 1, text: "Und das Los fiel* für den Stamm Manasse — denn er war Josefs Erstgeborener* —, und zwar für Machir*, den Erstgeborenen Manasses, den Vater Gileads*. Denn der war ein Kriegsmann, und es wurden ihm Gilead* und Baschan zuteil*.", heading: "Erbteil des halben Stammes Manasse", footnotes: ["w. wurde, o. war", "℘ 1Mo 41,51", "℘ 1Mo 50,23", "℘ 4Mo 26,29", "℘ 4Mo 32,40; 2Sam 2,9", "℘ 5Mo 3,15; Hes 47,13"] },
      { number: 2, text: "Und es fiel* für die übrigen Söhne Manasse nach ihren Sippen: für die Söhne des Abiëser*, für die Söhne des Helek und für die Söhne des Asriël, für die Söhne des Sichem, für die Söhne des Hefer und für die Söhne des Schemida*; das waren die Söhne Manasses, des Sohnes Josefs, die männlichen Nachkommen nach ihren Sippen.", footnotes: ["w. wurde, o. war", "℘ 4Mo 26,30; Ri 6,11; 1Chr 7,18", "℘ 4Mo 26,30-32"] },
      { number: 3, text: "Und Zelofhad, der Sohn Hefers, des Sohnes Gileads, des Sohnes Machirs, des Sohnes Manasses, hatte keine Söhne, sondern nur Töchter. Und dies sind die Namen seiner Töchter: Machla, Noa, Hogla, Milka und Tirza*.", footnotes: ["℘ 4Mo 26,33"] },
      { number: 4, text: "Und sie traten hinzu vor den Priester Eleasar und vor Josua, den Sohn des Nun, und vor die Fürsten* und sagten: Der HERR hat Mose geboten, uns ein Erbteil unter unseren Brüdern zu geben. Da gab er ihnen nach dem Befehl des HERRN ein Erbteil unter den Brüdern ihres Vaters*.", footnotes: ["℘ Kap. 21,1", "℘ 4Mo 27,1-7; 36,10-12"] },
      { number: 5, text: "So fielen dem Manasse zehn Anteile* zu, außer dem Land Gilead und Baschan, das jenseits des Jordan liegt*.", footnotes: ["w. Messschnüre", "℘ Kap. 13,29-31; 22,7; Hes 48,4"] },
      { number: 6, text: "Denn die Töchter Manasses erhielten ein Erbteil unter seinen Söhnen. Das Land Gilead aber wurde den übrigen Söhnen Manasses zuteil*.", footnotes: ["℘ Kap. 13,29-31; 22,7; Hes 48,4"] },
      { number: 7, text: "Die Grenze Manasses war von Asser nach Michmetat*, das gegenüber von* Sichem liegt. Und die Grenze ging dann nach rechts zu den Bewohnern von En-Tappuach hin.", footnotes: ["℘ Kap. 16,6", "d. i. östlich von"] },
      { number: 8, text: "Dem Manasse gehörte das Land Tappuach; aber Tappuach selbst an der Grenze Manasses gehörte den Söhnen Ephraim." },
      { number: 9, text: "Und die Grenze stieg hinab zum Bach Kana*, und zwar auf der Südseite des Baches. Diese Städte gehörten Ephraim inmitten der Städte Manasses*. Und das Gebiet Manasses war nördlich vom Bach und endete am Meer.", footnotes: ["℘ Kap. 16,8", "℘ Kap. 16,9"] },
      { number: 10, text: "Nach Süden zu gehörte es Ephraim und nach Norden zu Manasse. Das Meer war seine Grenze. Und an Asser stießen sie* im Norden, an Issaschar dagegen im Osten.", footnotes: ["d. h. die Manassiten"] },
      { number: 11, text: "Und dem Manasse gehörte in Issaschar und in Asser: Bet-Schean* und seine Tochterstädte, Jibleam* und seine Tochterstädte, die Bewohner von Dor und seine Tochterstädte, die Bewohner von En-Dor* und seine Tochterstädte, die Bewohner von Taanach und seine Tochterstädte und die Bewohner von Megiddo* und seine Tochterstädte: das Dreihügelgebiet. —", footnotes: ["℘ 1Sam 31,10; 1Kö 4,12; 1Chr 7,29", "℘ Ri 1,27; 2Kö 9,27", "℘ 1Sam 28,7", "℘ Ri 5,19; 1Kö 4,12; 2Chr 35,22"] },
      { number: 12, text: "Aber die Söhne Manasse konnten diese Städte nicht in Besitz nehmen; so gelang es den Kanaanitern, in diesem Land wohnen zu bleiben." },
      { number: 13, text: "Und es geschah, als die Söhne Israel stärker wurden, machten sie die Kanaaniter zu Zwangsarbeitern; aber sie vertrieben sie keineswegs*.", footnotes: ["℘ Kap. 16,10"] },
      { number: 14, text: "Und die Söhne Josef redeten zu Josua: Warum hast du mir als Erbteil nur ein Los und einen Anteil* gegeben? Ich bin doch ein zahlreiches Volk, weil der HERR mich so reich gesegnet hat*!", footnotes: ["w. eine Messschnur; d. h. ein abgemessenes Landstück", "℘ 1Mo 48,20; 4Mo 26,54-56; 5Mo 33,17"] },
      { number: 15, text: "Da sagte Josua zu ihnen: Wenn du ein zahlreiches Volk bist, steige in den Wald hinauf und rode für dich dort im Land der Perisiter und der Refaïter*, weil dir das Gebirge Ephraim* zu eng ist!", footnotes: ["℘ 1Mo 15,20", "℘ Ri 17,1"] },
      { number: 16, text: "Die Söhne Josef aber sagten: Das Gebirge reicht für uns nicht aus, und bei allen Kanaanitern, die im Flachland* wohnen, sind eiserne Wagen*: bei denen in Bet-Schean und seinen Tochterstädten und bei denen im Tal Jesreel*.", footnotes: ["w. Land der Ebene", "℘ Ri 1,19", "℘ Kap. 15,56; 19,18; Ri 6,33; 1Sam 29,1; 1Kö 18,45"] },
      { number: 17, text: "Da sagte Josua zum Haus Josef, zu Ephraim und zu Manasse: Du bist ein zahlreiches Volk und hast eine große Kraft. Du sollst nicht nur ein Los haben," },
      { number: 18, text: "sondern ein Gebirge soll dir zuteil werden. Es ist ja ein Wald, den kannst du roden, und auch seine Ausläufer sollen* dir gehören. Denn du wirst die Kanaaniter vertreiben, auch wenn sie eiserne Wagen haben — auch wenn sie stark sind*.", footnotes: ["o. und das so gewonnene Gebiet soll", "LXX: denn du bist stärker als sie\n℘ 1Mo 49,24; 5Mo 33,17; Jes 41,14-16"] },
    ]},
    { number: 18, verses: [
      { number: 1, text: "Und die ganze Gemeinde der Söhne Israel versammelte sich in Silo*, und sie schlugen dort das Zelt der Begegnung auf*; und das Land war vor ihnen unterjocht*.", heading: "Das Heiligtum in Silo — Weitere Vorbereitungen zur Auslosung des Landes", footnotes: ["℘ Kap. 21,2; Ri 21,12.19", "℘ Kap. 19,51; 22,19; Ri 18,31; 1Sam 1,3; Ps 78,60; Jer 7,12", "℘ 4Mo 32,22; Apg 7,45"] },
      { number: 2, text: "Es blieben aber unter den Söhnen Israel sieben Stämme übrig, die ihr Erbteil noch nicht unter sich verteilt hatten." },
      { number: 3, text: "Da sagte Josua zu den Söhnen Israel: Wie lange noch seid ihr zu nachlässig, um hinzugehen, um das Land in Besitz zu nehmen, das der HERR, der Gott eurer Väter, euch gegeben hat*?", footnotes: ["℘ Kap. 1,6; 13,1; Ri 18,9; Hebr 4,8"] },
      { number: 4, text: "Nehmt euch drei Männer für je einen Stamm, die ich dann aussenden werde! Und sie sollen sich aufmachen, das Land durchwandern und es aufschreiben entsprechend ihrem Erbteil und dann zu mir kommen." },
      { number: 5, text: "Sie sollen es unter sich in sieben Teile aufteilen. Juda soll auf seinem Gebiet bleiben gegen Süden*, und das Haus Josef bleibt auf seinem Gebiet im Norden*.", footnotes: ["℘ Kap. 15,1-12", "℘ Kap. 16,1-4"] },
      { number: 6, text: "Ihr aber sollt das Land zu sieben Teilen aufschreiben und mir das Verzeichnis hierherbringen. Ich werde euch dann das Los werfen hier vor dem HERRN, unserem Gott*.", footnotes: ["℘ Kap. 14,2"] },
      { number: 7, text: "Denn die Leviten haben keinen Anteil* in eurer Mitte, sondern das Priestertum des HERRN ist ihr Erbteil*. Gad und Ruben und der halbe Stamm Manasse haben jenseits des Jordan, im Osten, ihr Erbteil empfangen, das Mose, der Knecht des HERRN, ihnen gegeben hat*.", footnotes: ["d. h. am Landbesitz", "℘ Kap. 13,14.16.33", "℘ Kap. 12,6"] },
      { number: 8, text: "Und die Männer machten sich auf und gingen hin. Und Josua befahl denen, die hingingen, um das Land aufzuschreiben: Geht hin, durchwandert das Land und schreibt es auf, und kommt wieder zu mir! Und hier werde ich euch das Los werfen vor dem HERRN, hier in Silo." },
      { number: 9, text: "Da gingen die Männer und durchzogen das Land und schrieben es nach Städten zu sieben Teilen in einem Buch auf. Dann kamen sie zurück zu Josua ins Lager nach Silo." },
      { number: 10, text: "Da warf ihnen Josua das Los in Silo vor dem HERRN*. Dort verteilte Josua das Land an die Söhne Israel entsprechend ihren Volksgruppen*.", footnotes: ["℘ Neh 11,1", "w. Abteilungen\n℘ Kap. 14,2.5; 23,4; 1Chr 24,5; Hes 48,29; Apg 13,19"] },
      { number: 11, text: "Und es kam herauf das Los des Stammes der Söhne Benjamin* nach ihren Sippen. Das Gebiet ihres Loses erstreckte sich zwischen* den Söhnen Juda und den Söhnen Josef.", heading: "Erbteil des Stammes Benjamin", footnotes: ["℘ 1Mo 35,24; Hes 48,23", "w. Und die Grenze ihres Loses ging aus zwischen"] },
      { number: 12, text: "Ihre Grenze auf der Nordseite fing am Jordan an. Und die Grenze stieg im Norden den Abhang von Jericho hinauf und stieg auf das Gebirge im Westen* und endete in der Wüste bei Bet-Awen.", footnotes: ["℘ Kap. 16,1"] },
      { number: 13, text: "Und von dort ging die Grenze hinüber nach Lus, zum Südabhang von Lus*, das ist Bethel*. Und die Grenze fiel ab nach Atarot-Addar, bei dem Berg, der südlich von dem unteren Bet-Horon* liegt. —", footnotes: ["w. zur Schulter nach Lus, nach Süden", "℘ V. 22; 1Mo 28,19; Neh 11,31", "℘ Kap. 16,2.3.5"] },
      { number: 14, text: "Dann zog sich die Grenze herum und wandte sich zur Westseite, südlich von dem Berg, der vor Bet-Horon nach Süden hin liegt, und endete in Kirjat-Baal, das ist Kirjat-Jearim, eine Stadt der Söhne Juda; das war die Westseite." },
      { number: 15, text: "*Und die Südseite begann am Ende von Kirjat-Jearim. Und die Grenze lief nach Westen hin, und sie lief zur Quelle Me-Neftoach*.", footnotes: ["℘ V. 15-20: Kap. 15,5-9", "o. zur Quelle des Wassers Neftoach"] },
      { number: 16, text: "Und die Grenze lief hinab zum Fuß* des Berges, der vor dem Tal Ben-Hinnom in der Talebene Refaïm nach Norden zu liegt. Und sie lief das Tal Hinnom hinab zum Südabhang der Jebusiter*, und sie fiel ab nach En-Rogel* hin,", footnotes: ["w. zum Äußersten", "w. zur Schulter des Jebusiters nach Süden", "d. h. Bleicherquelle"] },
      { number: 17, text: "und sie zog sich herum nach Norden zu, lief nach En-Schemesch* und lief nach Gelilot* hin, das dem Anstieg Adummim gegenüberliegt. Und sie lief hinab zum Stein Bohans, des Sohnes Rubens, hin", footnotes: ["d. h. Sonnenquelle", "o. zu den Bezirken hin"] },
      { number: 18, text: "und ging hinüber zum Berghang*, der der Steppe* im Norden gegenüberliegt, und lief hinab zur Steppe*.", footnotes: ["w. zur Schulter, die", "hebr. Araba; d. i. die Steppe, die sich beiderseits des Toten Meeres erstreckt", "hebr. Araba; d. i. die Steppe, die sich beiderseits des Toten Meeres erstreckt"] },
      { number: 19, text: "Und die Grenze ging hinüber zum Nordabhang von Bet-Hogla*, und die Grenze endete bei der Nordzunge des Salzmeeres, am Südende des Jordan. Das war die Südgrenze. —", footnotes: ["w. zur Schulter . . . nach Norden"] },
      { number: 20, text: "Und der Jordan begrenzte es an der Ostseite. Das war das Erbteil der Söhne Benjamin nach seinen Grenzen ringsum, nach ihren Sippen*.", footnotes: ["℘ 2Sam 2,9"] },
      { number: 21, text: "Die Städte des Stammes der Söhne Benjamin nach ihren Sippen waren: Jericho*, Bet-Hogla und Emek-Keziz,", footnotes: ["℘ Kap. 6,1; Ri 1,16"] },
      { number: 22, text: "Bet-Araba*, Zemarajim* und Bethel*,", footnotes: ["℘ 2Sam 23,31", "℘ 2Chr 13,4", "℘ V. 13"] },
      { number: 23, text: "Awim, Para* und Ofra*,", footnotes: ["o. Haawwim, Happara", "℘ 1Sam 13,17; Mi 1,10"] },
      { number: 24, text: "Kefar-Ammoni, Ofni und Geba*: zwölf Städte und ihre Dörfer*;", footnotes: ["℘ Kap. 21,17; 1Sam 13,3; 2Sam 5,25; 1Kö 15,22; 2Kö 23,8; Esr 2,26", "o. Gehöfte"] },
      { number: 25, text: "Gibeon*, Rama* und Beerot*,", footnotes: ["℘ Kap. 9,3; 1Chr 8,29", "℘ Kap. 19,29; Ri 19,13; 1Sam 1,19; 1Kö 15,17; Neh 11,33; Jes 10,29; Jer 31,15", "℘ Kap. 9,17; 2Sam 4,2"] },
      { number: 26, text: "Mizpe*, Kefira* und Moza,", footnotes: ["℘ Ri 11,34; 1Sam 7,5; 1Kö 15,22; 2Kö 25,23; Jer 40,6", "℘ Kap. 9,17; 2Sam 4,2"] },
      { number: 27, text: "Rekem, Jirpeel und Tarala," },
      { number: 28, text: "Zela*, Elef, und die Jebusiter*, das ist Jerusalem*, Gibea*, Kirjat: vierzehn Städte und ihre Dörfer*. Das war das Erbteil der Kinder Benjamin nach ihren Sippen.", footnotes: ["℘ 2Sam 21,14", "LXX, syr. und lat. Üs.: Jebus", "℘ Kap. 15,8.63; Ri 1,21; 19,10; 1Chr 8,28; Jer 6,1", "℘ Ri 19,12; 1Sam 10,26", "o. Gehöfte"] },
    ]},
    { number: 19, verses: [
      { number: 1, text: "*Und das zweite Los kam heraus für Simeon*, für den Stamm der Söhne Simeon nach ihren Sippen. Und ihr Erbteil war mitten in dem Erbteil der Söhne Juda*.", heading: "Erbteil des Stammes Simeon", footnotes: ["℘ V. 1-9: Kap. 15,21-62; V. 2-8: 1Chr 4,28-33", "℘ 1Mo 35,23; Hes 48,24", "℘ 1Mo 49,7"] },
      { number: 2, text: "Und es wurde ihnen zum Erbteil: Beerscheba, Scheba* und Molada,", footnotes: ["nach Kap. 15,26 und mit LXX: Schema"] },
      { number: 3, text: "Hazar-Schual, Baala und Ezem," },
      { number: 4, text: "Eltolad, Betul und Horma," },
      { number: 5, text: "Ziklag*, Bet-Markabot und Hazar-Susa,", footnotes: ["℘ Kap. 15,31"] },
      { number: 6, text: "Bet-Lebaot und Scharuhen: dreizehn Städte und ihre Dörfer*;", footnotes: ["o. Gehöfte"] },
      { number: 7, text: "Ajin, Rimmon, Eter und Aschan: vier Städte und ihre Dörfer*;", footnotes: ["o. Gehöfte"] },
      { number: 8, text: "und alle Dörfer*, die rings um diese Städte liegen, bis Baalat-Beer, das ist Süd-Ramat*. Das war das Erbteil des Stammes der Söhne Simeon nach ihren Sippen.", footnotes: ["o. Gehöfte", "℘ 1Sam 30,27"] },
      { number: 9, text: "Aus dem Anteil* der Söhne Juda war das Erbteil der Söhne Simeon genommen*; denn das Teil der Söhne Juda war zu groß für sie*. Und so erhielten die Söhne Simeon ihr Erbteil mitten in deren Erbteil.", footnotes: ["w. der Messschnur", "℘ 1Mo 49,7", "℘ 4Mo 26,54"] },
      { number: 10, text: "Und das dritte Los kam heraus für die Söhne Sebulon* nach ihren Sippen. Und die Grenze ihres Erbteils war bis Sarid.", heading: "Erbteil des Stammes Sebulon", footnotes: ["℘ 1Mo 35,23; Hes 48,26"] },
      { number: 11, text: "Und ihre Grenze stieg westwärts hinauf, und zwar nach Marala, und stieß an Dabbeschet und stieß an den Bach, der vor Jokneam fließt." },
      { number: 12, text: "Und sie wandte sich von Sarid ostwärts gegen Sonnenaufgang zum Gebiet von Kislot-Tabor und verlief nach Daberat* hin und stieg hinauf nach Jafia.", footnotes: ["℘ Kap. 21,28"] },
      { number: 13, text: "Von dort ging sie nach Osten hinüber gegen Sonnenaufgang nach Gat-Hefer*, nach Et-Kazin und lief nach Rimmon, das sich nach Nea hin erstreckt.", footnotes: ["℘ 2Kö 14,25"] },
      { number: 14, text: "Und die Grenze zog sich darum herum nördlich nach Hannaton und endete im Tal Jiftach-El; . . ." },
      { number: 15, text: "und Kattat*, Nahalal*, Schimron, Jidala und Bethlehem*: zwölf Städte und ihre Dörfer.", footnotes: ["℘ Kap. 21,34", "℘ Kap. 21,35; Ri 1,30", "℘ Ri 12,8"] },
      { number: 16, text: "Das war das Erbteil der Söhne Sebulon nach ihren Sippen, diese Städte und ihre Dörfer*.", footnotes: ["o. Gehöfte"] },
      { number: 17, text: "Für Issaschar kam das vierte Los heraus, für die Söhne Issaschar* nach ihren Sippen.", heading: "Erbteil des Stammes Issaschar", footnotes: ["℘ 1Mo 35,23; Hes 48,25"] },
      { number: 18, text: "Und ihr Gebiet war: nach Jesreel* hin Kesullot und Schunem*,", footnotes: ["℘ Kap. 17,16; 2Sam 2,9; 2Kö 8,29; Hos 1,4.5", "℘ 1Sam 28,4; 1Kö 1,3; 2Kö 4,8"] },
      { number: 19, text: "Hafarajim, Schion und Anaharat," },
      { number: 20, text: "Rabbit, Kischjon* und Ebez,", footnotes: ["℘ Kap. 21,28"] },
      { number: 21, text: "Remet*, En-Gannim*, En-Hadda und Bet-Pazzez.", footnotes: ["℘ 1Chr 6,58", "℘ Kap. 21,29"] },
      { number: 22, text: "Und die Grenze stieß an Tabor*, Schahazajim, Bet-Schemesch, und ihre Grenze endete am Jordan: sechzehn Städte und ihre Dörfer*.", footnotes: ["℘ Ri 4,6; 1Chr 6,62", "o. Gehöfte"] },
      { number: 23, text: "Das war das Erbteil des Stammes der Söhne Issaschar nach ihren Sippen, die Städte und ihre Dörfer*.", footnotes: ["o. Gehöfte"] },
      { number: 24, text: "Und das fünfte Los kam heraus für den Stamm der Söhne Asser* nach ihren Sippen.", heading: "Erbteil des Stammes Asser", footnotes: ["℘ 1Mo 35,26"] },
      { number: 25, text: "Ihre Grenze war: Helkat*, Hali, Beten und Achschaf,", footnotes: ["℘ Kap. 21,31"] },
      { number: 26, text: "Alammelech, Amad und Mischal*. Sie stieß an den Karmel* im Westen und an den Schihor-Libnat*,", footnotes: ["℘ Kap. 21,30", "℘ Kap. 15,55; 1Kö 18,19; 2Kö 2,25; Jes 35,2", "d. i. ein Fluss"] },
      { number: 27, text: "und sie kehrte um gegen Sonnenaufgang nach Bet-Dagon und stieß an Sebulon und an das Tal Jiftach-El im Norden, dann an Bet-Emek und Negiël, und sie lief links weiter nach Kabul," },
      { number: 28, text: "Ebron und Rehob*, Hammon und Kana bis nach Sidon, der großen Stadt*.", footnotes: ["℘ Kap. 21,31; Ri 18,28", "℘ Ri 1,31; Hes 28,21"] },
      { number: 29, text: "Und die Grenze kehrte um nach Rama* und bis zur befestigten Stadt Tyrus*. Und die Grenze kehrte um nach Hosa, und sie endete am Meer von Hebel nach Achsib*; . . .", footnotes: ["℘ Kap. 18,25", "℘ 2Sam 5,11; 24,7; 1Kö 5,15; Lk 10,13", "Andere üs. mit Textänderung: am Meer. Machaleb und Achsib\n℘ Ri 1,31; Hes 28,21"] },
      { number: 30, text: "und Umma, Afek* und Rehob: 22 Städte und ihre Dörfer*.", footnotes: ["℘ Ri 1,31; Hes 28,21", "o. Gehöfte"] },
      { number: 31, text: "Das war das Erbteil des Stammes der Söhne Asser* nach ihren Sippen, diese Städte und ihre Dörfer*.", footnotes: ["℘ Hes 48,2", "o. Gehöfte"] },
      { number: 32, text: "Für die Söhne Naftali kam das sechste Los heraus, für die Söhne Naftali* nach ihren Sippen.", heading: "Erbteil des Stammes Naftali", footnotes: ["℘ 1Mo 35,25"] },
      { number: 33, text: "Und ihre Grenze war von Helef, von der Terebinthe bei Zaanannim*, und Adami-Nekeb und Jabneel bis Lakkum, und sie endete am Jordan.", footnotes: ["℘ Ri 4,11"] },
      { number: 34, text: "Und die Grenze wandte sich nach Westen in Richtung Asnot-Tabor und lief von dort nach Hukkok. Sie stieß im Süden an Sebulon, während sie im Westen an Asser stieß und an Juda* am Jordan gegen Sonnenaufgang.", footnotes: ["in LXX fehlt: an Juda"] },
      { number: 35, text: "Befestigte Städte waren: Ziddim, Zer und Hammat*, Rakkat und Kinneret,", footnotes: ["℘ Kap. 20,7; 21,32; Ri 4,6; 2Kö 15,29"] },
      { number: 36, text: "Adama, Rama und Hazor*,", footnotes: ["℘ Kap. 11,1"] },
      { number: 37, text: "Kedesch*, Edreï und En-Hazor,", footnotes: ["℘ Kap. 20,7; 21,32; Ri 4,6; 2Kö 15,29"] },
      { number: 38, text: "Jiron und Migdal-El, Horem, Bet-Anat und Bet-Schemesch*: neunzehn Städte und ihre Dörfer*.", footnotes: ["℘ Kap. 15,10; Ri 1,33", "o. Gehöfte"] },
      { number: 39, text: "Das war das Erbteil des Stammes der Söhne Naftali nach ihren Sippen, die Städte und ihre Dörfer*.", footnotes: ["o. Gehöfte\n℘ 1Kö 15,20; Hes 48,3"] },
      { number: 40, text: "Für den Stamm der Söhne Dan* nach ihren Sippen kam das siebte Los heraus.", heading: "Erbteil des Stammes Dan", footnotes: ["℘ 1Mo 35,25"] },
      { number: 41, text: "Und das Gebiet ihres Erbteils war: Zora, Eschtaol* und Ir-Schemesch,", footnotes: ["℘ Kap. 15,33; Ri 13,25"] },
      { number: 42, text: "Schaalbim* und Ajalon* und Jitla,", footnotes: ["℘ Ri 1,35; 2Sam 23,32; 1Kö 4,9", "℘ Kap. 10,12"] },
      { number: 43, text: "Elon*, Timna* und Ekron*,", footnotes: ["℘ Ri 1,35; 2Sam 23,32; 1Kö 4,9", "℘ Kap. 15,57", "℘ Kap. 15,45"] },
      { number: 44, text: "Elteke, Gibbeton* und Baalat*,", footnotes: ["℘ Kap. 21,23; 1Kö 15,27", "℘ 1Kö 9,18"] },
      { number: 45, text: "Jehud, Bene-Berak und Gat-Rimmon*,", footnotes: ["℘ Kap. 21,24; 2Sam 6,10"] },
      { number: 46, text: "Me-Jarkon und Rakkon mit dem Gebiet gegenüber Jafo*.", footnotes: ["℘ 2Chr 2,15; Apg 9,36"] },
      { number: 47, text: "Und das Gebiet der Söhne Dan ging ihnen verloren*. Und die Söhne Dan zogen hinauf* und kämpften gegen Leschem*; und sie nahmen es ein und schlugen es mit der Schärfe des Schwertes, nahmen es in Besitz und wohnten darin. Und sie nannten Leschem* Dan* nach dem Namen ihres Vaters Dan.", footnotes: ["o. Und die Grenze der Söhne Dan ging von hier aus weiter", "℘ Ri 1,34", "Leschem = Lajisch; vgl. Ri 18,29\n℘ Ri 18,29", "Leschem = Lajisch; vgl. Ri 18,29", "℘ 5Mo 33,22; 2Sam 24,6"] },
      { number: 48, text: "Das war das Erbteil des Stammes der Söhne Dan* nach ihren Sippen, diese Städte und ihre Dörfer*.", footnotes: ["℘ Hes 48,1", "o. Gehöfte"] },
      { number: 49, text: "Als sie die Verteilung des Landes nach seinen einzelnen Gebieten vollendet hatten, gaben die Söhne Israel Josua, dem Sohn des Nun, ein Erbteil in ihrer Mitte*.", heading: "Erbteil des Josua", footnotes: ["℘ Hes 45,7.8"] },
      { number: 50, text: "Nach dem Befehl des HERRN gaben sie ihm die Stadt, die er forderte, Timnat-Serach im Gebirge Ephraim*. Und er baute die Stadt und wohnte darin.", footnotes: ["℘ Kap. 24,30; Ri 2,9; 1Kö 4,8"] },
      { number: 51, text: "Das sind die Erbteile, die der Priester Eleasar und Josua, der Sohn des Nun, und die Familienoberhäupter* der Stämme der Söhne Israel durch das Los austeilten in Silo vor dem HERRN, an dem Eingang des Zeltes der Begegnung*. Und so vollendeten sie die Verteilung des Landes.", footnotes: ["w. Häupter der Väter", "℘ Kap. 14,1.2; 18,1; 4Mo 34,18.29"] },
    ]},
    { number: 20, verses: [
      { number: 1, text: "*Und der HERR redete zu Josua:", heading: "Verordnung über Zufluchtsstädte", footnotes: ["℘ 4Mo 35,9-29; 5Mo 19,1-13"] },
      { number: 2, text: "Rede zu den Söhnen Israel: Bestimmt für euch die Zufluchtsstädte, von denen ich durch Mose zu euch geredet habe*,", footnotes: ["℘ 2Mo 21,13; 4Mo 35,6"] },
      { number: 3, text: "damit dorthin ein Totschläger fliehen kann, der jemanden aus Versehen, unabsichtlich, erschlagen hat*! Sie sollen euch als Zuflucht vor dem Bluträcher dienen.", footnotes: ["w. der eine Seele erschlug aus Versehen, ohne Erkenntnis"] },
      { number: 4, text: "Und er soll in eine von diesen Städten fliehen und am Eingang des Stadttores stehen und vor den Ohren der Ältesten jener Stadt seine Sache vorbringen. Und sie sollen ihn zu sich in die Stadt aufnehmen und ihm einen Ort geben, damit er bei ihnen wohnt." },
      { number: 5, text: "Und wenn der Bluträcher ihm nachjagt, dann sollen sie den Totschläger nicht in seine Hand ausliefern; denn er hat seinen Nächsten unabsichtlich* erschlagen und hat ihn vorher* nicht gehasst.", footnotes: ["w. ohne Erkenntnis", "w. seit gestern und vorgestern"] },
      { number: 6, text: "Und er soll in jener Stadt wohnen, bis er vor der Gemeinde vor Gericht gestanden hat, bis zum Tod des Hohenpriesters, der in jenen Tagen sein wird. Dann mag der Totschläger zurückkehren und in seine Stadt und in sein Haus gehen, in die Stadt, aus der er geflohen ist. —" },
      { number: 7, text: "Und sie heiligten Kedesch* in Galiläa auf dem Gebirge Naftali, und Sichem* auf dem Gebirge Ephraim, und Kirjat-Arba, das ist Hebron*, auf dem Gebirge Juda.", footnotes: ["℘ Kap. 19,36", "℘ Kap. 21,21; 24,1; Ri 9,1; 1Kö 12,1.25", "℘ Kap. 15,13"] },
      { number: 8, text: "Und jenseits des Jordan, östlich von Jericho, bestimmten sie Bezer* in der Wüste, in der Ebene, aus dem Stamm Ruben, und Ramot* in Gilead, aus dem Stamm Gad, und Golan* in Baschan, aus dem Stamm Manasse.", footnotes: ["℘ Kap. 21,36", "℘ Kap. 21,38; 5Mo 4,43; 2Kö 8,28", "℘ Kap. 21,27; 5Mo 4,43"] },
      { number: 9, text: "Das waren die bestimmten Städte* für alle Söhne Israel und für den Fremden, der in ihrer Mitte weilte, dass dorthin jeder fliehen konnte, der jemanden aus Versehen erschlagen hatte, damit er nicht durch die Hand des Bluträchers starb, bevor er vor der Gemeinde gestanden hatte.", footnotes: ["w. die Städte der Bestimmung"] },
    ]},
    { number: 21, verses: [
      { number: 1, text: "*Da traten die Familienoberhäupter* der Leviten zum Priester Eleasar und zu Josua, dem Sohn des Nun, und zu den Familienoberhäuptern* der Stämme der Söhne Israel*", heading: "Städte für die Leviten", footnotes: ["℘ V. 1-8: 4Mo 35,1-8", "w. Häupter der Väter", "w. Häupter der Väter", "℘ Kap. 14,1; 17,4"] },
      { number: 2, text: "und sagten zu ihnen in Silo*, im Land Kanaan: Der HERR hat durch Mose geboten, uns Städte zum Wohnen zu geben sowie deren Weideplätze für unser Vieh.", footnotes: ["℘ Kap. 18,1"] },
      { number: 3, text: "Da gaben die Söhne Israel den Leviten von ihrem Erbteil nach dem Befehl des HERRN diese Städte und ihre Weideplätze*:", footnotes: ["℘ V. 41; 1Mo 49,7"] },
      { number: 4, text: "Und das Los kam heraus für die Sippen der Kehatiter*. Und die Söhne des Priesters Aaron von den Leviten* erhielten vom Stamm Juda und vom Stamm der Simeoniter und vom Stamm Benjamin durch das Los dreizehn Städte*;", footnotes: ["℘ 2Mo 6,16.18", "℘ 2Mo 6,20.23.25", "℘ V. 9-19"] },
      { number: 5, text: "und die übrigen Söhne Kehats* von den Sippen des Stammes Ephraim und vom Stamm Dan und vom halben Stamm Manasse durch das Los zehn Städte*.", footnotes: ["℘ 4Mo 3,27", "℘ V. 20-26; 1Chr 6,51-55"] },
      { number: 6, text: "Und die Söhne des Gerschon* erhielten von den Sippen des Stammes Issaschar und vom Stamm Asser und vom Stamm Naftali und vom halben Stamm Manasse in Baschan durch das Los dreizehn Städte*;", footnotes: ["℘ 2Mo 6,17", "℘ V. 27-33; 1Chr 6,56-61"] },
      { number: 7, text: "die Söhne des Merari* nach ihren Sippen vom Stamm Ruben und vom Stamm Gad und vom Stamm Sebulon zwölf Städte*.", footnotes: ["℘ 2Mo 6,19", "℘ V. 34-40; 1Chr 6,62-66"] },
      { number: 8, text: "So gaben die Söhne Israel den Leviten diese Städte und ihre Weideplätze durch das Los*, wie der HERR durch Mose geboten hatte.", footnotes: ["℘ 1Mo 49,7"] },
      { number: 9, text: "*Und sie gaben vom Stamm der Söhne Juda und vom Stamm der Söhne Simeon folgende Städte, die man mit Namen nannte.", footnotes: ["℘ V. 9-19: 1Chr 6,39-45"] },
      { number: 10, text: "Und sie wurden den Söhnen Aarons von den Sippen der Kehatiter aus den Söhnen Levi, zuteil, denn für sie war das erste Los." },
      { number: 11, text: "Und sie gaben ihnen die Stadt des Arba*, des Vaters des Enak, das ist Hebron*, im Gebirge Juda, und ihre Weideplätze rings um sie her.", footnotes: ["o. Kirjat-Arba", "℘ Kap. 15,13"] },
      { number: 12, text: "Aber das Feld der Stadt und ihre Dörfer* gaben sie Kaleb, dem Sohn des Jefunne, als sein Eigentum*.", footnotes: ["o. Gehöfte", "℘ Kap. 14,13"] },
      { number: 13, text: "Den Söhnen des Priesters Aaron gaben sie die Zufluchtsstadt für den Totschläger: Hebron und seine Weideplätze, sowie Libna* und seine Weideplätze,", footnotes: ["℘ Kap. 10,29"] },
      { number: 14, text: "Jattir* und seine Weideplätze, Eschtemoa* und seine Weideplätze,", footnotes: ["℘ Kap. 15,48", "℘ Kap. 15,50"] },
      { number: 15, text: "Holon* und seine Weideplätze, Debir* und seine Weideplätze,", footnotes: ["℘ Kap. 15,51", "℘ Kap. 10,38"] },
      { number: 16, text: "Ajin* und seine Weideplätze, Jutta* und seine Weideplätze, Bet-Schemesch* und seine Weideplätze: neun Städte von diesen beiden Stämmen.", footnotes: ["℘ Kap. 15,32; 1Chr 4,32", "℘ Kap. 15,55", "℘ Kap. 15,10"] },
      { number: 17, text: "Und vom Stamm Benjamin: Gibeon* und seine Weideplätze, Geba* und seine Weideplätze,", footnotes: ["℘ Kap. 9,3", "℘ Kap. 18,24; 1Chr 8,6; Sach 14,10"] },
      { number: 18, text: "Anatot* und seine Weideplätze, Almon und seine Weideplätze: vier Städte.", footnotes: ["℘ 2Sam 23,27; 1Kö 2,26; Neh 11,32; Jer 1,1"] },
      { number: 19, text: "Alle Städte der Söhne Aarons, der Priester: dreizehn Städte und ihre Weideplätze." },
      { number: 20, text: "*Und was die Sippen der Söhne des Kehat, der Leviten, und zwar die Übrigen von den Söhnen des Kehat, betrifft, so waren die Städte ihres Loses vom Stamm Ephraim.", footnotes: ["℘ V. 20-40: 1Chr 6,51-66"] },
      { number: 21, text: "Und sie gaben ihnen die Zufluchtsstadt für den Totschläger: Sichem* und seine Weideplätze auf dem Gebirge Ephraim*, Geser* und seine Weideplätze,", footnotes: ["℘ Kap. 20,7", "℘ Ri 17,1", "℘ Kap. 10,33"] },
      { number: 22, text: "Kibzajim und seine Weideplätze, Bet-Horon und seine Weideplätze: vier Städte." },
      { number: 23, text: "Und vom Stamm Dan: Elteke und seine Weideplätze, Gibbeton* und seine Weideplätze,", footnotes: ["℘ Kap. 19,44"] },
      { number: 24, text: "Ajalon* und seine Weideplätze, Gat-Rimmon* und seine Weideplätze: vier Städte.", footnotes: ["℘ Kap. 10,12", "℘ Kap. 19,45"] },
      { number: 25, text: "Und von der Hälfte des Stammes Manasse: Taanach* und seine Weideplätze, Gat-Rimmon und seine Weideplätze: zwei Städte.", footnotes: ["℘ Kap. 12,21"] },
      { number: 26, text: "Alle Städte waren zehn* und ihre Weideplätze für die Sippen der übrigen Söhne des Kehat.", footnotes: ["℘ V. 5"] },
      { number: 27, text: "Und den Söhnen Gerschon aus den Sippen der Leviten gaben sie vom halben Stamm Manasse die Zufluchtsstadt für den Totschläger: Golan* in Baschan und seine Weideplätze sowie Beeschtera* und seine Weideplätze: zwei Städte.", footnotes: ["℘ Kap. 20,8; 5Mo 4,43", "Die syr. Üs. liest: Aschtarot"] },
      { number: 28, text: "Und vom Stamm Issaschar: Kischjon* und seine Weideplätze, Daberat* und seine Weideplätze,", footnotes: ["℘ Kap. 19,20", "℘ Kap. 19,12"] },
      { number: 29, text: "Jarmut und seine Weideplätze, En-Gannim* und seine Weideplätze: vier Städte.", footnotes: ["℘ Kap. 19,21"] },
      { number: 30, text: "Und vom Stamm Asser: Mischal* und seine Weideplätze, Abdon und seine Weideplätze,", footnotes: ["℘ Kap. 19,26"] },
      { number: 31, text: "Helkat* und seine Weideplätze und Rehob* und seine Weideplätze: vier Städte.", footnotes: ["℘ Kap. 19,25", "℘ Kap. 19,28"] },
      { number: 32, text: "Und vom Stamm Naftali die Zufluchtsstadt für den Totschläger: Kedesch* in Galiläa und seine Weideplätze und Hammot-Dor* und seine Weideplätze und Kartan und seine Weideplätze: drei Städte.", footnotes: ["℘ Kap. 19,37; Ri 4,6", "℘ Kap. 19,35"] },
      { number: 33, text: "Alle Städte der Gerschoniter nach ihren Sippen: dreizehn Städte* und ihre Weideplätze.", footnotes: ["℘ V. 6"] },
      { number: 34, text: "Und den Sippen der Söhne des Merari, den übrigen Leviten, gaben sie vom Stamm Sebulon: Jokneam* und seine Weideplätze, Karta* und seine Weideplätze,", footnotes: ["℘ Kap. 12,22", "℘ Kap. 19,15"] },
      { number: 35, text: "Dimna und seine Weideplätze, Nahalal* und seine Weideplätze: vier Städte.", footnotes: ["℘ Kap. 19,15"] },
      { number: 36, text: "Und vom Stamm Ruben: Bezer* und seine Weideplätze und Jahaz* und seine Weideplätze,", footnotes: ["℘ Kap. 20,8", "℘ Kap. 13,18"] },
      { number: 37, text: "Kedemot und seine Weideplätze, Mefaat* und seine Weideplätze: vier Städte.", footnotes: ["℘ Kap. 13,18"] },
      { number: 38, text: "Und vom Stamm Gad die Zufluchtsstadt für den Totschläger: Ramot* in Gilead und seine Weideplätze und Mahanajim* und seine Weideplätze,", footnotes: ["℘ Kap. 20,8; 1Kö 4,13", "℘ Kap. 13,26.30; 1Kö 4,14"] },
      { number: 39, text: "Heschbon* und seine Weideplätze, Jaser* und seine Weideplätze; alle Städte waren vier.", footnotes: ["℘ 4Mo 32,3; 1Chr 26,31", "℘ 4Mo 32,3; 1Chr 26,31"] },
      { number: 40, text: "Alle diese Städte gehörten den Söhnen Meraris nach ihren Sippen, den Übrigen von den Sippen der Leviten, so dass ihr Los zwölf Städte* umfasste.", footnotes: ["℘ V. 7"] },
      { number: 41, text: "Alle Städte der Leviten inmitten des Eigentums der Söhne Israel: 48 Städte und ihre Weideplätze*.", footnotes: ["℘ V. 3; 4Mo 35,7"] },
      { number: 42, text: "Diese Städte hatten, Stadt für Stadt, ihre Weideplätze rings um sich her: so war es bei allen diesen Städten." },
      { number: 43, text: "So gab der HERR Israel das ganze Land, das er ihren Vätern zu geben geschworen hatte*. Und sie nahmen es in Besitz und wohnten darin*.", heading: "Israel lebt in Gottes Ruhe", footnotes: ["℘ Kap. 1,6; Ps 105,8-11", "℘ 4Mo 34,2; 5Mo 11,31; 12,29; Ri 11,24; 1Sam 12,8; 2Chr 20,8; Neh 9,8.22-25; Ps 78,55; Jer 32,23"] },
      { number: 44, text: "Und der HERR verschaffte ihnen Ruhe ringsumher*, ganz wie er es ihren Vätern geschworen hatte. Und keiner von allen ihren Feinden hielt vor ihnen stand; alle ihre Feinde gab der HERR in ihre Hand*.", footnotes: ["℘ Kap. 11,23; 22,4; 23,1; Hebr 4,8", "℘ Kap. 1,5; 2,24; 11,8.14; 5Mo 2,36"] },
      { number: 45, text: "Es fiel kein Wort dahin* von all den guten Worten, die der HERR zum Haus Israel geredet hatte. Alles traf ein*.", footnotes: ["d. h. nichts blieb unerfüllt\n℘ 1Sam 3,19", "℘ Kap. 23,14; 4Mo 23,19; 1Kö 8,15.20.24.56; Neh 9,8; Jes 48,3"] },
    ]},
    { number: 22, verses: [
      { number: 1, text: "Damals rief Josua die Rubeniter und die Gaditer und den halben Stamm Manasse* zusammen,", footnotes: ["℘ Kap. 1,12"] },
      { number: 2, text: "und er sprach zu ihnen: Ihr habt alles gehalten, was Mose, der Knecht des HERRN, euch geboten hat*, und habt meiner Stimme gehorcht in allem, was ich euch befohlen habe*.", footnotes: ["℘ 4Mo 32,20-29; 5Mo 3,18-20", "℘ Kap. 1,13-15; Phil 2,12"] },
      { number: 3, text: "Ihr habt eure Brüder nicht verlassen diese lange Zeit bis zum heutigen Tag und habt* das Gebot des HERRN, eures Gottes, treu gehalten*.", footnotes: ["LXX: diese lange Zeit; bis zum heutigen Tag habt ihr", "w. und habt die Befolgung des Gebotes des HERRN, eures Gottes, gehalten"] },
      { number: 4, text: "Nun aber hat der HERR, euer Gott, euren Brüdern Ruhe verschafft, wie er zu ihnen geredet hatte*. Nun denn, kehrt um und geht wieder zu euren Zelten, in das Land eures Eigentums, das Mose, der Knecht des HERRN, euch jenseits des Jordan gegeben hat*!", footnotes: ["℘ Kap. 21,44; 4Mo 32,18; 1Chr 22,18", "℘ Kap. 12,6"] },
      { number: 5, text: "Nur achtet genau darauf, das Gebot und das Gesetz zu tun, das Mose, der Knecht des HERRN, euch befohlen hat; den HERRN, euren Gott, zu lieben und auf allen seinen Wegen zu wandeln und seine Gebote zu halten* und ihm anzuhängen* und ihm zu dienen mit eurem ganzen Herzen und mit eurer ganzen Seele*!", footnotes: ["℘ 2Mo 23,13", "℘ Apg 11,23", "℘ Kap. 23,8.11; 5Mo 6,5.6"] },
      { number: 6, text: "Und Josua segnete sie* und entließ sie*; und sie gingen zu ihren Zelten*.", footnotes: ["℘ 2Mo 39,43; Lk 24,50", "℘ Kap. 24,28; 2Sam 6,18.20; 1Kö 8,66", "℘ 1Sam 10,25; 13,2"] },
      { number: 7, text: "Dem halben Stamm Manasse hatte Mose in Baschan ein Erbteil gegeben*; aber seiner anderen Hälfte gab Josua ein Erbteil bei ihren Brüdern jenseits des Jordan, nach Westen zu*. Und als Josua sie in ihre Zelte entließ, segnete er sie*", footnotes: ["℘ 4Mo 32,33", "℘ Kap. 17,5", "℘ 2Mo 39,43; Lk 24,50"] },
      { number: 8, text: "und sagte zu ihnen: Kehrt zu euren Zelten zurück mit großem Reichtum und mit sehr viel Vieh, mit Silber und mit Gold und mit Bronze und mit Eisen und mit Kleidern in großer Menge! Teilt die Beute eurer Feinde mit euren Brüdern*!", footnotes: ["℘ 4Mo 31,27"] },
      { number: 9, text: "Da kehrten die Söhne Ruben und die Söhne Gad und der halbe Stamm Manasse zurück und zogen fort von den Söhnen Israel, von Silo, das im Land Kanaan liegt, um ins Land Gilead*, in das Land ihres Eigentums zu ziehen, in dem sie sich ansässig gemacht hatten auf Befehl des HERRN durch Mose*.", heading: "Der Erinnerungsaltar am Jordan", footnotes: ["℘ 5Mo 3,20; 34,1; Ri 20,1; 1Chr 5,9", "w. aufgrund des Mundes des HERRN durch die Hand des Mose\n℘ 4Mo 32,20-29; 5Mo 3,18-20"] },
      { number: 10, text: "Und als sie in die Bezirke des Jordan* kamen, die noch im Land Kanaan liegen, da bauten die Söhne Ruben und die Söhne Gad und der halbe Stamm Manasse dort einen Altar* am Jordan, einen Altar, groß von Aussehen.", footnotes: ["o. nach Gelilot am Jordan; o. zu den Gelilot des Jordan; entsprechend V. 11.", "℘ 1Mo 12,7.8"] },
      { number: 11, text: "Und die Söhne Israel hörten sagen: Siehe, die Söhne Ruben und die Söhne Gad und der halbe Stamm Manasse haben den Altar gebaut vor das Land Kanaan in den Bezirken des Jordan nach der Seite der Söhne Israel*.", footnotes: ["o. gegen das Land Kanaan hin . . . den Söhnen Israel gegenüber\n℘ 3Mo 17,8.9; 5Mo 12,11-14"] },
      { number: 12, text: "Und als die Söhne Israel es hörten, versammelte sich die ganze Gemeinde der Söhne Israel nach Silo, um gegen sie zum Krieg* hinaufzuziehen*.", footnotes: ["w. Heerlager", "℘ Ri 20,1.2"] },
      { number: 13, text: "Und die Söhne Israel sandten zu den Söhnen Ruben und zu den Söhnen Gad und zu dem halben Stamm Manasse, ins Land Gilead*, Pinhas*, den Sohn des Priesters Eleasar*,", footnotes: ["℘ 4Mo 32,1", "℘ 2Mo 6,25; 1Chr 9,20", "o. den Priester Pinhas, den Sohn des Eleasar"] },
      { number: 14, text: "und zehn Fürsten mit ihm, je einen Fürst für ein Vaterhaus von allen Stämmen Israels. Und jeder von ihnen war das Haupt seines Vaterhauses in den Tausendschaften Israels*.", footnotes: ["℘ 4Mo 1,4"] },
      { number: 15, text: "Und sie kamen zu den Söhnen Ruben und zu den Söhnen Gad und zu dem halben Stamm Manasse ins Land Gilead und redeten mit ihnen:" },
      { number: 16, text: "So spricht die ganze Gemeinde des HERRN: Was ist das für eine Untreue, die ihr gegen den Gott Israels geübt habt, dass ihr euch heute abwendet von dem HERRN*, indem ihr euch einen Altar baut, um euch heute gegen den HERRN aufzulehnen*?", footnotes: ["w. von der Nachfolge hinter dem HERRN her", "℘ 3Mo 17,8.9; 5Mo 12,11-14"] },
      { number: 17, text: "Haben wir noch nicht genug an der Sünde mit Peor*, von der wir uns bis zum heutigen Tag noch nicht gereinigt haben —, worauf doch die Plage über die Gemeinde des HERRN kam?*", footnotes: ["w. Ist uns die Sünde des Peor (d. i. Baal-Peor) zu wenig?", "℘ 4Mo 25,3-9; 5Mo 4,3"] },
      { number: 18, text: "Und ihr, ihr wendet euch heute vom HERRN* ab! Und es wird geschehen, wenn ihr euch heute gegen den HERRN auflehnt, dann wird er morgen über die ganze Gemeinde Israels zürnen*.", footnotes: ["w. von der Nachfolge hinter dem HERRN her", "℘ 4Mo 16,22; 32,15"] },
      { number: 19, text: "Jedoch wenn das Land, das euch gehört*, unrein ist, dann kommt herüber in das Land, das dem HERRN gehört*, wo die Wohnung des HERRN steht*, und macht euch unter uns ansässig! Aber gegen den HERRN dürft ihr euch nicht auflehnen, und auch gegen uns dürft ihr euch nicht auflehnen, indem ihr euch einen Altar baut neben dem Altar des HERRN, unseres Gottes.", footnotes: ["w. das Land eures Eigentums", "w. das Land des Eigentums des HERRN", "℘ Kap. 18,1; 2Mo 15,17"] },
      { number: 20, text: "Hat nicht Achan, der Sohn Serachs, Untreue an dem Gebannten geübt? Und über die ganze Gemeinde Israels erging der Zorn*; und er kam nicht als Einziger wegen seiner Schuld um*.", footnotes: ["℘ Kap. 7,1.5.24.25", "℘ 3Mo 17,8.9; 5Mo 12,11-14"] },
      { number: 21, text: "Und die Söhne Ruben und die Söhne Gad und der halbe Stamm Manasse antworteten und redeten zu den Häuptern der Tausendschaften Israels:" },
      { number: 22, text: "Der Gott der Götter*, der HERR, der Gott der Götter*, der HERR, er weiß es*, und Israel soll es wissen: Wenn das in Auflehnung oder in Untreue gegen den HERRN geschehen ist, dann sollst du uns heute nicht retten*.", footnotes: ["℘ 5Mo 10,17; Ps 136,2; Dan 2,47", "℘ 3Mo 17,8.9; 5Mo 12,11-14", "℘ 1Sam 2,3; 1Kö 8,39; Ps 44,22; Joh 21,17", "LXX, syr. und lat. Üs. schreiben: so soll er uns heute nicht retten\n℘ Hi 31,5-8"] },
      { number: 23, text: "Und wenn es so ist, dass wir uns einen Altar gebaut haben, um uns vom HERRN* abzuwenden, und wenn es geschehen ist, um Brandopfer und Speisopfer darauf zu opfern, und wenn es geschehen ist, um Heilsopfer* darauf darzubringen, dann möge uns der HERR zur Rechenschaft ziehen*!", footnotes: ["w. von der Nachfolge hinter dem HERRN her", "o. Friedensopfer; o. Abschlussopfer; o. Gemeinschaftsopfer", "w. der HERR — er möge es fordern\n℘ 5Mo 18,19; 1Sam 20,16; 2Chr 24,22"] },
      { number: 24, text: "Vielmehr taten wir dies aus Besorgnis, aus einem bestimmten Grund, als wir uns sagten: Künftig werden eure Söhne zu unseren Söhnen sagen: Was habt ihr mit dem HERRN, dem Gott Israels, zu tun?" },
      { number: 25, text: "Der HERR hat ja eine Grenze zwischen uns und euch gesetzt, ihr Söhne Ruben und ihr Söhne Gad, nämlich den Jordan. Ihr habt keinen Anteil am HERRN*! So könnten eure Söhne unsere Söhne davon abbringen, den HERRN zu fürchten.", footnotes: ["℘ Ps 16,5"] },
      { number: 26, text: "Darum sagten wir: Wir wollen uns daranmachen, den Altar zu bauen, nicht für Brandopfer und nicht für Schlachtopfer," },
      { number: 27, text: "sondern ein Zeuge soll er sein* zwischen uns und euch und zwischen unseren Generationen nach uns, damit wir den Dienst des HERRN vor ihm verrichten mit unseren Brandopfern und mit unseren Schlachtopfern und mit unseren Heilsopfern* und damit nicht eure Söhne künftig zu unseren Söhnen sagen: Ihr habt keinen Anteil am HERRN*!", footnotes: ["℘ Kap. 24,27; 1Mo 31,48.52; Jes 19,19.20", "o. Friedensopfer; o. Abschlussopfer; o. Gemeinschaftsopfer", "℘ Ps 16,5"] },
      { number: 28, text: "Und wir sagten uns: Geschieht es, dass sie künftig zu uns oder zu unseren nachfolgenden Generationen in dieser Weise sprechen, dann werden wir antworten: Seht die Nachbildung* des Altars des HERRN, die unsere Väter gemacht haben, und zwar nicht für Brandopfer und nicht für Schlachtopfer, sondern ein Zeuge soll sie sein* zwischen uns und euch!", footnotes: ["w. Ebenbild. — Andere üs.: die Bauweise", "℘ Kap. 24,27; 1Mo 31,48.52; Jes 19,19.20"] },
      { number: 29, text: "Fern von uns sei es*, uns gegen den HERRN aufzulehnen und uns heute vom HERRN* abzuwenden*, indem wir einen Altar bauen für Brandopfer, für Speisopfer und für Schlachtopfer neben dem Altar des HERRN, unseres Gottes, der vor seiner Wohnung steht*!", footnotes: ["w. Etwas Entweihtes sei es uns", "w. von der Nachfolge hinter dem HERRN her", "℘ Kap. 24,16", "℘ 5Mo 12,11-14"] },
      { number: 30, text: "Und als der Priester Pinhas und die Fürsten der Gemeinde und die Häupter der Tausendschaften Israels, die bei ihm waren, die Worte hörten, die die Söhne Ruben und die Söhne Gad und die Söhne Manasse redeten, war es gut in ihren Augen." },
      { number: 31, text: "Und Pinhas, der Sohn des Priesters Eleasar*, sagte zu den Söhnen Ruben und zu den Söhnen Gad und zu den Söhnen Manasse: Heute erkennen wir, dass der HERR in unserer Mitte ist*, weil ihr diese Untreue am HERRN nicht geübt habt*. Nun habt ihr die Söhne Israel vor der Hand des HERRN gerettet.", footnotes: ["o. der Priester Pinhas, der Sohn des Eleasar", "℘ Kap. 3,10; 3Mo 26,11", "℘ 2Kor 7,11"] },
      { number: 32, text: "Da kehrten Pinhas, der Sohn des Priesters Eleasar*, und die Fürsten zurück von den Söhnen Ruben und von den Söhnen Gad, aus dem Land Gilead ins Land Kanaan, zu den Söhnen Israel und brachten ihnen Antwort.", footnotes: ["o. der Priester Pinhas, der Sohn des Eleasar"] },
      { number: 33, text: "Und die Sache war gut in den Augen der Söhne Israel. Und die Söhne Israel dankten Gott* und sprachen nicht mehr davon, gegen sie hinaufzuziehen zum Krieg*, um das Land zu vernichten*, in dem die Söhne Ruben und die Söhne Gad wohnten.", footnotes: ["℘ 1Sam 25,32", "w. Heerlager", "℘ Spr 25,25"] },
      { number: 34, text: "Und die Söhne Ruben und die Söhne Gad nannten den Altar »Zeuge«*, indem sie sagten: Denn Zeuge ist er zwischen uns*, dass der HERR Gott ist.", footnotes: ["Der Name fehlt im Mas. T.", "℘ Kap. 24,27; 1Mo 31,48.52; Jes 19,19.20"] },
    ]},
    { number: 23, verses: [
      { number: 1, text: "Und es geschah nach vielen Tagen, nachdem der HERR Israel Ruhe verschafft hatte vor allen seinen Feinden ringsumher* und Josua alt geworden und hochbetagt war*,", heading: "Josuas Abschiedspredigt", footnotes: ["℘ Kap. 21,44; 1Chr 23,25; 2Chr 14,1.6", "℘ Kap. 13,1; 1Sam 12,2; 1Kö 1,1"] },
      { number: 2, text: "da rief Josua ganz Israel zusammen, seine Ältesten und seine Häupter und seine Richter und seine Aufseher* und sagte zu ihnen: Ich bin alt geworden, und ich bin hochbetagt*.", footnotes: ["w. Schreiber; d. i. eine Beamtenbezeichnung\n℘ Kap. 24,1; 1Kö 8,1; 1Chr 23,2; 27,1", "℘ Kap. 13,1; 1Sam 12,2; 1Kö 1,1"] },
      { number: 3, text: "Und ihr, ihr habt alles gesehen*, was der HERR, euer Gott, allen diesen Nationen euretwegen* getan hat*. Denn der HERR, euer Gott, er ist es, der für euch gekämpft hat*.", footnotes: ["℘ 2Mo 19,4", "o. vor euch her", "℘ 5Mo 7,17-24", "℘ Kap. 10,14.42"] },
      { number: 4, text: "Seht, ich habe euch diese übrigen Nationen durchs Los als Erbteil zugeteilt nach euren Stämmen, vom Jordan an, sowie alle Nationen, die ich ausgerottet habe*, bis an das große Meer gegen Sonnenuntergang*.", footnotes: ["℘ Zef 3,6", "℘ Kap. 18,10"] },
      { number: 5, text: "Und der HERR, euer Gott, er selbst wird sie vor euch ausstoßen und sie vor euch vertreiben*. Und ihr werdet ihr Land in Besitz nehmen, wie der HERR, euer Gott, zu euch geredet hat*.", footnotes: ["℘ Kap. 13,6", "℘ 2Mo 34,11; 4Mo 33,53"] },
      { number: 6, text: "So haltet denn ganz fest daran, alles zu befolgen und zu tun, was in dem Buch des Gesetzes Moses geschrieben ist, dass ihr nicht davon abweicht, weder zur Rechten noch zur Linken*,", footnotes: ["℘ Kap. 1,7; 1Kö 2,3; 2Thes 2,15"] },
      { number: 7, text: "damit ihr nicht in diesen Nationen aufgeht, in denen, die bei euch übrig geblieben sind*! Den Namen ihrer Götter sollt ihr nicht nennen*! Ihr sollt nicht bei ihnen schwören*! Ihr sollt ihnen nicht dienen, und ihr sollt sie nicht anbeten*!*", footnotes: ["℘ 4Mo 33,55; Eph 5,11", "o. bekennen; o. preisen\n℘ 2Mo 20,5; 23,13; 2Kö 5,18; 17,12; 2Chr 7,19", "℘ 5Mo 6,13.14; Jer 5,7; Zef 1,5", "o. ihr sollt euch nicht vor ihnen niederwerfen", "℘ Kap. 13,1; 1Sam 12,2; 1Kö 1,1"] },
      { number: 8, text: "Sondern dem HERRN, eurem Gott, sollt ihr anhängen, so wie ihr es getan habt bis zum heutigen Tag*!", footnotes: ["℘ Kap. 22,5; 5Mo 4,4; 8,20; 13,5"] },
      { number: 9, text: "Und der HERR hat große und starke Nationen vor euch vertrieben*. Ihr aber — niemand hat vor euch standgehalten bis zum heutigen Tag*:", footnotes: ["℘ Kap. 24,18; 2Chr 20,7", "℘ 5Mo 11,23; 1Kö 21,26"] },
      { number: 10, text: "Ein Mann von euch jagt tausend*. Denn der HERR, euer Gott, er ist es, der für euch kämpft*, wie er zu euch geredet hat*.", footnotes: ["℘ 3Mo 26,8; 5Mo 32,30", "℘ 5Mo 3,22", "℘ 1Chr 5,20.22"] },
      { number: 11, text: "So achtet um eures Lebens willen* genau darauf*, den HERRN, euren Gott, zu lieben*!", footnotes: ["℘ 5Mo 4,9.15; Apg 20,28", "o. so achtet genau auf eure Seelen", "℘ 5Mo 30,16.20"] },
      { number: 12, text: "Denn wenn ihr euch abwendet* und euch an den Rest dieser Nationen hängt, an die, die bei euch übrig geblieben sind, und euch mit ihnen verschwägert* und in ihnen aufgeht und sie in euch,", footnotes: ["℘ Zef 1,6", "℘ 2Mo 34,16; Ri 14,3; Esr 9,1.2; 2Kor 6,14"] },
      { number: 13, text: "dann sollt ihr mit Sicherheit wissen, dass der HERR, euer Gott, nicht fortfahren wird, diese Nationen vor euch zu vertreiben*. Und sie werden euch dann zum Fangnetz und zur Falle werden*, zur Geißel in euren Flanken und zu Stacheln in euren Augen, bis ihr aus diesem guten Land weggerafft werdet, das der HERR, euer Gott, euch gegeben hat*.", footnotes: ["℘ Ri 2,3.21", "℘ 2Mo 23,33; 4Mo 33,55", "℘ 2Kö 17,18-23"] },
      { number: 14, text: "Und siehe, ich gehe heute den Weg der ganzen Erde*. Und ihr wisst* mit eurem ganzen Herzen und mit eurer ganzen Seele, dass auch nicht ein Wort hingefallen ist* von all den guten Worten, die der HERR, euer Gott, über euch geredet hat: Alle sind sie eingetroffen für euch; kein einziges Wort davon ist hingefallen*.", footnotes: ["℘ 1Kö 2,2; Hebr 9,27", "o. habt erkannt", "℘ Kap. 21,45", "℘ 2Mo 23,33; 4Mo 33,55"] },
      { number: 15, text: "Aber es wird geschehen: Wie jedes gute Wort über euch gekommen ist, das der HERR, euer Gott, zu euch geredet hat*, ebenso wird der HERR jedes böse Wort über euch kommen lassen, bis er euch aus diesem guten Land ausgerottet haben wird, das der HERR, euer Gott, euch gegeben hat*.", footnotes: ["℘ 3Mo 26,3-13", "℘ 3Mo 26,14-39; 1Kö 14,15; Hebr 6,6-8"] },
      { number: 16, text: "Wenn ihr den Bund des HERRN, eures Gottes, den er euch geboten hat, übertretet und hingeht und andern Göttern dient* und sie anbetet*, dann wird der Zorn des HERRN über euch entbrennen*, und ihr werdet schnell weggerafft aus dem guten Land, das er euch gegeben hat*.", footnotes: ["℘ 5Mo 17,3; Jes 24,5", "o. und euch vor ihnen niederwerft", "℘ 5Mo 28,15.45; Ri 2,14.20", "℘ 4Mo 33,56; 5Mo 4,26; 6,15; 1Sam 12,25; 1Kö 9,6.7"] },
    ]},
    { number: 24, verses: [
      { number: 1, text: "Und Josua versammelte alle Stämme Israels nach Sichem* und berief die Ältesten Israels, seine Häupter, seine Richter und seine Aufseher*. Und sie traten vor Gott*.", heading: "Rückblick und Bundeserneuerung bei Sichem", footnotes: ["℘ Kap. 20,7", "w. Schreiber; d. i. eine Beamtenbezeichnung\n℘ Kap. 23,2; 5Mo 29,9; 2Kö 23,1", "℘ Ri 20,26; 1Sam 10,19; Apg 10,33"] },
      { number: 2, text: "Und Josua sprach zu dem ganzen Volk: So spricht der HERR, der Gott Israels: Jenseits des Stroms* haben eure Väter vorzeiten gewohnt, und zwar Terach, der Vater Abrahams und der Vater Nahors*, und sie dienten andern Göttern*.", footnotes: ["d. i. der Euphrat", "℘ 1Mo 11,27", "℘ 1Mo 31,19"] },
      { number: 3, text: "Und ich nahm euren Vater Abraham von jenseits des Stroms und ließ ihn im ganzen Land Kanaan umherziehen*, und ich mehrte seine Nachkommen und gab ihm Isaak*.", footnotes: ["℘ 1Mo 12,1-9", "℘ 1Mo 21,2.3"] },
      { number: 4, text: "Und dem Isaak gab ich Jakob und Esau*, und dem Esau gab ich das Gebirge Seïr, es zu besitzen*. Jakob aber und seine Söhne zogen nach Ägypten hinab*.", footnotes: ["℘ 1Mo 25,24-26", "℘ 1Mo 36,8.9.43", "℘ 1Mo 46,1-7"] },
      { number: 5, text: "Und ich sandte Mose und Aaron* und schlug Ägypten, so wie ich es unter ihnen getan habe*; und danach führte ich euch heraus*.", footnotes: ["℘ 2Mo 6,27", "℘ 2Mo 7-12", "℘ 2Mo 12,41.51; Ps 105,43"] },
      { number: 6, text: "Und ich führte eure Väter aus Ägypten, und ihr kamt ans Meer*. Ägypten aber jagte euren Vätern mit Wagen und mit Reitern bis ans Schilfmeer nach*.", footnotes: ["℘ 2Mo 14,1", "℘ 2Mo 14,9"] },
      { number: 7, text: "Da schrien sie zum HERRN*, und er setzte Finsternis zwischen euch und die Ägypter* und ließ das Meer über sie kommen, und es bedeckte sie*. Und eure Augen haben gesehen, was ich an Ägypten getan habe*. Dann wohntet ihr eine lange Zeit in der Wüste*.", footnotes: ["℘ 2Mo 14,10", "℘ 2Mo 14,20.27.31", "o. und er (d. i. Gott) bedeckte sie\n℘ 2Mo 14,27.28", "℘ 2Mo 14,31; 5Mo 4,34.35", "℘ Kap. 5,6"] },
      { number: 8, text: "Und ich brachte euch in das Land der Amoriter, die jenseits des Jordan wohnten, und sie kämpften gegen euch*. Und ich gab sie in eure Hand, und ihr nahmt ihr Land ein, und ich rottete sie vor euch aus.", footnotes: ["℘ 2Mo 23,23; 4Mo 21,21-35; Am 2,9.10"] },
      { number: 9, text: "Da erhob sich Balak, der Sohn des Zippor, der König von Moab, und kämpfte gegen Israel. Und er sandte hin und ließ Bileam, den Sohn des Beor, rufen, euch zu verfluchen*.", footnotes: ["℘ 4Mo 22,2-6"] },
      { number: 10, text: "Aber ich wollte nicht auf Bileam hören, und er musste euch segnen*. Und ich rettete euch aus seiner Hand.", footnotes: ["o. und er segnete euch nachdrücklich\n℘ 4Mo 24,10; Mi 6,5"] },
      { number: 11, text: "Ihr habt den Jordan überschritten* und seid nach Jericho gekommen*. Aber die Bürger von Jericho, die Amoriter, die Perisiter, die Kanaaniter, die Hetiter, die Girgaschiter, die Hewiter und die Jebusiter* kämpften gegen euch*, und ich gab sie in eure Hand*.", footnotes: ["℘ Kap. 4,1.10.19", "℘ Kap. 9,2", "℘ Kap. 3,10", "℘ Kap. 3,10", "℘ Kap. 6-11"] },
      { number: 12, text: "Und ich schickte Entsetzen* vor euch her, und es vertrieb sie vor euch, die beiden Könige der Amoriter*; es geschah nicht durch dein Schwert und nicht durch deinen Bogen*.", footnotes: ["o. Hornissen", "℘ Kap. 2,10; 2Mo 23,28; 4Mo 21,32.32; 5Mo 4,46.47; 31,4; Ps 135,11", "℘ Ps 44,4; 80,10"] },
      { number: 13, text: "Und ich gab euch ein Land, um das du dich nicht gemüht hattest, und Städte, die ihr nicht gebaut hattet und in denen ihr nun doch wohnt*. Von Weinbergen und Ölbäumen, die ihr nicht gepflanzt habt, esst ihr*. —", footnotes: ["℘ Kap. 11,13; 5Mo 19,1", "℘ 5Mo 6,11"] },
      { number: 14, text: "So fürchtet nun den HERRN und dient ihm in Aufrichtigkeit und Treue*! Und tut die Götter weg*, denen eure Väter jenseits des Stroms und in Ägypten gedient haben*, und dient dem HERRN*!", footnotes: ["o. Wahrheit; o. Zuverlässigkeit\n℘ 1Sam 12,24; Mi 6,8", "℘ 1Mo 35,2; Ps 81,10", "℘ Hes 20,7.8", "℘ 5Mo 6,13; Mt 6,24"] },
      { number: 15, text: "Ist es aber übel in euren Augen, dem HERRN zu dienen, dann erwählt euch heute, wem ihr dienen wollt*: entweder den Göttern, denen eure Väter gedient haben, als sie noch jenseits des Stroms waren, oder den Göttern der Amoriter, in deren Land ihr wohnt*! Ich aber und mein Haus, wir wollen dem HERRN dienen*!", footnotes: ["℘ 1Kö 18,21", "℘ Hes 20,39", "℘ 2Mo 23,2"] },
      { number: 16, text: "Da antwortete das Volk und sagte: Fern von uns sei es*, den HERRN zu verlassen, um anderen Göttern zu dienen*!", footnotes: ["w. Etwas Entweihtes sei es uns", "℘ Kap. 22,29; Ps 119,106.113"] },
      { number: 17, text: "Denn der HERR, unser Gott*, er ist es, der uns und unsere Väter aus dem Land Ägypten, aus dem Sklavenhaus, heraufgeführt hat* und der vor unseren Augen diese großen Zeichen getan* und uns behütet hat auf dem ganzen Weg, den wir gingen, und unter all den Völkern, deren Mitte wir durchzogen*.", footnotes: ["℘ 2Chr 13,10", "℘ 2Mo 13,3.14", "℘ 5Mo 7,19; 29,2", "℘ 5Mo 32,9-12"] },
      { number: 18, text: "Und der HERR hat alle Völker und die Amoriter, die Bewohner des Landes, vor uns vertrieben*. Auch wir wollen dem HERRN dienen, denn er ist unser Gott*!", footnotes: ["℘ Kap. 23,9; Apg 7,45", "℘ 5Mo 10,21"] },
      { number: 19, text: "Da sagte Josua zum Volk: Ihr könnt dem HERRN nicht dienen. Denn er ist ein heiliger Gott*, er ist ein eifersüchtiger Gott*. Er wird euer Vergehen und eure Sünden nicht vergeben*.", footnotes: ["℘ 3Mo 11,45; Ps 99,3.9", "℘ 2Mo 20,5", "℘ 2Mo 23,21; Jes 2,9"] },
      { number: 20, text: "Verlasst ihr den HERRN und dient fremden Göttern*, dann wird er sich wenden und euch Böses antun und euch vernichten, nachdem er euch Gutes getan hat*.", footnotes: ["w. Göttern der Fremde", "℘ 1Sam 12,25; 1Chr 28,8.9; 2Chr 15,2"] },
      { number: 21, text: "Und das Volk antwortete Josua: Nein, sondern dem HERRN wollen wir dienen*!", footnotes: ["℘ 2Mo 24,3.7"] },
      { number: 22, text: "Da sagte Josua zum Volk: Ihr seid Zeugen gegen euch selbst, dass ihr selbst euch den HERRN erwählt habt, um ihm zu dienen*. Und sie sprachen: Wir sind Zeugen!", footnotes: ["℘ 5Mo 26,17"] },
      { number: 23, text: "So tut nun die fremden Götter* weg*, die unter euch sind, und neigt euer Herz zum HERRN, dem Gott Israels!", footnotes: ["w. die Götter der Fremde", "℘ 1Mo 35,2; Ps 81,10"] },
      { number: 24, text: "Und das Volk sagte zu Josua: Dem HERRN, unserem Gott, wollen wir dienen, und auf seine Stimme wollen wir hören*!", footnotes: ["℘ 2Mo 19,8; 2Chr 15,14"] },
      { number: 25, text: "Und Josua schloss einen Bund* für das Volk an diesem Tag und setzte ihm Ordnung und Recht in Sichem fest*.", footnotes: ["℘ 5Mo 29,11; 2Kö 11,17; 2Chr 15,12", "℘ 2Mo 15,25"] },
      { number: 26, text: "Und Josua schrieb diese Worte in das Buch des Gesetzes Gottes*. Und er nahm einen großen Stein und richtete ihn dort auf* unter der Terebinthe, die bei dem Heiligtum des HERRN steht*.", footnotes: ["℘ 2Mo 24,4", "℘ 1Mo 28,18", "℘ 1Mo 35,4; Ri 9,6"] },
      { number: 27, text: "Und Josua sagte zum ganzen Volk: Siehe, dieser Stein soll Zeuge gegen uns sein*; denn er hat alle Worte des HERRN gehört, die er mit uns geredet hat. Und er soll Zeuge gegen euch sein*, damit ihr euren Gott nicht verleugnet*.", footnotes: ["℘ Kap. 22,28.34; 5Mo 31,19.26", "℘ 2Mo 19,8; 2Chr 15,14", "℘ Mt 26,72.74"] },
      { number: 28, text: "Und Josua entließ das Volk, jeden in sein Erbteil*.", footnotes: ["℘ Kap. 22,6; 4Mo 36,7.9; Ri 2,6; Neh 11,20"] },
      { number: 29, text: "Und es geschah nach diesen Dingen, dass Josua, der Sohn des Nun, der Knecht des HERRN, im Alter von 110 Jahren starb*.", heading: "Josuas und Eleasars Tod — Beisetzung der Gebeine Josefs", footnotes: ["℘ 1Mo 50,26; Ri 2,8"] },
      { number: 30, text: "Und man begrub ihn im Gebiet seines Erbteils in Timnat-Serach, das im Gebirge Ephraim liegt, nördlich vom Berg Gaasch*.", footnotes: ["℘ Kap. 19,50; Ri 17,1; 2Sam 23,30"] },
      { number: 31, text: "Und Israel diente dem HERRN alle Tage Josuas und alle Tage der Ältesten, die Josua überlebten* und die das ganze Werk des HERRN kannten, das er für Israel getan hatte*.", footnotes: ["w. die ihre Tage nach Josua verlängerten", "℘ 5Mo 11,2-7; Ri 2,7; 2Chr 34,33"] },
      { number: 32, text: "Und die Gebeine Josefs, die die Söhne Israel aus Ägypten heraufgebracht hatten*, begruben sie in Sichem auf dem Feldstück, das Jakob von den Söhnen Hamors, des Vaters von Sichem, für hundert Kesita* gekauft hatte*; und es wurde* den Söhnen Josef zum Erbteil*.", footnotes: ["℘ 1Mo 50,25", "d. i. ein altes Gewicht", "℘ 1Mo 33,19; Apg 7,16", "w. sie wurden", "℘ 1Mo 48,22; Joh 4,5"] },
      { number: 33, text: "Und Eleasar, der Sohn Aarons*, starb. Und sie begruben ihn auf dem Hügel seines Sohnes Pinhas*, der ihm* auf dem Gebirge Ephraim gegeben worden war.", footnotes: ["℘ 4Mo 20,28", "℘ 2Mo 6,25", "o. in Gibea, der Stadt seines Sohnes Pinhas, die ihm"] },
    ]},
  ]
};
